function renderNav(){
  document.getElementById('nav').innerHTML=NAV.filter(function(n){return n.k&&!n.hide&&(!n.vis||n.vis())}).map(function(n){
    return '<button type="button" class="ess-workflow-nav-item'+(page===n.k?' active':'')+'"'+(page===n.k?' aria-current="page"':'')+' title="'+n.l+'" onclick="workflowNavigate(\''+n.k+'\')"><span>'+n.l+'</span></button>';
  }).join('');
  NAVPIP();
}
function NAVPIP(){
  var p=document.getElementById('pipCount'); if(!p) return;
  var v=(typeof navPipCount==='function')?navPipCount():0;
  if(v>0){ p.textContent=v; p.hidden=false; } else { p.hidden=true; }
}
var TITLES={'instance':'Workflow instances'};
function go(k){
  document.getElementById('view').dataset.uiScreen=k;
  page=k; renderNav();
  document.getElementById('view').className='content'+(k==='thiet-ke'?' wide':'');
  var t=(NAV.filter(function(n){return n.k===k})[0]||{}).l||'';
  var cr=document.getElementById('crumb'); if(cr) cr.textContent=TITLES[k]||t;
  window.scrollTo(0,0);
  PAGES[k]();
}


