function subChip(x){
  if(x.sub==='Faulted') return '<span class="chip c-rej">Faulted</span>';
  if(x.sub==='Cancelled') return '<span class="chip c-draft">Cancelled</span>';
  if(x.sub==='Suspended') return '<span class="chip c-wait">Suspended</span>'+(x.late?' <span class="chip c-rej nb">overdue</span>':'');
  return '<span class="chip c-done">Finished</span>';
}




