var FT={text:'Single line',area:'Multi-line',num:'Number',money:'Amount',date:'Date',time:'Time',
 select:'Dropdown',radio:'Choose one',check:'Checkbox',file:'File attachment',
 user:'User picker',ro:'Read-only / calculated'};



var BC_STEPS=[3,4,6,8,9,12];
function bcType(t){ return ({textarea:'area',readonly:'ro'})[t]||t }
function bcIsData(f){ var t=bcType(f.t); return t!=='section'&&t!=='note'&&t!=='divider' }

function bcFull(f){ var t=bcType(f.t); return t==='section'||t==='divider' }
function bcDefW(f){ var t=bcType(f.t); return (bcFull(f)||t==='area'||t==='file'||t==='table'||t==='radio'||t==='check'||t==='note')?12:6 }
function bcW(f){ if(bcFull(f)) return 12; var w=Math.round(+f.w); return (w>=2&&w<=12)?w:bcDefW(f) }

function bcRows(form,skip){
  var out=[],cur=null;
  (form||[]).forEach(function(f,i){
    if(skip&&skip(f)) return;
    var t=bcType(f.t);
    if(t==='section'||t==='divider'){ out.push({k:t,items:[{f:f,i:i,w:12}]}); cur=null; return }
    var w=bcW(f);
    if(!cur||f.nl||cur.sum+w>12||cur.items.length>=4){ cur={k:'row',items:[],sum:0}; out.push(cur) }
    cur.items.push({f:f,i:i,w:w}); cur.sum+=w;
  });
  return out;
}

function bcNote(s){
  return esc(s||'').replace(/\*\*(.+?)\*\*/g,'<b>$1</b>').replace(/\*(.+?)\*/g,'<i>$1</i>')
    .replace(/\[(.+?)\]\((https?:\/\/[^)\s]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
}
var BC_FILE='<svg viewBox="0 0 24 24"><path d="M14 3v4a1 1 0 0 0 1 1h4"/><path d="M17 21H7a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h7l5 5v11a2 2 0 0 1-2 2z"/></svg>';

function bcRoVal(f,o){
  var t=bcType(f.t), v=o.val?o.val(f):'';
  if(t==='file'){
    var fs=o.files?o.files(f):[];
    return fs.length?fs.map(function(x){
      return '<a class="bc-file" href="javascript:void(0)" onclick="'+(o.fileClick?o.fileClick(x):'')+'">'+BC_FILE+esc(x.n||x)+'</a>';
    }).join(''):'<span class="bc-empty">—</span>';
  }
  if(v===undefined||v===null||String(v).trim()==='') return '<span class="bc-empty">—</span>';
  if(t==='area') return '<span class="bc-pre">'+esc(v)+'</span>';
  return esc(v);
}

function bcRender(form,o){
  o=o||{};
  var ro=o.mode==='ro';
  var skip=function(f){
    if(bcType(f.t)==='note'&&ro&&!f.ro) return true;     
    return o.skip?o.skip(f):false;
  };
  var rows=bcRows(form,skip);
  if(!rows.length) return o.empty||'';
  return '<div class="bc'+(ro?' bc-ro':'')+'">'+rows.map(function(r){
    var f0=r.items[0].f;
    if(r.k==='section') return '<div class="bc-sec">'+esc(f0.l||'Section header')+'</div>';
    if(r.k==='divider') return '<hr class="bc-hr">';
    return '<div class="bc-row">'+r.items.map(function(it){
      var f=it.f, t=bcType(f.t), cls='bc-c'+(f.bl?' bl':''), st=' style="grid-column:span '+it.w+'"';
      if(t==='note') return '<div class="'+cls+'"'+st+'><div class="bc-note '+(f.tone==='warn'?'warn':'info')+'">'+bcNote(f.text)+'</div></div>';
      if(ro) return '<div class="'+cls+'"'+st+'><div class="bc-lb">'+esc(f.l)+'</div><div class="bc-v">'+bcRoVal(f,o)+'</div></div>';
      return '<div class="'+cls+'"'+st+'>'+o.input(f)+'</div>';
    }).join('')+'</div>';
  }).join('')+'</div>';
}

function bcPairs(fi){
  var form=[],val={};
  (fi||[]).forEach(function(p,i){
    var k='p'+i, long=String(p[1]).length>48;
    form.push({k:k,l:p[0],t:long?'area':'text'}); val[k]=p[1];
  });
  return {form:form,val:val};
}

function bcApprovals(sp,whoFmt){
  return (sp||[]).filter(function(s,i){ return i>0&&s.at&&(s.s==='done'||s.s==='rej')&&/approv|confirm/i.test(s.t) }).map(function(s){
    var note=s.note||'', kq=s.s==='rej'?'Reject':/^Request more/i.test(note)?'Request more info':/confirm/i.test(s.t)?'Confirmed':'Approved';
    var cls=s.s==='rej'?'rej':/^Request more/i.test(note)?'ask':'ok';
    return '<div class="bc-apl"><b>'+esc(s.t)+'</b> · '+(whoFmt?whoFmt(s):esc(s.w))+' · <b class="'+cls+'">'+kq+'</b> · <span class="num">'+esc(s.at)+'</span>'+
      (note?' · “'+esc(note.replace(/^Request more info:\s*/i,''))+'”':'')+'</div>';
  }).join('');
}


var LD=null, LD_SEQ=0;
var LD_ROLES=['System Administrator','Process Designer'];
function canDesign(){
  var me=userBy('admin');
  return !!(me&&me.tt&&me.vt.some(function(r){return LD_ROLES.indexOf(r)>=0}));
}
function bcDataCount(n){ return (n.form||[]).filter(bcIsData).length }
function ldNow(){ return '21/09/2026 '+new Date().toTimeString().slice(0,5) }
function ldClone(x){ return JSON.parse(JSON.stringify(x)) }
function ldNode(){ return LD?nodeById(LD.nid):null }


function ldInitLo(){
  Object.keys(DEFS).forEach(function(k){
    DEFS[k].nodes.forEach(function(n){ if(n.form&&!n._lo) n._lo=n.form.map(function(f){return f.k}) });
  });
}


function openLayout(){
  var n=fnode(); if(!n) return;
  if(n.t!=='start'&&n.t!=='task') return;
  if(!canDesign()){
    AUDIT.unshift({t:ldNow(),u:'admin',h:'Denied saving / opening the form layout',dt:DSN.id+' · node '+n.id+' — has no System Admin / Workflow Designer role',ip:'10.20.4.11',nc:0});
    return toast('No permission to design layouts','Only the System Administrator or Process Designer roles can open this screen');
  }
  if(!n._lo) n._lo=(n.form||[]).map(function(f){return f.k});
  LD={nid:n.id,form:ldClone(n.form||[]),pool:[],sel:null,hist:[],fut:[],chg:0,drag:null,modal:null,warn:(n._bcWarn||[]).slice()};
  var el=document.getElementById('ld');
  if(!el){ el=document.createElement('div'); el.id='ld'; el.className='ld'; el.setAttribute('role','dialog'); el.setAttribute('aria-modal','true'); document.body.appendChild(el) }
  el.classList.add('on'); document.body.style.overflow='hidden';
  ldDraw();
}
function ldShut(){
  var el=document.getElementById('ld'); if(el){ el.classList.remove('on'); el.innerHTML='' }
  document.body.style.overflow=''; LD=null;
}
function ldClose(){
  if(!LD) return;
  if(LD.chg>0){ LD.modal={k:'close'}; return ldDraw() }
  ldShut();
}


function ldSnapState(){ return JSON.stringify({f:LD.form,p:LD.pool}) }
function ldLoad(s){ var o=JSON.parse(s); LD.form=o.f; LD.pool=o.p }
function ldPush(){ LD.hist.push(ldSnapState()); if(LD.hist.length>50) LD.hist.shift(); LD.fut=[]; LD.chg++ }
function ldUndo(){ if(!LD.hist.length) return; LD.fut.push(ldSnapState()); ldLoad(LD.hist.pop()); LD.chg=Math.max(0,LD.chg-1); ldFixSel(); ldDraw() }
function ldRedo(){ if(!LD.fut.length) return; LD.hist.push(ldSnapState()); ldLoad(LD.fut.pop()); LD.chg++; ldFixSel(); ldDraw() }
function ldFixSel(){ if(LD.sel!==null&&!LD.form[LD.sel]) LD.sel=null }


function ldStarts(form){
  var s={}; bcRows(form).forEach(function(r){ s[r.items[0].i]=1 }); return s;
}
function ldFreeze(){
  var s=ldStarts(LD.form);
  LD.form.forEach(function(f,i){ if(i>0&&s[i]&&bcIsFlow(f)) f.nl=1 });
}
function bcIsFlow(f){ var t=bcType(f.t); return t!=='section'&&t!=='divider' }
function ldClean(){
  LD.form.forEach(function(f,i){
    if(!f.nl) return;
    if(i===0){ delete f.nl; return }
    var tmp=LD.form.map(function(x,j){ if(j!==i) return x; var c={}; for(var k in x) if(k!=='nl') c[k]=x[k]; return c });
    if(ldStarts(tmp)[i]) delete f.nl;
  });
}


function ldDraw(){
  var el=document.getElementById('ld'); if(!el||!LD) return;
  var n=ldNode(), d=def(), isTask=n.t==='task';
  var cvScroll=(document.getElementById('ldCv')||{}).scrollTop||0;
  var data=LD.form.map(function(f,i){return {f:f,i:i}}).filter(function(x){return bcIsData(x.f)});
  var lo=n._lo||[];
  var tasks=d.nodes.filter(function(x){return x.t==='task'}).map(function(x){return x.id});
  var shows=isTask?'Block C of the step’s approval screen <b>'+esc(n.id)+'</b> ('+esc(n.who||'')+')'
                  :'<b>Submit ticket</b> (input) · ticket details · block A at step <b>'+(tasks.length?esc(tasks.join(', ')):'—')+'</b> (read-only)';
  var narrow=window.innerWidth<1280;

  var pool=LD.pool;
  var left='<div class="ld-sec"><div class="ld-sh">Form fields <span class="num">('+(data.length+pool.length)+')</span></div>'+
    (pool.length?'<div class="ld-sub">Not placed</div>'+pool.map(function(f,j){
      return '<div class="ld-fi pool" role="button" tabindex="0" title="Drag onto the design canvas (or click to add at the end)" '+
        'onmousedown="ldStartNew(event,\'fld:'+j+'\')" onkeydown="if(event.key===\'Enter\')ldAddQuick(\'fld:'+j+'\')">'+
        '<span class="ld-grip">⠿</span><span class="ld-fl">'+esc(f.l)+(f.r?' <i>*</i>':'')+'</span>'+
        '<span class="ld-ft">'+(FT[f.t]||f.t)+'</span></div>';
    }).join(''):'')+
    (data.length?'<div class="ld-sub">Placed on the canvas</div>'+data.map(function(x){
      var f=x.f, isNew=lo.indexOf(f.k)<0;
      return '<button class="ld-fi'+(LD.sel===x.i?' on':'')+'" onclick="ldPick('+x.i+',1)">'+
        '<span class="ld-fl">'+esc(f.l)+(f.r?' <i>*</i>':'')+'</span>'+(isNew?'<span class="ld-new">New</span>':'')+
        '<span class="ld-ft">'+(FT[f.t]||f.t)+'</span></button>';
    }).join(''):'')+
    (!data.length&&!pool.length?'<div class="ld-empty">No fields yet.</div>':'')+
    '</div>'+
    '<div class="ld-sec"><div class="ld-sh">Presentation</div>'+
    [['section','Section header','<path d="M4 6h16M4 12h10"/>','Header strip that groups fields'],
     ['divider','Divider','<path d="M3 12h18"/>','Divider between groups'],
     ['bl','Column divider','<path d="M12 3v18"/><path d="M4 8h5M15 8h5M4 16h5M15 16h5"/>','Drop onto a field to draw a vertical divider on its left']].map(function(p){
      return '<div class="ld-pal" role="button" tabindex="0" title="'+p[3]+' — drag onto the canvas or click to add" '+
        'onmousedown="ldStartNew(event,\''+p[0]+'\')" onkeydown="if(event.key===\'Enter\')ldAddQuick(\''+p[0]+'\')">'+
        svg(p[2])+'<div><b>'+p[1]+'</b></div></div>';
    }).join('')+'</div>';

  var paper;
  if(isTask){
    var st=d.nodes.filter(function(x){return x.t==='start'})[0];
    paper='<div class="ld-blk lock"><div class="ld-bh"><span class="ld-bt">A. Employee’s ticket</span>'+
      ''+
      (st?'<button class="link" style="margin-left:auto" onclick="ldGoStart()">Open the Submit ticket node layout →</button>':'')+'</div>'+
      '<div class="ld-bb">'+(st?bcRender(st.form,{mode:'ro',val:ldSample,files:ldSampleFiles,empty:'<div class="ld-empty">The Submit ticket node has no fields.</div>'}):'')+'</div></div>'+
      '<div class="ld-blk ph"><div class="ld-bh"><span class="ld-bt">B. Previous approvals</span></div>'+
      '<div class="ld-bb">'+ldApprovedSample()+'</div></div>'+
      '<div class="ld-blk edit"><div class="ld-bh"><span class="ld-bt">C. This step’s part</span></div>'+
      '<div class="ld-bb">'+ldGridHTML()+'</div></div>';
  } else {
    paper='<div class="ld-blk edit"><div class="ld-bh"><span class="ld-bt">Ticket information</span></div>'+
      '<div class="ld-bb">'+ldGridHTML()+'</div></div>';
  }

  el.innerHTML=
   '<div class="ld-top"><h2>Layout design — '+esc(n.name)+'</h2>'+
   '<span class="chip c-brand nb">'+NT[n.t].n+'</span>'+
   '<button class="x-btn" onclick="ldClose()" aria-label="Close designer">'+svg(I.x)+'</button></div>'+
   (narrow
    ?'<div class="ld-narrow"><div class="empty">'+svg('<rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 21h8M12 18v3"/>')+
      '<b>The window is narrower than the minimum</b><p>The layout designer needs a browser window at least <span style="font-weight:600;color:var(--ink)">1280px</span> (currently '+window.innerWidth+'px). '+
      'Widen or maximise the window; the screen comes back when it is wide enough.</p></div></div>'
    :'<div class="ld-body"><aside class="ld-left">'+left+'</aside>'+
      '<main class="ld-cv" id="ldCv" onmousedown="ldBlank(event)"><div class="ld-paper">'+paper+'</div></main>'+
      '<aside class="ld-right" id="ldProps">'+ldPropsHTML()+'</aside></div>')+
   '<div class="ld-foot">'+
   '<button class="btn" onclick="ldNewBlank()"'+(narrow?' disabled':'')+'>'+svg('<path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 4v5h5"/>')+tx('Làm lại','Start over')+'</button>'+
   '<button class="btn" style="margin-left:auto" onclick="ldClose()">Cancel</button>'+
   '<button class="btn pri" onclick="ldSave()"'+(narrow?' disabled':'')+'>'+svg(I.save)+'Save layout</button></div>'+
   (LD.modal?ldModalHTML():'');
  var cv=document.getElementById('ldCv'); if(cv) cv.scrollTop=cvScroll;
}


function ldGridHTML(){
  var n=ldNode(), lo=n._lo||[];
  var rows=bcRows(LD.form);
  var body=rows.map(function(r,ri){
    var one=r.k!=='row';
    return '<div class="ld-row'+(one?' one':'')+'" data-r="'+ri+'">'+r.items.map(function(it){
      var f=it.f, i=it.i, t=bcType(f.t), sel=LD.sel===i, isNew=bcIsData(f)&&lo.indexOf(f.k)<0;
      var inner;
      if(t==='section') inner='<div class="bc-sec">'+esc(f.l||'Section header')+'</div>';
      else if(t==='divider') inner='<hr class="bc-hr">';
      else if(t==='note') inner='<div class="bc-note '+(f.tone==='warn'?'warn':'info')+'">'+bcNote(f.text)+
        (f.ro?'':'<span class="ld-tag">hidden when viewing the ticket</span>')+'</div>';
      else inner=ldCtl(f);
      return '<div class="ld-it'+(sel?' sel':'')+(isNew?' new':'')+(f.bl?' bl':'')+(one?' one':'')+'" data-i="'+i+'" style="grid-column:span '+it.w+'" '+
        'onmousedown="ldItemDown(event,'+i+')" tabindex="-1">'+
        '<span class="ld-h" title="Drag to move" onmousedown="ldStartMove(event,'+i+')">⠿</span>'+
        '<span class="ld-w num">'+(one?'Full row':it.w+'/12')+'</span>'+
        '<button class="ld-x" title="Remove from layout (Delete)" aria-label="Remove from layout" onmousedown="event.stopPropagation()" onclick="event.stopPropagation();LD.sel='+i+';ldDel()">'+svg(I.trash)+'</button>'+
        (one?'':'<span class="ld-rs l" title="Drag left to widen, right to narrow" onmousedown="ldStartResize(event,'+i+',\'l\')"></span>'+
                '<span class="ld-rs" title="Drag right to widen, left to narrow" onmousedown="ldStartResize(event,'+i+',\'r\')"></span>')+
        (t==='area'?'<span class="ld-rb" title="Drag up / down to change the height (rows)" onmousedown="ldStartRows(event,'+i+')"></span>':'')+
        '<div class="ld-in">'+inner+'</div></div>';
    }).join('')+'</div>';
  }).join('');
  return '<div class="ld-grid" id="ldGrid">'+
    '<div class="ld-cols">'+Array(13).join('<i></i>')+'</div>'+
    (body||'<div class="ld-emptyz">'+svg('<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>')+'<b>The canvas is empty</b><span>Drag fields from the list on the left to start designing.</span></div>')+
    '<div class="ld-endz">Drop here to place at the end of the form</div>'+
    '<div class="ld-ind" id="ldInd"></div></div>';
}

function ldCtl(f){
  var t=bcType(f.t), box;
  var fake=function(txt,cls){ return '<div class="inp ld-fake'+(cls?' '+cls:'')+'">'+txt+'</div>' };
  if(t==='area') box='<div class="inp ld-fake ld-ta" style="height:'+((+f.rows||3)*20+18)+'px"></div>';
  else if(t==='select') box=fake('— Choose —','sel');
  else if(t==='user') box=fake('— Choose a user —','sel');
  else if(t==='date') box=fake('dd/mm/yyyy');
  else if(t==='time') box=fake('--:--');
  else if(t==='money') box=fake('0 VND');
  else if(t==='ro') box=fake('(calculated by the system)','ro');
  else if(t==='radio') box='<div class="ld-opts">'+(f.o||'').split('\n').filter(Boolean).map(function(o){return '<span><i class="rd"></i>'+esc(o)+'</span>'}).join('')+'</div>';
  else if(t==='check') box='<div class="ld-opts"><span><i class="cb"></i>'+esc(f.l)+'</span></div>';
  else if(t==='file') box='<div class="ld-file">'+svg('<path d="M12 16V4"/><path d="M7 9l5-5 5 5"/><path d="M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2"/>')+
    'Drag files here or click to choose · or paste a link</div>';
  else box=fake('');
  return '<div class="field"><label>'+esc(f.l)+(f.r?' <span style="color:var(--danger)">*</span>':'')+'</label>'+box+'</div>';
}
var LD_MAU={loaiNghi:'Annual leave',tuNgay:'14/09/2026',denNgay:'16/09/2026',buoi:'Full day',
  banGiao:'Lê Thị Mai (NV-00398)',lyDo:'Going back to my hometown for family matters as planned with my family.'};
function ldSample(f){ return LD_MAU[f.k]!==undefined?LD_MAU[f.k]:(typeof PRM_MAU!=='undefined'&&PRM_MAU[f.k])||'' }
function ldSampleFiles(f){ return [{n:(typeof PRM_MAU!=='undefined'&&/\.[a-z]{3,4}$/.test(PRM_MAU[f.k]||''))?PRM_MAU[f.k]:'attachment.pdf'}] }


function ldSeg(vals,cur,fn,dis){
  return '<div class="ld-seg'+(dis?' dis':'')+'">'+vals.map(function(v){
    return '<button class="'+(String(v[0])===String(cur)?'on':'')+'"'+(dis?' disabled':'')+' onclick="'+fn+'('+JSON.stringify(v[0]).replace(/"/g,'&quot;')+')">'+v[1]+'</button>';
  }).join('')+'</div>';
}
function ldIsOverride(f){ return (f.w!==undefined&&+f.w!==bcDefW(f))||!!f.nl||!!f.bl||(f.rows!==undefined&&+f.rows!==3) }
function ldPropsHTML(){
  if(LD.sel===null||!LD.form[LD.sel]) return '<div class="ld-sh">Properties</div>';
  var f=LD.form[LD.sel], t=bcType(f.t), data=bcIsData(f);
  var h='<div class="ld-sh">Properties: '+esc(data?f.l:t==='section'?'Section header':t==='note'?'Note':'Divider')+'</div>';
  if(data){
    h+='<div class="mini" style="margin-bottom:12px">'+(FT[f.t]||f.t)+' · <span class="mono">'+esc(f.k)+'</span></div>'+
      '<div class="field ld-pf"><label for="ldFl">Display label</label><input class="inp" id="ldFl" value="'+esc(f.l||'')+'" onchange="ldSet(\'l\',this.value)"></div>'+
      '<label class="ck ld-pf"><input type="checkbox"'+(f.r?' checked':'')+' onchange="ldSet(\'r\',this.checked?1:0)"><span>Required</span></label>'+
      ((t==='select'||t==='radio')?'<div class="field ld-pf"><label for="ldFo">Options (one value per line)</label><textarea class="inp" id="ldFo" rows="3" onchange="ldSet(\'o\',this.value)">'+esc(f.o||'')+'</textarea></div>':'');
  }
  if(t==='section') h+='<div class="field ld-pf"><label for="ldSecL">Header text</label><input class="inp" id="ldSecL" value="'+esc(f.l||'')+'" onchange="ldSet(\'l\',this.value)"></div>';
  if(t==='note'){
    h+='<div class="field ld-pf"><label for="ldNoteT">Note content</label><textarea class="inp" id="ldNoteT" rows="4" onchange="ldSet(\'text\',this.value)">'+esc(f.text||'')+'</textarea>'+
      '<span class="hint">**bold** · *italic* · [text](https://link)</span></div>'+
      '<div class="field ld-pf"><label>Type</label>'+ldSeg([['info','Information'],['warn','Note']],f.tone||'info','ldTone')+'</div>'+
      '<label class="ck ld-pf"><input type="checkbox"'+(f.ro?' checked':'')+' onchange="ldSet(\'ro\',this.checked?1:0)"><span>Also show when viewing the ticket (hidden in read-only mode by default)</span></label>';
  }
  if(t!=='section'&&t!=='divider'){
    h+='<div class="field ld-pf"><label for="ldWr">Width: <b class="num" id="ldWv">'+bcW(f)+'</b> / 12 columns</label>'+
      '<input type="range" class="ld-range" id="ldWr" min="2" max="12" step="1" value="'+bcW(f)+'" oninput="document.getElementById(\'ldWv\').textContent=this.value" onchange="ldWidth(+this.value)">'+
      ldSeg(BC_STEPS.map(function(s){return [s,s]}),bcW(f),'ldWidth')+'</div>';
    var first=LD.sel===0||(function(){ for(var j=LD.sel-1;j>=0;j--){ return !bcIsFlow(LD.form[j]) } return true })();
    h+='<div class="field ld-pf"><label>Start a new row</label>'+ldSeg([[0,'No'],[1,'Yes']],f.nl?1:0,'ldNl',first)+'</div>';
    h+='<div class="field ld-pf"><label>Left divider</label>'+ldSeg([[0,'No'],[1,'Yes']],f.bl?1:0,'ldBl')+'</div>';
  }
  if(t==='area') h+='<div class="field ld-pf"><label for="ldRr">Height: <b class="num" id="ldRv">'+(+f.rows||3)+'</b> rows</label>'+
    '<input type="range" class="ld-range" id="ldRr" min="2" max="12" step="1" value="'+(+f.rows||3)+'" oninput="document.getElementById(\'ldRv\').textContent=this.value" onchange="ldRowsN(+this.value)">'+
    '<span class="hint">Or drag the bottom edge of the box on the canvas.</span></div>';
  if(data){
    var ov=ldIsOverride(f);
    h+='<button class="btn sm dgr" style="width:100%;justify-content:center;margin-top:4px" onclick="ldDel()">'+svg(I.trash)+'Remove field from layout</button>';
  } else {
    h+='<button class="btn sm dgr" style="width:100%;justify-content:center;margin-top:4px" onclick="ldDel()">'+svg(I.trash)+'Delete element</button>';
  }
  return h;
}


function ldMut(fn){ ldPush(); ldFreeze(); fn(LD.form[LD.sel]); ldClean(); ldDraw() }
function ldSet(k,v){ ldPush(); LD.form[LD.sel][k]=v; ldDraw() }
function ldTone(v){ ldSet('tone',v) }
function ldWidth(w){
  var f=LD.form[LD.sel]; if(!f||!bcIsFlow(f)) return;
  w=Math.max(2,Math.min(12,Math.round(w)));
  if(bcW(f)===w) return ldDraw();
  ldMut(function(f){ if(w===bcDefW(f)) delete f.w; else f.w=w });
}
function ldNl(v){ ldMut(function(f){ if(v) f.nl=1; else delete f.nl }) }
function ldBl(v){ ldPush(); if(v) LD.form[LD.sel].bl=1; else delete LD.form[LD.sel].bl; ldDraw() }
function ldRowsN(v){ v=Math.max(2,Math.min(12,Math.round(v))); ldPush(); if(v===3) delete LD.form[LD.sel].rows; else LD.form[LD.sel].rows=v; ldDraw() }
function ldReset1(){ ldMut(function(f){ delete f.w; delete f.nl; delete f.bl; delete f.rows }) }
function ldDel(){
  var f=LD.form[LD.sel]; if(!f) return;
  ldPush(); ldFreeze();
  var s=ldStarts(LD.form), i=LD.sel, nx=LD.form[i+1];
  if(s[i]&&nx&&bcIsFlow(nx)&&bcIsFlow(f)) nx.nl=1;      
  LD.form.splice(i,1); LD.sel=null;
  if(bcIsData(f)){ delete f.nl; LD.pool.push(f) }         
  ldClean(); ldDraw();
  if(bcIsData(f)) toast('Removed "'+f.l+'" from the layout','The field is in "Not placed" on the left — drag it back onto the canvas if needed. Saving without placing it removes the field from the form');
}
function ldPick(i,scroll){
  LD.sel=i; ldDraw();
  if(scroll){ var el=document.querySelector('.ld-it[data-i="'+i+'"]'); if(el) el.scrollIntoView({block:'center',behavior:'smooth'}) }
}
function ldBlank(e){ if(e.target.id==='ldCv'||e.target.classList.contains('ld-paper')){ LD.sel=null; ldDraw() } }
function ldGoStart(){
  var st=def().nodes.filter(function(x){return x.t==='start'})[0]; if(!st) return;
  var go=function(){ ldShut(); DSN.sel=st.id; DSN.tab='fm'; renderNodes(); renderInsp(); openLayout() };
  if(LD.chg>0){ LD.modal={k:'leave',then:'start'}; return ldDraw() }
  go();
}
function ldEditField(){
  if(LD.chg>0){ LD.modal={k:'leave',then:'field'}; return ldDraw() }
  ldToField();
}
function ldToField(){
  var n=ldNode(), k=LD.form[LD.sel]&&LD.form[LD.sel].k;
  ldShut();
  DSN.sel=n.id; DSN.tab='fm'; DSN.open=(n.form||[]).map(function(f){return f.k}).indexOf(k);
  if(DSN.open<0) DSN.open=null;
  renderNodes(); renderInsp();
}


function ldProto(type){
  if(type.indexOf('fld:')===0) return LD.pool[+type.slice(4)]||{t:'text'};
  if(type.indexOf('ft:')===0) return {t:type.slice(3)};
  return {t:type};
}
function ldTypeLabel(type){
  if(type.indexOf('fld:')===0) return (LD.pool[+type.slice(4)]||{}).l||'Field';
  if(type.indexOf('ft:')===0) return 'New field · '+(FT[type.slice(3)]||type.slice(3));
  return ({section:'Section header',note:'Note',divider:'Divider',bl:'Column divider'})[type];
}
function ldMake(type){
  if(type.indexOf('fld:')===0) return LD.pool.splice(+type.slice(4),1)[0];
  if(type.indexOf('ft:')===0){
    var ft=type.slice(3), used={}, k, i=1;
    LD.form.concat(LD.pool).forEach(function(x){ used[x.k]=1 });
    while(used['truong'+i]) i++;
    k='truong'+i;
    var nf={k:k,l:'New field '+i,t:ft};
    if(ft==='select'||ft==='radio') nf.o='Option 1\nOption 2';
    return nf;
  }
  LD_SEQ++;
  if(type==='section') return {k:'sec'+LD_SEQ,t:'section',l:'Section header'};
  if(type==='note') return {k:'gc'+LD_SEQ,t:'note',text:'Note content',tone:'info',ro:0};
  return {k:'hr'+LD_SEQ,t:'divider'};
}
function ldAddQuick(type){
  if(type==='bl'){
    if(LD.sel===null||!LD.form[LD.sel]||!bcIsFlow(LD.form[LD.sel])) return toast('Select a field first','A column divider attached to the left edge of the selected field');
    return ldBl(1);
  }
  var at=LD.sel!==null?LD.sel+1:LD.form.length;
  ldPush(); ldFreeze();
  var el=ldMake(type); el.nl=1;
  var nx=LD.form[at];
  LD.form.splice(at,0,el);
  if(nx&&bcIsFlow(nx)) nx.nl=1;
  LD.sel=at; ldClean(); ldDraw();
}


function ldItemDown(e,i){
  if(e.target.closest&&e.target.closest('.ld-h,.ld-rs,.ld-rb,.ld-x')) return;
  e.stopPropagation(); if(LD.sel!==i){ LD.sel=i; ldDraw() }
}
function ldStartMove(e,i){ e.preventDefault(); e.stopPropagation(); LD.sel=i; LD.drag={m:'move',i:i,x0:e.clientX,y0:e.clientY,go:0} }
function ldStartNew(e,type){ e.preventDefault(); LD.drag={m:type==='bl'?'bl':'new',type:type,x0:e.clientX,y0:e.clientY,go:0} }
function ldStartResize(e,i,side){
  e.preventDefault(); e.stopPropagation();
  var f=LD.form[i];
  var it=document.querySelector('.ld-it[data-i="'+i+'"]'), row=it.parentNode.getBoundingClientRect(), gap=15, r=it.getBoundingClientRect();
  LD.sel=i;
  document.querySelectorAll('.ld-it.sel').forEach(function(x){x.classList.remove('sel')}); it.classList.add('sel');
  
  LD.drag={m:'rs',i:i,side:side||'r',left:r.left+6,right:r.right-6,colW:(row.width+gap)/12,gap:gap,w0:bcW(f),w:bcW(f),el:it};
  document.getElementById('ldGrid').classList.add('dragging');
}
function ldStartRows(e,i){
  e.preventDefault(); e.stopPropagation();
  var it=document.querySelector('.ld-it[data-i="'+i+'"]'), box=it.querySelector('.ld-ta');
  LD.sel=i; it.classList.add('sel');
  LD.drag={m:'rh',i:i,top:box.getBoundingClientRect().top,r0:+LD.form[i].rows||3,r:+LD.form[i].rows||3,box:box,el:it};
}


function ldTarget(x,y){
  var grid=document.getElementById('ldGrid'); if(!grid) return null;
  var gr=grid.getBoundingClientRect();
  if(x<gr.left-40||x>gr.right+40) return null;
  var rows=[].slice.call(grid.querySelectorAll('.ld-row'));
  var endz=grid.querySelector('.ld-endz').getBoundingClientRect();
  if(y>=endz.top-6) return {pos:'end'};
  if(!rows.length) return {pos:'end'};
  for(var ri=0;ri<rows.length;ri++){
    var rr=rows[ri].getBoundingClientRect();
    if(y<rr.top-8) return {pos:'rowB',r:ri};
    if(y<=rr.bottom+8){
      if(y<rr.top+8) return {pos:'rowB',r:ri};
      if(y>rr.bottom-8) return {pos:'rowA',r:ri};
      if(rows[ri].classList.contains('one')) return {pos:y<(rr.top+rr.bottom)/2?'rowB':'rowA',r:ri};
      var its=[].slice.call(rows[ri].querySelectorAll('.ld-it')).filter(function(el){return !(LD.drag.m==='move'&&+el.getAttribute('data-i')===LD.drag.i)});
      if(!its.length) return {pos:'rowB',r:ri};
      for(var k=0;k<its.length;k++){
        var ir=its[k].getBoundingClientRect();
        if(x<(ir.left+ir.right)/2) return {pos:'bef',j:+its[k].getAttribute('data-i'),r:ri};
      }
      return {pos:'aft',j:+its[its.length-1].getAttribute('data-i'),r:ri};
    }
  }
  return {pos:'end'};
}
function ldRowOfTarget(tg){ var rows=bcRows(LD.form); return rows[tg.r] }
function ldCheck(tg,f){
  if(!tg) return {ok:0};
  if(tg.pos==='bef'||tg.pos==='aft'){
    if(bcFull(f)||bcW(f)===12) return {ok:1,tg:{pos:tg.pos==='bef'?'rowB':'rowA',r:tg.r},full:1};
    var row=ldRowOfTarget(tg), cnt=row.items.filter(function(it){return !(LD.drag.m==='move'&&it.i===LD.drag.i)}).length;
    if(cnt>=4) return {ok:0,msg:'Up to 4 fields per row',tg:tg};
  }
  return {ok:1,tg:tg};
}
function ldShowInd(chk){
  var ind=document.getElementById('ldInd'), grid=document.getElementById('ldGrid'); if(!ind) return;
  if(!chk||!chk.tg){ ind.style.display='none'; return }
  var tg=chk.tg, gr=grid.getBoundingClientRect(), rows=grid.querySelectorAll('.ld-row'), s=ind.style;
  ind.className='ld-ind'+(chk.ok?'':' bad'); ind.textContent=chk.ok?'':chk.msg; s.display='block';
  if(tg.pos==='bef'||tg.pos==='aft'){
    var el=grid.querySelector('.ld-it[data-i="'+tg.j+'"]').getBoundingClientRect();
    s.left=((tg.pos==='bef'?el.left-8:el.right+5)-gr.left)+'px'; s.top=(el.top-gr.top)+'px'; s.width='3px'; s.height=el.height+'px';
  } else if(tg.pos==='end'){
    var ez=grid.querySelector('.ld-endz').getBoundingClientRect();
    s.left='16px'; s.width=(gr.width-32)+'px'; s.top=(ez.top-gr.top-6)+'px'; s.height='3px';
  } else {
    var rr=rows[tg.r].getBoundingClientRect();
    s.left='16px'; s.width=(gr.width-32)+'px'; s.top=((tg.pos==='rowB'?rr.top-9:rr.bottom+6)-gr.top)+'px'; s.height='3px';
  }
}
function ldGhost(x,y,txt){
  var g=document.getElementById('ldGhost');
  if(!g){ g=document.createElement('div'); g.id='ldGhost'; g.className='ld-ghost'; document.getElementById('ld').appendChild(g) }
  if(txt!==undefined) g.textContent=txt;
  g.style.left=(x+14)+'px'; g.style.top=(y+10)+'px';
}
function ldEndDrag(){
  var g=document.getElementById('ldGhost'); if(g) g.parentNode.removeChild(g);
  var grid=document.getElementById('ldGrid'); if(grid) grid.classList.remove('dragging');
  var ind=document.getElementById('ldInd'); if(ind) ind.style.display='none';
  document.querySelectorAll('.ld-it.drop-bl,.ld-it.moving').forEach(function(el){el.classList.remove('drop-bl','moving')});
}
document.addEventListener('mousemove',function(e){
  if(!LD||!LD.drag) return;
  var D=LD.drag;
  if(D.m==='rs'){
    var c=D.side==='l'?(D.right-e.clientX+D.gap)/D.colW:(e.clientX-D.left+D.gap)/D.colW;
    var w=Math.max(2,Math.min(12,Math.round(c)));
    if(w!==D.w){ D.w=w; D.el.style.gridColumn='span '+w; D.el.querySelector('.ld-w').textContent=w+'/12' }
    return;
  }
  if(D.m==='rh'){
    var rr=Math.max(2,Math.min(12,Math.round((e.clientY-D.top-18)/20)));
    if(rr!==D.r){ D.r=rr; D.box.style.height=(rr*20+18)+'px'; D.el.querySelector('.ld-w').textContent=rr+(rr===1?' row':' rows')+'' }
    return;
  }
  if(!D.go){
    if(Math.abs(e.clientX-D.x0)+Math.abs(e.clientY-D.y0)<5) return;
    D.go=1;
    var grid=document.getElementById('ldGrid'); if(grid) grid.classList.add('dragging');
    var lbl=D.m==='move'?(bcIsData(LD.form[D.i])?LD.form[D.i].l:({section:'Section header',note:'Note',divider:'Divider'})[LD.form[D.i].t])
           :ldTypeLabel(D.type);
    ldGhost(e.clientX,e.clientY,lbl);
    if(D.m==='move'){ var me=document.querySelector('.ld-it[data-i="'+D.i+'"]'); if(me) me.classList.add('moving') }
  }
  ldGhost(e.clientX,e.clientY);
  var cv=document.getElementById('ldCv');                   
  if(cv){ var cr=cv.getBoundingClientRect(); if(e.clientY>cr.bottom-40) cv.scrollTop+=14; else if(e.clientY<cr.top+40) cv.scrollTop-=14 }
  if(D.m==='bl'){
    document.querySelectorAll('.ld-it.drop-bl').forEach(function(el){el.classList.remove('drop-bl')});
    var hit=document.elementFromPoint(e.clientX,e.clientY), it=hit&&hit.closest?hit.closest('.ld-it'):null;
    D.hit=null;
    if(it&&!it.classList.contains('one')){ it.classList.add('drop-bl'); D.hit=+it.getAttribute('data-i') }
    return;
  }
  var f=D.m==='move'?LD.form[D.i]:ldProto(D.type);
  D.chk=ldCheck(ldTarget(e.clientX,e.clientY),f);
  ldShowInd(D.chk);
  var g=document.getElementById('ldGhost');
  if(g){ if(D.chk&&!D.chk.ok){ g.classList.add('bad'); g.setAttribute('data-l',g.getAttribute('data-l')||g.textContent); g.textContent=D.chk.msg }
         else if(g.classList.contains('bad')){ g.classList.remove('bad'); g.textContent=g.getAttribute('data-l') } }
});
document.addEventListener('mouseup',function(e){
  if(!LD||!LD.drag) return;
  var D=LD.drag; LD.drag=null; ldEndDrag();
  if(D.m==='rs'){
    if(D.w!==D.w0){ var i=D.i; LD.sel=i; ldMut(function(f){ if(D.w===bcDefW(f)) delete f.w; else f.w=D.w }) }
    else ldDraw();
    return;
  }
  if(D.m==='rh'){ LD.sel=D.i; if(D.r!==D.r0) ldRowsN(D.r); else ldDraw(); return }
  if(!D.go){                                     
    if(D.m==='new'||D.m==='bl') ldAddQuick(D.type); else ldDraw();
    return;
  }
  if(D.m==='bl'){
    if(D.hit===null||D.hit===undefined) return toast('Drop onto a field','A column divider attached to the left edge of the dropped field');
    LD.sel=D.hit; return ldBl(1);
  }
  var chk=D.chk; if(!chk||!chk.tg){ return ldDraw() }
  if(!chk.ok){ ldDraw(); return toast('Couldn’t drop',chk.msg) }
  ldApply(D,chk.tg);
});
function ldApply(D,tg){
  ldPush(); ldFreeze();
  var F=LD.form, rows=bcRows(F), item, from=-1;
  
  var idx, mode=tg.pos;
  if(mode==='end') idx=F.length;
  else if(mode==='rowB') idx=rows[tg.r].items[0].i;
  else if(mode==='rowA') idx=rows[tg.r].items[rows[tg.r].items.length-1].i+1;
  else if(mode==='bef') idx=tg.j;
  else idx=tg.j+1;
  var targetWasStart=(mode==='bef')&&ldStarts(F)[tg.j];
  
  var rowObjs=(mode==='bef'||mode==='aft')?rows[tg.r].items.map(function(it){return it.f}):[];
  if(D.m==='move'){
    from=D.i; item=F[from];
    var s=ldStarts(F), nx=F[from+1];
    if(s[from]&&nx&&bcIsFlow(nx)&&!ldStarts(F)[from+1]) nx.nl=1;   
    F.splice(from,1);
    if(idx>from) idx--;
  } else item=ldMake(D.type);
  if(mode==='end'||mode==='rowB'||mode==='rowA'){ item.nl=1 }
  else if(mode==='bef'){ if(targetWasStart){ item.nl=1 } else delete item.nl }
  else delete item.nl;
  F.splice(idx,0,item);
  if(mode==='bef'&&targetWasStart){ delete F[idx+1].nl }
  var after=F[idx+1]; if((mode==='rowB'||mode==='rowA'||mode==='end')&&after&&bcIsFlow(after)) after.nl=1;
  if(rowObjs.length){
    var others=rowObjs.filter(function(x){return x!==item}), sum=others.reduce(function(s,x){return s+bcW(x)},0);
    if(sum+bcW(item)>12){                                  
      var all=others.concat([item]), w=Math.floor(12/all.length), rem=12-w*all.length;
      all.forEach(function(x,k){ x.w=w+(k<rem?1:0) });
      toast('The row already has 12 columns','Redistributed evenly '+all.length+(all.length===1?' field':' fields')+' in the row');
    }
  }
  LD.sel=idx; ldClean(); ldDraw();
}


document.addEventListener('keydown',function(e){
  if(!LD) return;
  var tag=(e.target.tagName||'').toLowerCase(), typing=tag==='input'||tag==='textarea'||tag==='select';
  if(e.key==='Escape'){ e.stopImmediatePropagation(); if(LD.modal){ LD.modal=null; ldDraw() } else ldClose(); return }
  if(typing) return;
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){ e.preventDefault(); return ldUndo() }
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){ e.preventDefault(); return ldRedo() }
  if(LD.sel===null) return;
  if(e.key==='Delete'||e.key==='Backspace'){ e.preventDefault(); return ldDel() }
  if(e.key==='ArrowRight'||e.key==='ArrowLeft'){
    var f=LD.form[LD.sel]; if(!f||!bcIsFlow(f)) return; e.preventDefault();
    var w=bcW(f)+(e.key==='ArrowRight'?1:-1); if(w<2||w>12) return;
    ldWidth(w);
  }
},true);
window.addEventListener('resize',function(){ if(LD&&!LD.drag) ldDraw() });


function ldModalHTML(){
  var m=LD.modal, h='', btns='';
  if(m.k==='close'){
    h='<div class="alert a-warn">'+svg(I.warn)+'<div><b>Remaining: '+LD.chg+' unsaved changes</b>Closing the designer now will discard all changes from this session.</div></div>';
    btns='<button class="btn" onclick="LD.modal=null;ldDraw()">Keep editing</button><button class="btn dgr" onclick="ldShut()">Discard changes and close</button>'+
         '<button class="btn pri" onclick="ldSave()">'+svg(I.save)+'Save layout</button>';
  } else if(m.k==='blank'){
    h='<div class="alert a-info">'+svg(I.info)+'<div><b>Create a new layout from scratch?</b>The design canvas will be completely empty. All form fields move to <b>Not placed</b> in the left sidebar; '+
      'existing section titles, notes and dividers are dropped. Drag each field onto the canvas to redesign it. You can Undo if not yet saved.</div></div>';
    btns='<button class="btn" onclick="LD.modal=null;ldDraw()">Cancel</button><button class="btn pri" onclick="ldNewBlank()">Start from an empty canvas</button>';
  } else if(m.k==='pool'){
    h='<div class="alert a-warn">'+svg(I.warn)+'<div><b>Remaining: '+LD.pool.length+(LD.pool.length===1?' field':' fields')+' not yet placed in the layout</b>'+
      'If you save now, these fields <b>removed from the form</b>: '+LD.pool.map(function(f){return '“'+esc(f.l)+'”'}).join(', ')+
      '. If a Value or Variable value of a System task node uses these fields, the related parameter will show an error.</div></div>';
    btns='<button class="btn" onclick="LD.modal=null;ldDraw()">Back to placing fields</button>'+
         '<button class="btn dgr" onclick="ldSave(1)">Save and delete '+LD.pool.length+(LD.pool.length===1?' field':' fields')+'</button>';
  } else if(m.k==='leave'){
    h='<div class="alert a-warn">'+svg(I.warn)+'<div><b>Remaining: '+LD.chg+' unsaved changes</b>Save the layout before switching so you don’t lose changes.</div></div>';
    btns='<button class="btn" onclick="LD.modal=null;ldDraw()">Stay</button>'+
         '<button class="btn pri" onclick="'+(m.then==='start'?'if(ldSave())ldGoStartNow()':'ldSave()')+'">'+svg(I.save)+'Save and switch</button>';
  } else if(m.k==='warn'){
    h='<div class="ld-sh">Layout warnings</div>'+LD.warn.map(function(w,i){
      return '<div class="alert a-warn">'+svg(I.warn)+'<div>'+esc(w.x)+
        (w.k&&LD.form.some(function(f){return f.k===w.k})?' <button class="link" onclick="LD.modal=null;ldPick(LD.form.map(function(f){return f.k}).indexOf(\''+w.k+'\'),1)">Select element</button>':'')+'</div></div>';
    }).join('');
    btns='<button class="btn" onclick="LD.warn=[];LD.modal=null;ldDraw()">Seen, warning hidden</button><button class="btn pri" onclick="LD.modal=null;ldDraw()">Close</button>';
  }
  return '<div class="ld-modal"><div class="ld-mb" role="alertdialog" aria-modal="true">'+h+'<div class="ld-mf">'+btns+'</div></div></div>';
}
function ldNewBlank(){
  ldPush();
  var fields=LD.form.filter(bcIsData).map(function(f){ var c={}; for(var k in f) if(['w','nl','bl','rows'].indexOf(k)<0) c[k]=f[k]; return c });
  LD.pool=fields.concat(LD.pool); LD.form=[]; LD.sel=null; LD.modal=null; ldDraw();
  toast('Empty frame created','Drag fields from "Not placed" or "Add new field" in the left bar onto the canvas');
}
function ldGoStartNow(){
  var st=def().nodes.filter(function(x){return x.t==='start'})[0]; if(!st) return;
  DSN.sel=st.id; DSN.tab='fm'; renderNodes(); renderInsp(); openLayout();
}


function ldSave(force){
  var n=ldNode(); if(!n) return false;
  if(!canDesign()){                                   
    AUDIT.unshift({t:ldNow(),u:'admin',h:'Denied saving the form layout',dt:DSN.id+' · node '+n.id,ip:'10.20.4.11',nc:0});
    toast('The server refused to save','The account has neither the System Administrator nor the Process Designer role'); return false;
  }
  if(LD.pool.length&&!force){ LD.modal={k:'pool',then:LD.modal&&LD.modal.k==='leave'?LD.modal.then:null}; ldDraw(); return false }
  var then=LD.modal&&(LD.modal.k==='leave'||LD.modal.k==='pool')?LD.modal.then:null;
  var removed=LD.pool.length;
  n.form=ldClone(LD.form);
  n._lo=n.form.filter(bcIsData).map(function(f){return f.k});
  n._bcWarn=[];
  var d=def();
  AUDIT.unshift({t:ldNow(),u:'admin',h:'Save form layout',dt:DSN.id+' · node '+n.id+' ('+n.name+') · draft after v'+d.v,ip:'10.20.4.11',nc:0});
  if(then==='field'){ LD.chg=0; ldToField() } else ldShut();
  markDirty(); renderNodes(); renderInsp();
  toast('Layout saved to draft',(removed?'Deleted '+removed+(removed===1?' field':' fields')+' not placed in the layout · ':'')+'Not effective until the workflow is published · logged');
  return true;
}

