function setProp(k,v){ var n=nodeById(DSN.sel); if(!n) return; n[k]=v; renderNodes(); renderInsp(); markDirty() }


var DT={string:'String',number:'Number',date:'Date',datetime:'Date & time',time:'Time',boolean:'True/False',file:'File'};


function upstreamNodes(id){
  var d=def(), seen={}, lv={}, out=[], q=[id]; lv[id]=0;
  while(q.length){
    var cur=q.shift();
    d.links.forEach(function(l){
      if(l.to!==cur||seen[l.f]) return;
      seen[l.f]=1; lv[l.f]=(lv[cur]||0)+1; out.push(l.f); q.push(l.f);
    });
  }
  
  return out.sort(function(a,b){ return lv[b]-lv[a] });
}
function startNodeId(){ var s=def().nodes.filter(function(n){return n.t==='start'})[0]; return s?s.id:null }

function reachFrom(from,avoid){
  var d=def(), seen={}, q=[from]; if(from===avoid) return seen; seen[from]=1;
  while(q.length){
    var cur=q.shift();
    d.links.forEach(function(l){
      if(l.f!==cur||seen[l.to]||l.to===avoid) return;
      seen[l.to]=1; q.push(l.to);
    });
  }
  return seen;
}

function prmAlways(target,x){
  var s=startNodeId(); if(!s||x===s) return true;
  return !reachFrom(s,x)[target];
}

function prmCond(target,x){
  var ups=upstreamNodes(x).slice().reverse();          
  for(var i=0;i<ups.length;i++){
    var g=nodeById(ups[i]); if(!g||g.t!=='gate') continue;
    var outs=def().links.filter(function(l){return l.f===g.id});
    var toX=outs.filter(function(l){return l.to===x||reachFrom(l.to)[x]});
    var skip=outs.filter(function(l){return toX.indexOf(l)<0 && (l.to===target||reachFrom(l.to)[target])});
    if(toX.length&&skip.length){
      var pv={}; paramsOf(def()).forEach(function(p){ pv[p[0]]=p[1] });
      var c=String(g.cond||g.name).replace(/\{\{\s*([A-Z_0-9]+)\s*\}\}/g,function(_,k){return pv[k]||k});
      var neg=toX.every(function(l){return l.lbl==='False'});
      return (neg?'only exists when NOT met ':'only exists when ')+c;
    }
  }
  return 'only exists on some branches';
}


function fieldDT(f){
  var t=f.t;
  if(t==='num'||t==='money') return 'number';
  if(t==='date') return 'date';
  if(t==='time') return 'time';
  if(t==='check') return 'boolean';
  if(t==='file') return 'file';
  if(t==='ro') return f.dt||(/^(so|muc|luong|quyPhep|otThang)/.test(f.k)?'number':'string');
  return 'string';
}
