  luongHienTai:'16000000',luongDeXuat:'17500000',mucTang:'9.4',hieuLuc:'Next period',canCu:'Achieved 112% of target',
  mucDuyet:'17500000',ngayOT:'12/09/2026',loaiNgay:'Weekday (150%)',tuGio:'18:00',denGio:'22:00',soGio:'4',
