function approverMa(n){ var u=userBy(WHO_ACC[n.who]||''); return u?u.ma:'NV-00000' }


function varsAt(id){
  var list=[];
  [['maDon','string','Ticket ID, generated when the instance is created','NP-2026-0142'],
   ['maNhanVien','string','Employee code of the ticket submitter','NV-00412'],
   ['hoTen','string','Full name of the ticket submitter','Nguyễn Văn An'],
   ['phongBan','string','Submitter’s department','Sales Department'],
   ['thoiDiemNop','datetime','Ticket submitted at','08/09/2026 09:12'],
   ['cachChonNguoiDuyet','string','Approver selection method: UserGroup | TuChon','TuChon']].forEach(function(s){
    list.push({v:'sys.'+s[0],dt:s[1],lbl:s[2],g:'sys',gl:'System',always:true,mau:s[3]});
  });
  upstreamNodes(id).forEach(function(nid){
    var n=nodeById(nid); if(!n) return;
    var always=prmAlways(id,nid), cond=always?'':prmCond(id,nid), gl=nid+' · '+n.name;
    (n.form||[]).forEach(function(f){
      if(typeof bcIsData==='function'&&!bcIsData(f)) return;     
      var dt=fieldDT(f);
      list.push({v:nid+'.'+f.k,dt:dt,lbl:f.l,g:nid,gl:gl,node:nid,always:always,cond:cond,mau:PRM_MAU[f.k]||DT_MAU[dt]});
    });
    if(n.t==='task'){
      list.push({v:nid+'.nguoiDuocGiao',dt:'string',lbl:'Employee code of the person assigned this step',g:nid,gl:gl,node:nid,always:always,cond:cond,mau:approverMa(n)});
      list.push({v:nid+'.nguonNguoiDuyet',dt:'string',lbl:'Approver source: UserGroup | NguoiNopChon',g:nid,gl:gl,node:nid,always:always,cond:cond,mau:'NguoiNopChon'});
      list.push({v:nid+'.nguoiDuyet',dt:'string',lbl:'Employee code of the person who approved this step',g:nid,gl:gl,node:nid,always:always,cond:cond,mau:approverMa(n)});
      list.push({v:nid+'.thoiDiem',dt:'datetime',lbl:'Approval completed at',g:nid,gl:gl,node:nid,always:always,cond:cond,mau:nid==='n2'?'08/09/2026 15:40':'09/09/2026 10:30'});
      list.push({v:nid+'.ketQua',dt:'string',lbl:'Approve / Reject / Request more info',g:nid,gl:gl,node:nid,always:always,cond:cond,mau:'Approve'});
    }
  });
  return list;
}
function varIdx(vars){ var m={}; vars.forEach(function(v){ m[v.v]=v }); return m }

function exprsIn(s){ var out=[]; String(s||'').replace(/\{\{\s*([^}]+?)\s*\}\}/g,function(_,x){ out.push(x.trim()) }); return out }


var HTTP_METHODS=['DELETE','GET','HEAD','OPTIONS','PATCH','POST','PUT'];
var SYS={nid:null,open:-1,focus:null,caret:null,q:'',bag:0,menu:null};

function sysGet(n){
  if(!n.http) n.http={method:'POST',url:'',sendQuery:1,qmode:'fields',params:[],json:''};
  var h=n.http; if(!h.params) h.params=[];
  h.sendQuery=1;                                   
  h.params.forEach(function(p){ if(!p.vars) p.vars=[] });
  return h;
}
function sysPath(url){
  var u=String(url||'').trim(); if(!u) return '';
  var m=u.match(/^https?:\/\/[^\/?#]+([^?#]*)/i);
  return m?(m[1]||'/'):u;
}
function sysLabel(n){ var h=sysGet(n); return h.method+' '+(sysPath(h.url)||'(no URL yet)') }


function sysPaths(target){
  var d=def(), s=startNodeId(), out=[];
  if(!s) return out;
  (function dfs(cur,path,gs){
    if(out.length>=64) return;
    if(cur===target){ out.push({nodes:path.slice(),gates:gs.slice()}); return }
    d.links.forEach(function(l){
      if(l.f!==cur||path.indexOf(l.to)>=0) return;
      var g=nodeById(cur), isG=g&&g.t==='gate';
      path.push(l.to); if(isG) gs.push({g:g,lbl:l.lbl||''});
      dfs(l.to,path,gs);
      path.pop(); if(isG) gs.pop();
    });
  })(s,[s],[]);
  out.forEach(function(P){
    P.label=P.gates.length?P.gates.map(function(x){return '“'+x.g.name+'” → '+(x.lbl||'other branch')}).join(' · '):'All tickets';
    P.tasks=P.nodes.map(nodeById).filter(function(x){return x&&x.t==='task'}).map(function(x){return x.name});
  });
  return out;
}


function sysEntry(s,vi){
  s=String(s||'').trim();
  var e={s:s,empty:!s,refs:exprsIn(s),bad:[],nodes:[]};
  e.refs.forEach(function(x){
    if(!vi[x]) e.bad.push(x);
    else if(vi[x].node&&e.nodes.indexOf(vi[x].node)<0) e.nodes.push(vi[x].node);
  });
  return e;
}

function sysAvail(e,P){
  if(e.empty||e.bad.length) return false;
  return e.nodes.every(function(nd){ return P.nodes.indexOf(nd)>=0 });
}
var SYS_NAME_BAD=/[\s&=?#]/;

function sysRowEval(p,i,all,paths,vi){
  var R={i:i,err:[],warn:[],pick:[],miss:[],entries:[]};
  var name=String(p.name||'').trim();
  if(!name) R.err.push({f:'n',m:'Name is missing — enter the exact parameter name from the HRM integration guide'});
  else if(SYS_NAME_BAD.test(name)) R.err.push({f:'n',m:'Name must not contain spaces or the characters & = ? #'});
  else if(all.some(function(q,k){ return k!==i&&String(q.name||'').trim()===name }))
    R.warn.push({f:'n',m:'Name duplicates another parameter — HRM will receive two values with the same name'});
  var es=[p.value].concat(p.vars||[]).map(function(s){ return sysEntry(s,vi) });
  R.entries=es;
  var bad=0;
  es.forEach(function(e,k){
    var who=k?'Variable value '+k:'Value', f=k?'w'+(k-1):'v';
    e.bad.forEach(function(x){ bad=1; R.err.push({f:f,m:who+': variable {{'+x+'}} cannot be used in this node — the node was deleted, the field code changed, or the variable belongs to a later step'}) });
    if(k>0&&e.empty){ bad=1; R.err.push({f:f,m:who+' is empty — enter a value or delete this row'}) }
  });
  if(bad||!paths.length) return R;
  if(es.every(function(e){return e.empty})){
    R.warn.push({f:'v',m:'Value is empty — the parameter will be sent empty'});
    return R;
  }
  paths.forEach(function(P,pi){
    var idx=-1; for(var k=0;k<es.length;k++){ if(sysAvail(es[k],P)){ idx=k; break } }
    R.pick[pi]=idx; if(idx<0) R.miss.push(P);
  });
  R.miss.forEach(function(P){
    R.err.push({f:es.length>1?'w'+(es.length-2):'v',m:'A ticket on branch '+P.label+' will send '+(name||'this parameter')+' empty — add a Variable value taken from a step this branch passes through'});
  });
  es.forEach(function(e,k){
    if(e.empty||R.pick.indexOf(k)>=0) return;
    if(k) R.warn.push({f:'w'+(k-1),m:'Variable value '+k+' is never used — the value above already has data on every branch reaching this node. Check the order'});
    else R.warn.push({f:'v',m:'Value has no data on any branch reaching this node — check the variable'});
  });
  return R;
}

function sysEval(n){
  var h=sysGet(n), vars=varsAt(n.id), vi=varIdx(vars), paths=sysPaths(n.id);
  var st={errs:0,warns:0,url:{err:[],warn:[]},gen:[],rows:[],json:{err:[],warn:[]},paths:paths,vi:vi};
  var u=String(h.url||'').trim();
  if(!u) st.url.err.push('URL is missing — take the endpoint address from the HRM integration guide');
  else if(!/^https?:\/\/[^\s\/?#]+/i.test(u)) st.url.err.push('The URL must start with http:// or https:// and a host name');
  else if(/\s/.test(u)) st.url.err.push('The URL must not contain spaces');
  else if(h.sendQuery&&u.indexOf('?')>=0) st.url.warn.push('The URL already has a query string — the Query Parameters below will be appended with &');
  if(HTTP_METHODS.indexOf(h.method)<0) st.url.err.push('No Method selected');
  if(!paths.length) st.gen.push({t:'warn',m:'The node is not connected from the Start node — variables can’t be checked per branch yet'});
  if(h.sendQuery){
    if(h.qmode==='json') sysJsonEval(h,st);
    else {
      if(!h.params.length) st.gen.push({t:'warn',m:'No parameters yet — click Add Parameter'});
      h.params.forEach(function(p,i){ st.rows.push(sysRowEval(p,i,h.params,paths,vi)) });
    }
  }
  st.errs=st.url.err.length+st.json.err.length+st.rows.reduce(function(a,R){return a+(R.err.length?1:0)},0);
  st.warns=st.url.warn.length+st.json.warn.length+st.gen.length+st.rows.reduce(function(a,R){return a+(!R.err.length&&R.warn.length?1:0)},0);
  return st;
}
function sysJsonEval(h,st){
  var s=String(h.json||'').trim(), o;
  if(!s){ st.json.warn.push('JSON is empty — no parameters are sent'); return }
  try{ o=JSON.parse(s) }catch(e){ st.json.err.push('Invalid JSON: '+e.message); return }
  if(!o||typeof o!=='object'||Array.isArray(o)){ st.json.err.push('JSON must be an object like { "name": "value" }'); return }
  var keys=Object.keys(o);
  if(!keys.length) st.json.warn.push('The JSON has no properties — no parameters are sent');
  keys.forEach(function(k){
    var v=o[k];
    if(SYS_NAME_BAD.test(k)) st.json.err.push('"'+k+'": parameter name must not contain spaces or the characters & = ? #');
    if(v&&typeof v==='object'){ st.json.err.push('"'+k+'": Query Parameters only accept flat values (string, number, true/false) — not objects or arrays'); return }
    if(typeof v!=='string') return;
    var e=sysEntry(v,st.vi);
    e.bad.forEach(function(x){ st.json.err.push('"'+k+'": variable {{'+x+'}} cannot be used in this node') });
    if(e.bad.length||!st.paths.length) return;
    var miss=st.paths.filter(function(P){ return !sysAvail(e,P) });
    if(miss.length&&!e.empty) st.json.warn.push('"'+k+'" uses a variable available only on some branches — a ticket on branch '+miss[0].label+' will be sent empty. JSON mode has no Variable value; switch to Using Fields Below if you need a fallback value');
  });
}
function sysBad(n){ return n.t==='sys'&&sysEval(n).errs>0 }


var SYS_IC={
  up:'<path d="M18 15l-6-6-6 6"/>', down:'<path d="M6 9l6 6 6-6"/>',
  copy:'<rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/>',
  search:'<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>',
  bag:'<path d="M4 7h16l-1.5 12.5a2 2 0 0 1-2 1.5h-9a2 2 0 0 1-2-1.5z"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/>'
};
