function previewFlow(){
  var d=def();
  var rows=d.nodes.map(function(n){
    var outs=d.links.filter(function(l){return l.f===n.id});
    return '<tr><td><span class="chip nb" style="background:'+NT[n.t].c+'20;color:'+NT[n.t].c+';border-color:'+NT[n.t].c+'55">'+NT[n.t].sn+'</span></td>'+
     '<td><div class="c-main">'+esc(n.name)+'</div><div class="c-sub mono">'+n.id+'</div></td>'+
     '<td>'+esc(n.who||n.cond||(n.t==='sys'?sysLabel(n):'')||'—')+'</td>'+
     '<td class="num">'+(n.sla?n.sla+' h':'—')+'</td>'+
     '<td>'+(NT[n.t].form?bcDataCount(n)+' fields':'—')+'</td>'+
     '<td>'+(outs.length?outs.map(function(l){
        var tn=nodeById(l.to);
        return '<div style="font-size:12px">'+(l.lbl?'<b style="color:'+linkColor(l)+'">'+esc(lkTxt(l))+'</b> → ':'→ ')+esc(tn?tn.name:l.to)+'</div>';
      }).join(''):'<span style="color:var(--ink-3)">End</span>')+'</td></tr>';
  }).join('');
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>Preview whole flow</h2>'+
   '<div class="meta"><span>'+esc(d.n)+'</span><span>·</span><span class="mono">'+wfShowCode(DSN.id)+'</span></div>'+
   '<div class="meta" style="margin-top:7px"><span class="chip c-brand nb">'+d.nodes.length+(d.nodes.length===1?' node':' nodes')+'</span>'+
   '<span class="chip c-draft nb">'+d.links.length+(d.links.length===1?' link':' links')+'</span></div></div>'+
   '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
   '<div class="drw-b"><div class="card" style="box-shadow:none"><div class="card-h"><h2>Specification table generated from the drawing</h2></div>'+
   '<div class="card-b flush"><div class="tbl-wrap"><table class="tbl" style="min-width:0"><thead><tr>'+
   '<th>Type</th><th>Step name</th><th>Person / condition</th><th>SLA</th><th>Form</th><th>Continue</th></tr></thead><tbody>'+
   rows+'</tbody></table></div></div></div>'+
   '<div class="alert a-info" style="margin-top:14px">'+svg(I.info)+
   '<div><b>This table is the hand-off to the development team</b>Each row corresponds to one node in the drawing. When publishing, the system generates the engine definition from exactly this table.</div></div>'+
   '</div><div class="drw-f"><button class="btn" onclick="toast(\'Spec exported\',\'The Excel file is downloading\')">'+svg(I.down)+'Export spec</button>'+
   '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">Close</button></div>');
}


