function srcMt(role,sub,date,wf,extra){
  var rows=MATRIX.concat(extra||[]).filter(function(r){
    return r.emp===sub&&r.roles.indexOf(role.id)>=0&&mtActive(r,date)&&(!r.wf.length||r.wf.indexOf(wf)>=0);
  });
  var sp=rows.filter(function(r){return r.wf.length});
  if(sp.length) rows=sp;                              
  if(!rows.length) return {list:[],note:'No row declared for '+uname(sub)+' with role '+role.n+' on '+dmy(date)+' (workflow '+wfNm(wf)+')'};
  var l=[]; rows.forEach(function(r){ if(l.indexOf(r.appr)<0) l.push(r.appr) });
  return {list:l,note:'Row '+rows.map(function(r){return r.id||'(being entered)'}).join(', ')+(sp.length?' — declared for a specific workflow':' — All workflows'),rows:rows};
}
function srcRt(role,sub,date){
  if(role.loai!=='cap') return {na:1,note:'Not applicable to Functional roles'};
  var cur=sub;
  for(var i=1;i<=role.cap;i++){
    var u=userBy(cur), nx=u?u.ql:'';
    if(!nx) return {list:[],note:i===1?uname(sub)+' has no line manager on HRM':'The reporting chain of '+uname(sub)+' has only '+(i-1)+' levels, fewer than level '+role.cap};
    cur=nx;
  }
  return {list:[cur],note:'The manager '+uname(sub)+' '+role.cap+' levels above, per HRM'};
}
function srcUg(role,sub,date){
  if(role.loai!=='cn') return {na:1,note:'Not applicable to By-reporting-level roles'};
  var unit=unitOf(sub);
  if(!role.hrm.length) return {list:[],note:'Role '+role.n+' has no HRM role code mapped, so User Group cannot return anyone (BR-29)'};
  var recs=ugHolders(unit,role.id), l=[], exp={};
  recs.forEach(function(x){ if(l.indexOf(x.acc)<0) l.push(x.acc); if(recStatus(x,date)==='exp') exp[x.acc]=1 });
  if(!recs.length) return {list:[],note:'Company '+unitName(unit)+' has no holder of '+role.n+' in the HRM sync snapshot '+ugAtStr(unit)};
  return {list:l,exp:exp,note:'HRM sync snapshot of '+unitName(unit)+' at '+ugAtStr(unit)};
}
function resolve(role,sub,date,wf,ord,o){
  o=o||{}; ord=ord||DEF_ORD;
  var steps=[], stop='', final=[];
  ord.forEach(function(k){
    var st={k:k,name:SRC_NAME[k]};
    if(stop){ st.state='skip'; st.note='Not queried because an earlier source already found someone'; steps.push(st); return }
    var r=k==='mt'?srcMt(role,sub,date,wf,o.extra):k==='rt'?srcRt(role,sub,date):srcUg(role,sub,date);
    if(r.na){ st.state='na'; st.note=r.note; steps.push(st); return }
    st.ret=r.list.slice(); st.note=r.note; st.rows=r.rows||[]; st.ok=[]; st.ex=[];
    r.list.forEach(function(a){
      var why=(r.exp&&r.exp[a])?'Expired':badReason(a,sub);
      if(why) st.ex.push({acc:a,why:why}); else st.ok.push(a);
    });
    if(st.ok.length){ st.state='hit'; stop=k; final=st.ok.slice() } else st.state='none';
    steps.push(st);
  });
  var dl=[];
  final=final.map(function(a){                         /* BR-12 */
    var d=delegOf(a,date,wf);
    if(d&&!badReason(d.to,sub)){ dl.push({from:a,to:d.to,gc:d.gc}); return d.to }
    return a;
  });
  return {steps:steps,stop:stop,final:final,deleg:dl,queue:!stop};
}
function ordIsDefault(ord){ return JSON.stringify(ord||DEF_ORD)===JSON.stringify(DEF_ORD) }

function ordWarn(role,ord){
  if(!role) return '';
  ord=ord||DEF_ORD;
  var sh=role.loai==='cap'?'rt':'ug', i=ord.indexOf(sh), j=ord.indexOf('mt');
  if(i>=0&&j>=0&&i<j) return role.loai==='cap'
    ?'Report to is ordered before Matrix: a matrix row is used only when the submitter has no manager on HRM. To let a dedicated row beat the HRM manager, move Matrix to the top.'
    :'User Group is ordered before Matrix: a matrix row is used only when User Group has no valid person. To let a dedicated row win, move Matrix to the top.';
  return '';
}
function ordHasAny(role,ord){ return (ord||DEF_ORD).some(function(k){ return srcApplies(k,role) }) }


function approvalNodes(defId){
  return (DEFS[defId]?DEFS[defId].nodes:[]).filter(function(n){return n.t==='task'}).sort(function(a,b){return a.x-b.x});
}
function roleUsage(roleId){
  var out=[];
  Object.keys(DEFS).forEach(function(k){
    approvalNodes(k).forEach(function(n){ if(n.role===roleId) out.push({d:k,dn:DEFS[k].n,v:DEFS[k].v,pub:DEFS[k].pub,node:n,ord:nodeOrd(n),unit:wfUnit(k)}) });
  });
  return out;
}
function mtUsage(roleId,unit){
  return MATRIX.filter(function(r){ var s=mtSt(r); return r.roles.indexOf(roleId)>=0&&(s==='on'||s==='soon')&&(!unit||unitOf(r.emp)===unit) }).length;
}

(function(){
  var map={n2:'QL1',n4:'TPNS',s2:'QL1',s4:'GD',o2:'QL1',o4:'TPNS'};
  Object.keys(DEFS).forEach(function(k){
    DEFS[k].nodes.forEach(function(n){
      if(n.t==='task'&&map[n.id]){ n.role=map[n.id]; n.who=roleBy(n.role).n; n.multi='any'; n.auto=1 }
      if(n.t==='start'&&n.who==='Direct Manager') n.who='Level 1 manager';
    });
  });
  
  if(DEFS['salary-increase-demo']) DEFS['salary-increase-demo'].ord=['rt','mt','ug'];
})();
var WHO_ACC={'Level 1 manager':'dungvt4','Level 2 manager':'hungvq','HR Manager':'haptt','Director':'hungvq','Chief Accountant':'binhdt','HR Officer':'lanlt','Legal':'phuongnt'};


var ACTORS={
 grp:{n:'Group BPM admin',s:'Whole group',acc:'admin',av:'QT',units:['fsoft','fptis','ftel']},
 hr:{n:'Unit HR admin',s:'Fsoft',acc:'hr.fsoft',av:'HR',units:['fsoft']},
 des:{n:'Workflow designer',s:'View & configure nodes',acc:'designer1',av:'TK',units:['fsoft','fptis','ftel']}
};
var ACT='grp';
var PERM={roleEdit:['grp'],map:['grp'],sync:['grp','hr'],confirm:['grp'],mt:['grp','hr'],queue:['grp','hr']};

function can(p,unit){
  if(PERM[p].indexOf(ACT)<0) return false;
  if(unit&&(p==='sync'||p==='mt'||p==='queue')&&ACTORS[ACT].units.indexOf(unit)<0) return false;
  return true;
}
var AUD_IP='10.20.4.11';
function auditLog(h,dt){ AUDIT.unshift({t:nowStr(),u:ACTORS[ACT].acc,h:h,dt:dt||'—',ip:AUD_IP,nc:0}) }
function denied(what){
  auditLog('Access denied (403)',what);
  toast('403 — No permission',what+'. The action has been logged.');
  return false;
}
function guard(p,unit,what){ if(can(p,unit)) return true; return denied(what||'You do not have enough permission for this action') }
function renderActor(){
  var s=document.getElementById('actorSel'); if(s) s.value=ACT;
  var a=ACTORS[ACT], av=document.querySelector('.tb-user .av'), nm=document.querySelector('.tb-user .nm');
  if(av) av.textContent=a.av; if(nm) nm.textContent=a.n+' · '+a.s;
}
function pageVisible(k){ return true }
function setActor(a){
  ACT=a; renderActor(); DRWCLOSE();
  var k=pageVisible(page)?page:'thiet-ke';
  toast('Viewing as role “'+ACTORS[a].n+'”','For testing permissions in this demo only; the real product uses the signed-in account');
  go(k);
}
function DRWCLOSE(){ try{ closeDrawer() }catch(e){} }
function unitsFor(){ return ACT==='hr'?['fsoft']:['fsoft','fptis','ftel'] }


var ORDDRAG=-1;

function defOfNode(n){ var ks=Object.keys(DEFS); for(var i=0;i<ks.length;i++){ if(DEFS[ks[i]].nodes.indexOf(n)>=0) return DEFS[ks[i]] } return null }
function wfOrd(d){ return (d&&d.ord&&d.ord.length===3)?d.ord:DEF_ORD.slice() }
function nodeOrd(n){ return wfOrd(defOfNode(n)) }
function nodeLog(n,what){ auditLog('Edit Approval step configuration',wfNm(DSN.id)+' · '+n.name+': '+what) }
function roleOptLabel(r){ return r.n+' · '+roleSub(r)+(r.on?'':' (disabled)') }

function v8StartWho(n){
  var opts=['Ticket submitter'].concat(ROLES.filter(function(r){return r.on}).map(function(r){return r.n}));
  if(opts.indexOf(n.who)<0) opts.push(n.who);
  return '<div class="field"><label>Performer</label><select class="inp" onchange="setProp(\'who\',this.value)">'+
    opts.map(function(w){return '<option'+(n.who===w?' selected':'')+'>'+esc(w)+'</option>'}).join('')+'</select>'+
    '</div>';
}

function wfRoles(d){ var seen={}, out=[]; d.nodes.forEach(function(n){ if(n.t==='task'&&n.role&&!seen[n.role]){ seen[n.role]=1; var r=roleBy(n.role); if(r) out.push(r) } }); return out }
function ordRowsHTML(ord,roles){
  return ord.map(function(k,i){
    var ap=!roles.length||roles.some(function(r){return srcApplies(k,r)});
    return '<div class="ord-r'+(ap?'':' dim')+'" role="listitem" draggable="true" data-i="'+i+'"'+
      ' ondragstart="ordDragStart(event,'+i+')" ondragover="ordOver(event)" ondrop="ordDrop(event,'+i+')" ondragend="ordDragEnd()">'+
      '<span class="grip" aria-hidden="true">⋮⋮</span><span class="idx">'+(i+1)+'</span>'+
      '<div class="ord-t"><b>'+SRC_NAME[k]+'</b><span>'+esc(srcDesc(k))+'</span></div>'+
      '<button class="xb" aria-label="Move '+SRC_NAME[k]+' up" title="Up" onclick="ordMove('+i+',-1)"'+(i===0?' disabled':'')+'>'+svg('<path d="M12 19V6M6 12l6-6 6 6"/>')+'</button>'+
      '<button class="xb" aria-label="Move '+SRC_NAME[k]+' down" title="Down" onclick="ordMove('+i+',1)"'+(i===2?' disabled':'')+'>'+svg('<path d="M12 5v13M6 12l6 6 6-6"/>')+'</button>'+
      '</div>';
  }).join('');
}

function inspTask(n){
  var role=roleBy(n.role);
  return '<div class="field"><label for="nodeRole">Role to approve <span style="color:var(--danger)">*</span></label>'+
    '<select class="inp'+(role&&role.on?'':' bad')+'" id="nodeRole" onchange="nodeRole(this.value)">'+
    '<option value="">— Select a role —</option>'+
    ROLES.filter(function(r){return r.on||r.id===n.role}).map(function(r){
      return '<option value="'+r.id+'"'+(n.role===r.id?' selected':'')+'>'+esc(roleOptLabel(r))+'</option>'}).join('')+'</select>'+
    (!role?'<span class="hint" style="color:var(--danger)">No role selected — cannot publish (BR-01).</span>'
      :!role.on?'<span class="hint" style="color:var(--danger)">This role is disabled — switch to another role before publishing.</span>'
      :'<span class="hint">'+esc(role.mo)+'</span>')+'</div>';
}
function nodeRole(v){
  var n=nodeById(DSN.sel); if(!n) return;
  var o=n.role?(roleBy(n.role)||{}).n:'(not selected)', r=roleBy(v);
  n.role=v; n.who=r?r.n:'';
  if(!n.multi) n.multi='any'; if(n.auto===undefined) n.auto=1;
  nodeLog(n,'role '+o+' → '+(r?r.n:'(not selected)'));
  renderNodes(); renderInsp(); markDirty();
}
function nodeK(k,v,txt){
  var n=nodeById(DSN.sel); if(!n) return; n[k]=v;
  nodeLog(n,txt); renderNodes(); renderInsp(); markDirty();
}
function ordApply(ord,txt){
  var d=def(); d.ord=ord;
  auditLog('Edit approver lookup order',wfNm(DSN.id)+': '+txt);
  markDirty(); drawWfOrd(); try{ renderNodes() }catch(e){}
}
function ordTxt(o){ return 'lookup order '+o.map(function(k){return SRC_NAME[k]}).join(' → ') }
function ordMove(i,dl){
  var o=wfOrd(def()).slice(), j=i+dl; if(j<0||j>2) return;
  var t=o[i]; o[i]=o[j]; o[j]=t; ordApply(o,ordTxt(o));
}
function ordReset(){ ordApply(DEF_ORD.slice(),'restore default order') }
function ordDragStart(e,i){ ORDDRAG=i; try{ e.dataTransfer.effectAllowed='move'; e.dataTransfer.setData('text/plain',String(i)) }catch(x){} }
function ordOver(e){ e.preventDefault() }
function ordDragEnd(){ ORDDRAG=-1 }
function ordDrop(e,j){
  e.preventDefault(); if(ORDDRAG<0||ORDDRAG===j){ ORDDRAG=-1; return }
  var o=wfOrd(def()).slice(), k=o.splice(ORDDRAG,1)[0]; o.splice(j,0,k); ORDDRAG=-1;
  ordApply(o,ordTxt(o));
}

function openWfOrd(){ drawWfOrd() }
function drawWfOrd(){
  var d=def(), ord=wfOrd(d), roles=wfRoles(d), steps=approvalNodes(DSN.id);
  var warns=roles.map(function(r){ var w=ordWarn(r,ord); return w?{r:r,w:w}:null }).filter(Boolean);
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>Approver lookup order</h2>'+
    '<div class="meta"><span>'+esc(d.n)+' · applies to '+steps.length+' approval steps of this workflow</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
    '<div class="drw-b"><div class="field"><div class="ord-h"><label>Order of sources</label>'+
    '<button class="link" onclick="ordReset()"'+(ordIsDefault(ord)?' disabled style="opacity:.45;cursor:default"':'')+'>Restore default</button></div>'+
    '<div class="ord" role="list" aria-label="Approver lookup order">'+ordRowsHTML(ord,roles)+'</div>'+
    '<span class="hint">The system asks each source from top to bottom and stops at the first one that has a valid person. Drag and drop or use the up/down buttons to reorder. Default: Matrix → Report to → User Group.</span></div>'+
    warns.map(function(x){ return '<div class="alert a-warn" style="margin-bottom:10px">'+svg(I.warn)+'<div><b>A source is shadowed — '+esc(x.r.n)+'</b>'+esc(x.w)+'</div></div>' }).join('')+
    (ordIsDefault(ord)?'':'<div class="ord-tag">'+svg(I.info)+'Order changed from default</div>')+
    '<div class="field" style="margin-top:12px"><label>Approval steps using this order</label>'+
    (steps.length?steps.map(function(n){ var r=roleBy(n.role); return '<div class="lk-r"><span class="lk-n">'+esc(n.name)+'</span><span class="chip c-draft nb">'+esc(r?r.n:'No role selected')+'</span></div>' }).join(''):'<div class="insp-note">This workflow has no Approval step node.</div>')+'</div>'+
    '<div class="insp-note">Changes are saved in the draft and apply to new tickets after you click Publish.</div></div>'+
    '<div class="drw-f"><button class="btn" style="margin-left:auto" onclick="closeDrawer()">Close</button></div>');
}


function publishErrors(){
  var errs=[];
  def().nodes.forEach(function(n){
    if(n.t==='task'){
      var r=roleBy(n.role);
      if(!r) errs.push({n:n,m:'No role selected to approve (BR-01)'});
      else if(!r.on) errs.push({n:n,m:'Using role “'+r.n+'” which is disabled (BR-25)'});
    }
    if(sysBad(n)) errs.push({n:n,m:'Remaining: '+sysEval(n).errs+' error in the API call configuration',sys:1});
  });
  return errs;
}
function pubGoto(id){
  closeDrawer(); DSN.inspOn=true; DSN.sel=id; DSN.tab='cf'; renderNodes(); renderInsp();
  var n=nodeById(id); if(n&&n.t==='sys') sysJump();
}
function publishDef(){
  var errs=publishErrors();
  if(errs.length){
    showDrawer('<div class="drw-h"><div style="flex:1"><h2>Couldn’t publish</h2>'+
      '<div class="meta"><span>'+esc(def().n)+' · '+errs.length+(errs.length===1?' node':' nodes')+' to fix before publishing</span></div></div>'+
      '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
      '<div class="drw-b"><div class="alert a-dgr" style="margin-bottom:14px">'+svg(I.warn)+'<div><b>Publishing blocked</b>Every Approval step node must have a role in use so the system knows how to look up the approver for a ticket. Fix the nodes below, then publish again.</div></div>'+
      '<div class="card" style="box-shadow:none"><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Node</th><th>Error</th><th></th></tr></thead><tbody>'+
      errs.map(function(e){
        return '<tr><td class="c-main">'+esc(e.n.name)+'<div class="mono" style="font-size:11px;color:var(--ink-3)">'+e.n.id+'</div></td><td>'+esc(e.m)+'</td>'+
          '<td class="r"><button class="btn xs" onclick="pubGoto(\''+e.n.id+'\')">Go to node</button></td></tr>';
      }).join('')+'</tbody></table></div></div></div></div>'+
      '<div class="drw-f"><button class="btn" style="margin-left:auto" onclick="closeDrawer()">Close</button></div>');
    return;
  }
  var d=def(); d.v++; d.pub=1; DSN.dirty=0;
  var e=document.getElementById('dsnState'); if(e)e.innerHTML='<span class="chip c-done">Published · v'+d.v+'</span>';
  auditLog('Publish workflow',DSN.id+' version '+d.v);
  toast('Published v'+d.v,'Tickets submitted from now on run on this version; older tickets keep the previous version');
}


function optsHTML(list,cur){ return list.map(function(x){return '<option value="'+esc(x[0])+'"'+(String(x[0])===String(cur)?' selected':'')+'>'+esc(x[1])+'</option>'}).join('') }
function unitOpts(cur,allowed){ return optsHTML((allowed||unitsFor()).map(function(u){return [u,unitName(u)]}),cur) }
function roBadge(){ return '<span class="chip c-draft nb">'+svg(I.lock)+'Read-only</span>' }
function empty(ic,t,p){ return '<div class="empty">'+svg(ic)+'<b>'+t+'</b>'+(p?'<p>'+p+'</p>':'')+'</div>' }
function allHrmCodes(){
  var m={}; Object.keys(UGS).forEach(function(u){ UGS[u].recs.forEach(function(x){ m[x.code]=1 }) });
  Object.keys(HRM_NAMES).forEach(function(c){ m[c]=1 });
  return Object.keys(m).sort();
}
function codeCount(code,unit){ return UGS[unit].recs.filter(function(x){return x.code===code}).length }
function roleWarns(r,unit){
  var out=[];
  if(r.loai==='cn'&&r.on&&roleUsage(r.id).length){
    if(!r.hrm.length) out.push('In use by nodes but no HRM role code is mapped');
    else if(!ugHolders(unit,r.id).filter(function(x){return recStatus(x)==='on'}).length) out.push(unitName(unit)+' has no valid holder in the sync snapshot');
  }
  return out;
}
