ldInitLo();
var LANG='en';
WF_CODE['business-trip']='CONG_TAC';WF_CODE['advance-payment']='TAM_UNG';WF_CODE['timesheet-confirm']='XAC_NHAN_CONG';WF_CODE['shift-change']='DOI_CA';WF_CODE['resignation']='THOI_VIEC';

/* =====================================================================
   v17 — NODE BƯỚC DUYỆT: nguồn chính (4 lựa chọn) + thứ tự ưu tiên dự phòng
   n.ap = {main:'rt'|'ug'|'mt'|'fx', cap, code, acc, hoTen, prio:[{k:'rt',cap},{k:'ug',code},{k:'mt'}]}
   ===================================================================== */
function tx(a,b){ return LANG==='en'?b:a }
var AP={drag:-1};
var AP_SRC_N={rt:['Report to','Report to'],ug:['User Group','User Group'],mt:['Ma trận phê duyệt','Approval matrix'],fx:['Chỉ định đích danh','Named approver']};
function apSrcName(k){ return tx(AP_SRC_N[k][0],AP_SRC_N[k][1]) }
var AP_MAXCAP=5;
function capName(c){ return tx('Quản lý cấp '+c,'Level '+c+' manager') }
function posName(c){ return (typeof HRM_NAMES!=='undefined'&&HRM_NAMES[c])||c||'' }
function ugPositions(){
  var m={}, out=[];
  Object.keys(HRM_NAMES).forEach(function(c){ m[c]=1; out.push([c,HRM_NAMES[c]]) });
  Object.keys(UGS).forEach(function(u){ UGS[u].recs.forEach(function(x){ if(!m[x.code]){ m[x.code]=1; out.push([x.code,posName(x.code)]) } }) });
  return out;
}
function apDefPrio(){ return [{k:'rt',cap:1},{k:'ug',code:''},{k:'mt'}] }
function apGet(n){
  var a=n.ap;
  if(!a) a=n.ap={main:'rt',cap:1,code:'',acc:'',hoTen:'',prio:apDefPrio()};
  if(!a.main){                                   /* chuyển từ dạng v16 {mode,src} */
    var src=a.src||[];
    if(a.mode==='fixed') a.main='fx';
    else if(src.length){ a.main=src[0].k; a.cap=src[0].cap||1; a.code=src[0].code||'' }
    else a.main='rt';
    var pr=[];
    src.forEach(function(s){ if(!pr.some(function(p){return p.k===s.k})) pr.push({k:s.k,cap:s.cap||1,code:s.code||''}) });
    ['rt','ug','mt'].forEach(function(k){ if(!pr.some(function(p){return p.k===k})) pr.push(k==='rt'?{k:'rt',cap:1}:k==='ug'?{k:'ug',code:''}:{k:'mt'}) });
    a.prio=pr; delete a.src; delete a.mode;
  }
  if(!a.prio||a.prio.length!==3) a.prio=apDefPrio();
  if(!a.cap) a.cap=1;
  return a;
}
function apParamLabel(k,o){ return k==='rt'?capName(o.cap||1):k==='ug'?(posName(o.code)||tx('chưa chọn chức vụ','no position')):k==='mt'?apSrcName('mt'):'' }
function apShort(k,o){ return k==='mt'?tx('Ma trận','Matrix'):k==='rt'?tx('QL cấp ','Mgr L')+(o.cap||1):(posName(o.code)||'User Group') }
function apWho(n){
  var a=apGet(n);
  if(a.main==='fx'){ var u=userBy(a.acc); return (u?u.n:(a.hoTen||tx('Chưa chỉ định','Not set')))+(a.acc?' · '+a.acc:'') }
  return apShort(a.main,a);
}
function apSync(n){ if(n&&n.t==='task') n.who=apWho(n) }
function apErrors(n){
  var a=apGet(n), e=[];
  if(a.main==='fx'){
    var u=userBy(a.acc);
    if(!a.acc) e.push(tx('Chưa nhập account người duyệt đích danh','Named approver account is empty'));
    else if(!u) e.push(tx('Account “'+a.acc+'” không có trong danh bạ','Account “'+a.acc+'” is not in the directory'));
    else if(uStat(u.u)==='left') e.push(tx('Người duyệt đích danh đã nghỉ việc','The named approver has left the company'));
    else if(uStat(u.u)==='locked') e.push(tx('Account người duyệt đích danh đang bị khoá','The named approver account is locked'));
  } else if(a.main==='ug'&&!a.code) e.push(tx('User Group chưa chọn chức vụ','User Group has no position selected'));
  return e;
}

/* ---- bộ tra ---- */
function apMt(sub,date,wf,extra){
  var rows=MATRIX.concat(extra||[]).filter(function(r){ return r.emp===sub&&mtActive(r,date)&&(!r.wf.length||r.wf.indexOf(wf)>=0) });
  var sp=rows.filter(function(r){return r.wf.length}); if(sp.length) rows=sp;
  var l=[]; rows.forEach(function(r){ if(l.indexOf(r.appr)<0) l.push(r.appr) });
  return {list:l,rows:rows};
}
function apRt(cap,sub){
  var cur=sub;
  for(var i=1;i<=cap;i++){ var u=userBy(cur), nx=u?u.ql:''; if(!nx) return {list:[]}; cur=nx }
  return {list:[cur]};
}
function apUg(code,sub){
  var unit=unitOf(sub); if(!code) return {list:[]};
  var l=[]; ugMembers(unit,code).forEach(function(acc){ if(l.indexOf(acc)<0) l.push(acc) });
  return {list:l};
}
function apTry(k,o,sub,date,wf,extra){
  var r=k==='mt'?apMt(sub,date,wf,extra):k==='rt'?apRt(o.cap||1,sub):apUg(o.code,sub);
  return r.list.filter(function(x){ return !badReason(x,sub) });
}
function apResolve(n,sub,date,wf,extra){
  var a=apGet(n), final=[], used='';
  if(a.main==='fx'){ if(a.acc&&!badReason(a.acc,sub)){ final=[a.acc]; used='fx' } }
  else {
    final=apTry(a.main,a,sub,date,wf,extra); if(final.length) used=a.main;
    if(!final.length) a.prio.some(function(p){ if(p.k===a.main) return false; final=apTry(p.k,a,sub,date,wf,extra); if(final.length){ used=p.k; return true } return false });
  }
  var dl=[];
  final=final.map(function(x){ var d=delegOf(x,date,wf); if(d&&!badReason(d.to,sub)){ dl.push({from:x,to:d.to}); return d.to } return x });
  return {final:final,used:used,deleg:dl,queue:!final.length};
}
function approverMa(n){
  try{ if(n.t==='task'){ var r=apResolve(n,'annv',TODAY,DSN.id); var u=userBy(r.final[0]||''); if(u) return u.ma } }catch(e){}
  return 'NV-00000';
}

/* ---- panel cấu hình ---- */
function apCapSel(val,on){ var o=''; for(var c=1;c<=AP_MAXCAP;c++) o+='<option value="'+c+'"'+((val||1)===c?' selected':'')+'>'+capName(c)+'</option>'; return '<select class="inp ap-sel" aria-label="'+tx('Cấp quản lý','Manager level')+'" onchange="'+on+'">'+o+'</select>' }
function apPosSel(val,on,bad){
  return '<select class="inp ap-sel'+(bad?' bad':'')+'" aria-label="'+tx('Chức vụ','Position')+'" onchange="'+on+'"><option value="">'+tx('— Chọn chức vụ —','— Select position —')+'</option>'+
    ugPositions().map(function(p){ return '<option value="'+esc(p[0])+'"'+(val===p[0]?' selected':'')+'>'+esc(p[1])+'</option>' }).join('')+'</select>';
}
function inspTask(n){
  var a=apGet(n), h='';
  h+='<div class="field"><label>'+tx('Người duyệt','Approver')+'</label><div class="ap-opts" role="radiogroup" aria-label="'+tx('Người duyệt','Approver')+'">';
  ['rt','ug','mt','fx'].forEach(function(k){
    var on=a.main===k, body='';
    if(on&&k==='rt') body=apCapSel(a.cap,"apMainSet('cap',+this.value)");
    if(on&&k==='ug') body=apPosSel(a.code,"apMainSet('code',this.value)",!a.code);
    if(on&&k==='fx'){
      var u=userBy(a.acc), err='';
      if(a.acc&&!u) err=tx('Account không có trong danh bạ','Account is not in the directory');
      else if(u&&uStat(u.u)==='left') err=tx('Người này đã nghỉ việc','This person has left the company');
      else if(u&&uStat(u.u)==='locked') err=tx('Account đang bị khoá','Account is locked');
      body='<datalist id="apUsers">'+USERS.filter(function(x){return uStat(x.u)==='on'}).map(function(x){ return '<option value="'+esc(x.n+' · '+x.u)+'">' }).join('')+'</datalist>'+
        '<div class="ap-fxg"><div class="field"><label for="ap_nm">'+tx('Họ tên','Full name')+' <span style="color:var(--danger)">*</span></label>'+
        '<input class="inp" id="ap_nm" list="apUsers" value="'+esc(a.hoTen||'')+'" placeholder="'+tx('Gõ họ tên…','Type a name…')+'" autocomplete="off" onchange="apFixed(\'nm\',this.value)"></div>'+
        '<div class="field"><label for="ap_acc">Account <span style="color:var(--danger)">*</span></label>'+
        '<input class="inp mono'+(err?' bad':'')+'" id="ap_acc" list="apUsers" value="'+esc(a.acc||'')+'" placeholder="'+tx('Ví dụ: haptt','e.g. haptt')+'" autocomplete="off" onchange="apFixed(\'acc\',this.value)">'+
        (err?'<span class="hint" style="color:var(--danger)">'+esc(err)+'</span>':'')+'</div></div>';
    }
    h+='<div class="ap-opt'+(on?' on':'')+'"><label class="ap-oh"><input type="radio" name="ap_main" '+(on?'checked':'')+' onchange="apMain(\''+k+'\')"><b>'+apSrcName(k)+'</b></label>'+(body?'<div class="ap-ob">'+body+'</div>':'')+'</div>';
  });
  h+='</div></div>';
  if(a.main!=='fx'){
    h+='<div class="field"><label>'+tx('Thứ tự ưu tiên','Priority order')+'</label>'+
      '<div class="ord" role="list" aria-label="'+tx('Thứ tự ưu tiên','Priority order')+'">'+a.prio.map(function(p,i){
        var ctl='';
        return '<div class="ord-r ap-r" role="listitem" draggable="true" ondragstart="apDragStart(event,'+i+')" ondragover="event.preventDefault()" ondrop="apDrop(event,'+i+')" ondragend="AP.drag=-1">'+
          '<span class="grip" aria-hidden="true">⋮⋮</span><span class="idx">'+(i+1)+'</span>'+
          '<div class="ord-t"><b>'+apSrcName(p.k)+'</b>'+ctl+'</div>'+
          '<div class="ap-btns"><button class="xb" title="'+tx('Lên','Up')+'" aria-label="'+tx('Đưa lên','Move up')+'" onclick="apMove('+i+',-1)"'+(i===0?' disabled':'')+'>'+svg('<path d="M12 19V6M6 12l6-6 6 6"/>')+'</button>'+
          '<button class="xb" title="'+tx('Xuống','Down')+'" aria-label="'+tx('Đưa xuống','Move down')+'" onclick="apMove('+i+',1)"'+(i===2?' disabled':'')+'>'+svg('<path d="M12 5v13M6 12l6 6 6-6"/>')+'</button></div></div>';
      }).join('')+'</div></div>';
  }
  return h;
}
function apChange(n,txt){ apSync(n); try{ nodeLog(n,txt) }catch(e){} renderNodes(); renderInsp(); markDirty() }
function apNode(){ var n=nodeById(DSN.sel); return n&&n.t==='task'?n:null }
function apMain(k){ var n=apNode(); if(!n) return; var a=apGet(n); a.main=k; apChange(n,tx('người duyệt → ','approver → ')+apSrcName(k)) }
function apMainSet(f,v){ var n=apNode(); if(!n) return; apGet(n)[f]=v; apChange(n,apWho(n)) }
function apPrioSet(i,f,v){ var n=apNode(); if(!n) return; apGet(n).prio[i][f]=v; apChange(n,tx('thứ tự ưu tiên','priority order')) }
function apMove(i,d){ var n=apNode(); if(!n) return; var p=apGet(n).prio, j=i+d; if(j<0||j>2) return; var t=p[i]; p[i]=p[j]; p[j]=t; apChange(n,tx('thứ tự ưu tiên','priority order')) }
function apDragStart(e,i){ AP.drag=i; try{ e.dataTransfer.effectAllowed='move'; e.dataTransfer.setData('text/plain',String(i)) }catch(x){} }
function apDrop(e,j){
  e.preventDefault(); var n=apNode(); if(!n||AP.drag<0||AP.drag===j){ AP.drag=-1; return }
  var p=apGet(n).prio, s=p.splice(AP.drag,1)[0]; p.splice(j,0,s); AP.drag=-1; apChange(n,tx('thứ tự ưu tiên','priority order'));
}
function apParseUser(v){
  v=String(v||'').trim(); if(!v) return null;
  var p=v.split(' · '); if(p.length>1){ var u=userBy(p[p.length-1].trim().toLowerCase()); if(u) return u }
  return userBy(v.toLowerCase())||USERS.filter(function(x){return x.n.toLowerCase()===v.toLowerCase()})[0]||null;
}
function apFixed(k,v){
  var n=apNode(); if(!n) return; var a=apGet(n), u=apParseUser(v);
  if(u){ a.acc=u.u; a.hoTen=u.n }
  else if(k==='acc') a.acc=String(v||'').trim().toLowerCase();
  else a.hoTen=String(v||'').trim();
  apChange(n,apSrcName('fx')+' '+(a.hoTen||'')+' · '+(a.acc||''));
}

/* ---- tạo node mới ---- */
function newNode(t,x,y){
  DSN.seq++;
  var id='k'+DSN.seq;
  var n={id:id,t:t,x:Math.round(x),y:Math.round(y),name:NT[t].n};
  if(t==='start'){n.who=tx('Người nộp ticket','Ticket submitter');n.form=[];n._lo=[]}
  if(t==='task'){n.ap={main:'rt',cap:1,code:'',acc:'',hoTen:'',prio:apDefPrio()};n.multi='any';n.auto=1;n.sla=24;n.bosung=1;
    n.form=[{k:'quyetDinh',l:tx('Quyết định','Decision'),t:'radio',r:1,o:tx('Duyệt\nTừ chối','Approve\nReject')},{k:'yKien',l:tx('Ý kiến của người duyệt','Approver comment'),t:'area'}];n._lo=['quyetDinh','yKien'];apSync(n)}
  if(t==='gate'){n.ifc={mode:'rules',comb:'and',rules:[{l:'',t:'string',op:'equals',r:''}],js:''};n.cond=''}
  if(t==='sys'){n.http={method:'POST',url:'',sendQuery:1,qmode:'fields',params:[],json:''}}
  if(t==='end'){n.kq='duyet'}
  return n;
}

/* =====================================================================
   v16 — panel cấu hình chung, kiểm tra khi xuất bản, chuyển dữ liệu cũ
   ===================================================================== */
function inspCfg(n){
  var h='<div class="field"><label>'+tx('Tên bước','Step name')+'</label><input class="inp" value="'+esc(n.name)+'" oninput="setNodeName(this.value)"></div>';
  if(n.t==='task') h+=inspTask(n);
  if(n.t==='gate') h+=ifSummaryHTML(n);
  if(n.t==='end'){
    h+='<div class="field"><label>'+tx('Kết quả ghi nhận','Recorded result')+'</label><select class="inp" onchange="setProp(\'kq\',this.value)">'+
      [['duyet',tx('Đã duyệt','Approved')],['tuchoi',tx('Từ chối','Rejected')],['huy',tx('Đã huỷ','Cancelled')]].map(function(k){
        return '<option value="'+k[0]+'"'+(n.kq===k[0]?' selected':'')+'>'+k[1]+'</option>'}).join('')+'</select></div>'+
      '<label class="ck"><input type="checkbox" checked><span>'+tx('Đẩy kết quả về HRM khi kết thúc','Push the result to HRM when finished')+'</span></label>';
  }
  h+='<div style="border-top:1px solid var(--line);padding-top:11px;margin-top:3px">'+
     '<button class="btn sm dgr" onclick="delNode()">'+svg(I.x)+tx('Xoá node này','Delete this node')+'</button></div>';
  return h;
}

/* nhãn phiên bản hiển thị: v<chính>.<số lần xuất bản> — ví dụ v8.3 → v8.4 */
function wfVer(w){ return w&&w.v&&w.vers&&w.vers.length?'v'+w.v+'.'+w.vers.length:'—' }
/* ---- Xuất bản: kiểm tra node Bước duyệt, Rẽ nhánh, Tác vụ hệ thống ---- */
function publishErrors(){
  var errs=[];
  def().nodes.forEach(function(n){
    if(n.t==='task') apErrors(n).forEach(function(m){ errs.push({n:n,m:m}) });
    if(n.t==='gate') ifErrors(n).forEach(function(m){ errs.push({n:n,m:m,gate:1}) });
    if(sysBad(n)) errs.push({n:n,m:tx('Còn '+sysEval(n).errs+' lỗi ở phần cấu hình gọi API',sysEval(n).errs+' error(s) left in the API call settings'),sys:1});
  });
  return errs;
}
function pubGoto(id){
  closeDrawer(); DSN.inspOn=true; DSN.sel=id; DSN.tab='cf'; renderNodes(); renderInsp();
  var n=nodeById(id); if(n&&n.t==='sys') sysJump(); if(n&&n.t==='gate') ifOpen(id);
}
function publishDef(){
  var errs=publishErrors();
  if(errs.length){
    showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+tx('Chưa xuất bản được','Cannot publish yet')+'</h2>'+
      '<div class="meta"><span>'+esc(def().n)+' · '+errs.length+tx(' lỗi cần sửa trước khi xuất bản',' issue(s) to fix before publishing')+'</span></div></div>'+
      '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
      '<div class="drw-b"><div class="card" style="box-shadow:none"><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Node</th><th>'+tx('Lỗi','Issue')+'</th><th></th></tr></thead><tbody>'+
      errs.map(function(e){
        return '<tr><td class="c-main">'+esc(e.n.name)+'</td><td>'+esc(e.m)+'</td>'+
          '<td class="r"><button class="btn xs" onclick="pubGoto(\''+e.n.id+'\')">'+tx('Đi tới node','Go to node')+'</button></td></tr>';
      }).join('')+'</tbody></table></div></div></div></div>'+
      '<div class="drw-f"><button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Đóng','Close')+'</button></div>');
    return;
  }
  var d=def(); d.pub=1; DSN.dirty=0;
  var w=wfById(DSN.id), t=nowStr(), me=ACTORS[ACT].acc, old=wfVer(w);
  if(w){
    if(!w.vers) w.vers=[];
    if(!w.v) w.v=1;
    if(w.vers.length&&w.vers[0].s==='draft'&&!w.pub){ w.vers[0].s='pub'; w.vers[0].t=t; w.vers[0].w=me }   /* lần xuất bản đầu của quy trình mới */
    else w.vers.unshift({v:w.v,t:t,w:me,s:'pub',note:tx('Xuất bản phiên bản mới','Published a new version')});
    w.st='run'; w.pub=1; w.upd=t; delete w.mod;
  }
  var nv=wfVer(w);
  auditLog(tx('Xuất bản quy trình','Publish workflow'),DSN.id+' '+old+' → '+nv);
  toast(tx('Đã xuất bản ','Published ')+nv,tx('Ticket nộp từ giờ chạy theo bản này, ticket cũ giữ nguyên phiên bản trước','New tickets use this version; existing tickets keep their version'));
}

/* ---- Chuyển dữ liệu mẫu: vai trò → thứ tự ưu tiên; điều kiện chuỗi → luật ---- */
(function(){
  var R={QL1:[['rt',1]],QL2:[['rt',2]],TPNS:[['ug','TRUONG_PHONG_NS']],CBNS:[['ug','CAN_BO_NS']],KTT:[['ug','KE_TOAN_TRUONG']],GD:[['ug','GIAM_DOC']]};
  Object.keys(DEFS).forEach(function(k){
    var d=DEFS[k], ord=(d.ord&&d.ord.length===3)?d.ord:['mt','rt','ug'];
    d.nodes.forEach(function(n){
      if(n.t==='task'&&!n.ap){
        var m=R[n.role]||[['rt',1]], src=[];
        ord.forEach(function(s){
          if(s==='mt'&&m[0][0]==='rt') src.push({k:'mt'});   /* Ma trận (ai duyệt cho ai) chỉ gắn vào bước của quản lý */
          m.forEach(function(x){ if(x[0]===s) src.push(x[0]==='rt'?{k:'rt',cap:x[1]}:{k:'ug',code:x[1]}) });
        });
        n.ap={mode:'prio',src:src,acc:'',hoTen:''}; delete n.role; apSync(n);
      }
    });
    delete d.ord;
  });
  /* Ma trận: bỏ vai trò. Dòng MT-0010 (cấp 2 của Sơn) trùng phạm vi với MT-0003/0004 khi không còn vai trò → chuyển sang nhân viên chưa có quản lý */
  MATRIX.forEach(function(r){ delete r.roles });
  var r10=mtById('MT-0010'); if(r10){ r10.emp='tudv'; r10.gc=tx('Chưa có quản lý trực tiếp trên HRM — duyệt thay trong quý IV','No line manager in HRM — stand-in approver for Q4') }
})();

/* =====================================================================
   v16 — NODE RẼ NHÁNH ĐIỀU KIỆN kiểu n8n: INPUT | Parameters | OUTPUT
   n.ifc = {mode:'rules'|'js', comb:'and'|'or', rules:[{l,t,op,r}], js}
   ===================================================================== */
var IFN={id:null,tab:'par',view:'schema',src:'all',menu:null,menuT:'',ac:null,acSel:0,res:null,stale:0,edit:0,sample:{},otab:''};
var IF_TYPES=[['string','String'],['number','Number'],['dateTime','Date & Time'],['boolean','Boolean']];
var IF_U=[['exists','exists',1],['notExists','does not exist',1],['empty','is empty',1],['notEmpty','is not empty',1]];
var IF_OPS={
  string:IF_U.concat([['equals','is equal to'],['notEquals','is not equal to'],['contains','contains'],['notContains','does not contain'],['startsWith','starts with'],['notStartsWith','does not start with'],['endsWith','ends with'],['notEndsWith','does not end with'],['regex','matches regex'],['notRegex','does not match regex']]),
  number:IF_U.concat([['equals','is equal to'],['notEquals','is not equal to'],['gt','is greater than'],['lt','is less than'],['gte','is greater than or equal to'],['lte','is less than or equal to']]),
  dateTime:IF_U.concat([['equals','is equal to'],['notEquals','is not equal to'],['after','is after'],['before','is before'],['afterOrEquals','is after or equal to'],['beforeOrEquals','is before or equal to']]),
  boolean:IF_U.concat([['true','is true',1],['false','is false',1],['equals','is equal to'],['notEquals','is not equal to']])
};
var IF_SYM={equals:'=',notEquals:'≠',gt:'>',lt:'<',gte:'≥',lte:'≤',after:'>',before:'<',afterOrEquals:'≥',beforeOrEquals:'≤'};
var IF_CFG={NGUONG_PHAN_TRAM:'10',TRAN_OT_THANG:'40'};
var IF_IC={
  cal:'<rect x="3.5" y="5" width="17" height="15" rx="2"/><path d="M3.5 10h17M8 3v4M16 3v4"/>',
  tog:'<rect x="2.5" y="7" width="19" height="10" rx="5"/><circle cx="16.5" cy="12" r="3"/>',
  chev:'<path d="M6 9l6 6 6-6"/>', right:'<path d="M9 6l6 6-6 6"/>', back:'<path d="M19 12H5"/><path d="M12 19l-7-7 7-7"/>',
  flask:'<path d="M9 3h6M10 3v6l-5.5 9.5A1.7 1.7 0 0 0 6 21h12a1.7 1.7 0 0 0 1.5-2.5L14 9V3"/><path d="M7.5 15h9"/>',
  code:'<path d="M8 8l-4 4 4 4M16 8l4 4-4 4M13.5 5l-3 14"/>', list:'<path d="M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01"/>',
  pen:'<path d="M4 20h4L19 9l-4-4L4 16z"/>', grab:'<circle cx="9" cy="6" r="1"/><circle cx="15" cy="6" r="1"/><circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="9" cy="18" r="1"/><circle cx="15" cy="18" r="1"/>'
};
function ifTypeIc(t){
  if(t==='number') return '<span class="ift">#</span>';
  if(t==='dateTime') return '<span class="ift">'+svg(IF_IC.cal)+'</span>';
  if(t==='boolean') return '<span class="ift">'+svg(IF_IC.tog)+'</span>';
  return '<span class="ift">T</span>';
}
function ifTypeName(t){ return (IF_TYPES.filter(function(x){return x[0]===t})[0]||IF_TYPES[0])[1] }
function ifOp(t,op){ return (IF_OPS[t]||[]).filter(function(x){return x[0]===op})[0]||null }
function ifUnary(t,op){ var o=ifOp(t,op); return !!(o&&o[2]) }
function dtType(dt){ return dt==='number'?'number':(dt==='date'||dt==='datetime'||dt==='time')?'dateTime':dt==='boolean'?'boolean':'string' }

/* ---- biến dùng được ở node ---- */
function ifVars(n){
  var l=varsAt(n.id).slice();
  Object.keys(IF_CFG).forEach(function(k){ l.push({v:k,dt:'number',lbl:tx('Tham số cấu hình','Configuration parameter'),g:'cfg',gl:tx('Tham số cấu hình','Configuration parameters'),always:true,mau:IF_CFG[k]}) });
  return l;
}
function ifScope(n){ var o={}; ifVars(n).forEach(function(v){ o[v.v]=v }); return o }
function ifSampleOf(v){ return Object.prototype.hasOwnProperty.call(IFN.sample,v.v)?IFN.sample[v.v]:v.mau }
function ifShort(s){ return String(s||'').replace(/\{\{\s*([^}]+?)\s*\}\}/g,function(_,k){ return /^[A-Z0-9_]+$/.test(k)?'{{'+k+'}}':k.split('.').pop() }) }

/* ---- dữ liệu của node ---- */
function ifGet(n){
  if(!n.ifc){
    var rule={l:'',t:'string',op:'equals',r:''}, m=String(n.cond||'').match(/^\s*([\w.]+)\s*(>=|<=|==|!=|>|<|=)\s*(.+?)\s*$/);
    if(m){
      var v=ifVars(n).filter(function(x){ return x.v===m[1]||x.v.split('.').pop()===m[1] })[0];
      rule.l='{{'+(v?v.v:m[1])+'}}'; rule.t=v?dtType(v.dt):'number';
      var map={'>':'gt','<':'lt','>=':'gte','<=':'lte','==':'equals','=':'equals','!=':'notEquals'}, op=map[m[2]];
      if(rule.t==='dateTime') op={gt:'after',lt:'before',gte:'afterOrEquals',lte:'beforeOrEquals'}[op]||op;
      if(!ifOp(rule.t,op)){ rule.t='number' }
      rule.op=op; rule.r=m[3];
    }
    n.ifc={mode:'rules',comb:'and',rules:[rule],js:''};
  }
  return n.ifc;
}
function ifCondText(n){
  var c=ifGet(n);
  if(c.mode==='js') return 'JavaScript';
  return c.rules.filter(function(r){return r.l}).map(function(r){
    var o=ifOp(r.t,r.op), s=IF_SYM[r.op];
    return ifShort(r.l)+' '+(s||(o?o[1]:r.op))+(ifUnary(r.t,r.op)?'':' '+ifShort(r.r));
  }).join(c.comb==='or'?' OR ':' AND ');
}
function ifErrors(n){
  var c=ifGet(n), e=[], sc=ifScope(n);
  function refs(s,i,side){ String(s||'').replace(/\{\{\s*([^}]+?)\s*\}\}/g,function(_,k){ if(!sc[k]) e.push(tx('Điều kiện '+(i+1)+': biến {{'+k+'}} không có ở node này','Condition '+(i+1)+': variable {{'+k+'}} is not available at this node')) }) }
  if(c.mode==='js'){
    if(!String(c.js||'').trim()) e.push(tx('Chưa viết mã JavaScript','No JavaScript code yet'));
    else { var se=ifJsSyntax(c.js); if(se) e.push(tx('Lỗi cú pháp JavaScript: ','JavaScript syntax error: ')+se) }
    return e;
  }
  if(!c.rules.length) e.push(tx('Chưa có điều kiện nào','No condition yet'));
  c.rules.forEach(function(r,i){
    if(!String(r.l).trim()) e.push(tx('Điều kiện '+(i+1)+': chưa có value 1','Condition '+(i+1)+': value 1 is empty'));
    else refs(r.l,i);
    if(!ifUnary(r.t,r.op)){
      if(!String(r.r).trim()) e.push(tx('Điều kiện '+(i+1)+': chưa có value 2','Condition '+(i+1)+': value 2 is empty'));
      else refs(r.r,i);
    }
    if((r.op==='regex'||r.op==='notRegex')&&String(r.r).trim()&&r.r.indexOf('{{')<0){ try{ ifRegex(r.r) }catch(x){ e.push(tx('Điều kiện '+(i+1)+': regex không hợp lệ','Condition '+(i+1)+': invalid regex')) } }
  });
  return e;
}
function ifJsSyntax(code){ try{ new Function('n1','n2','n3','n4','n5','sys','cfg',code); return '' }catch(x){ return x.message } }
function ifRegex(s){ var m=String(s).match(/^\/(.*)\/([gimsuy]*)$/); return m?new RegExp(m[1],m[2]):new RegExp(s) }

/* ---- chạy thử ---- */
function ifRaw(s,sc){
  s=String(s==null?'':s);
  var m=s.match(/^\s*\{\{\s*([^}]+?)\s*\}\}\s*$/);
  if(m){ var v=sc[m[1]]; return v?{v:ifSampleOf(v)}:{miss:m[1]} }
  var miss='', out=s.replace(/\{\{\s*([^}]+?)\s*\}\}/g,function(_,k){ var v=sc[k]; if(!v){ miss=k; return '' } return ifSampleOf(v) });
  return miss?{miss:miss}:{v:out};
}
function ifDate(v){
  var s=String(v==null?'':v).trim(), m;
  if((m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?$/))) return new Date(+m[3],m[2]-1,+m[1],+(m[4]||0),+(m[5]||0)).getTime();
  if((m=s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2}))?/))) return new Date(+m[1],m[2]-1,+m[3],+(m[4]||0),+(m[5]||0)).getTime();
  if((m=s.match(/^(\d{1,2}):(\d{2})$/))) return (+m[1])*60+(+m[2]);
  return null;
}
function ifConv(t,v){
  var s=String(v==null?'':v);
  if(t==='number'){ var x=Number(s.trim().replace(',','.')); return (s.trim()===''||!isFinite(x))?{err:"'"+s+"' "+tx('không phải kiểu Number','is not a Number')}:{val:x} }
  if(t==='dateTime'){ var d=ifDate(s); return d===null?{err:"'"+s+"' "+tx('không phải kiểu Date & Time','is not a Date & Time')}:{val:d} }
  if(t==='boolean'){ var b=s.trim().toLowerCase(); if(['true','đúng','1','yes','có'].indexOf(b)>=0) return {val:true}; if(['false','sai','0','no','không'].indexOf(b)>=0) return {val:false}; return {err:"'"+s+"' "+tx('không phải kiểu Boolean','is not a Boolean')} }
  return {val:s};
}
function ifEvalRule(r,sc){
  var L=ifRaw(r.l,sc), R=ifRaw(r.r,sc), op=r.op, t=r.t, o={lv:L.v,rv:R.v};
  if(L.miss){ o.err=tx('không có biến {{'+L.miss+'}}','variable {{'+L.miss+'}} not found'); return o }
  var has=L.v!==undefined&&L.v!==null, emp=!has||String(L.v)==='';
  if(op==='exists'){ o.ok=has; return o } if(op==='notExists'){ o.ok=!has; return o }
  if(op==='empty'){ o.ok=emp; return o } if(op==='notEmpty'){ o.ok=!emp; return o }
  var a=ifConv(t,L.v); if(a.err){ o.err='Value 1: '+a.err; return o }
  if(op==='true'){ o.ok=a.val===true; return o } if(op==='false'){ o.ok=a.val===false; return o }
  if(R.miss){ o.err=tx('không có biến {{'+R.miss+'}}','variable {{'+R.miss+'}} not found'); return o }
  if(op==='regex'||op==='notRegex'){ try{ var re=ifRegex(R.v); o.ok=op==='regex'?re.test(String(a.val)):!re.test(String(a.val)) }catch(x){ o.err=tx('regex không hợp lệ','invalid regex') } return o }
  var b=ifConv(t,R.v); if(b.err){ o.err='Value 2: '+b.err; return o }
  var x=a.val, y=b.val;
  switch(op){
    case 'equals': o.ok=x===y; break; case 'notEquals': o.ok=x!==y; break;
    case 'contains': o.ok=String(x).indexOf(y)>=0; break; case 'notContains': o.ok=String(x).indexOf(y)<0; break;
    case 'startsWith': o.ok=String(x).indexOf(y)===0; break; case 'notStartsWith': o.ok=String(x).indexOf(y)!==0; break;
    case 'endsWith': o.ok=String(x).slice(-String(y).length)===String(y); break; case 'notEndsWith': o.ok=String(x).slice(-String(y).length)!==String(y); break;
    case 'gt': case 'after': o.ok=x>y; break; case 'lt': case 'before': o.ok=x<y; break;
    case 'gte': case 'afterOrEquals': o.ok=x>=y; break; case 'lte': case 'beforeOrEquals': o.ok=x<=y; break;
    default: o.err=tx('toán tử không hợp lệ','invalid operator');
  }
  return o;
}
function ifTyped(v){ var s=ifSampleOf(v); if(v.dt==='number'){ var x=Number(String(s).replace(',','.')); return isFinite(x)&&String(s).trim()!==''?x:s } if(v.dt==='boolean'){ var b=ifConv('boolean',s); return b.err?s:b.val } return s }
function ifData(n){
  var g={};
  ifVars(n).forEach(function(v){
    if(v.g==='cfg'){ (g.cfg=g.cfg||{})[v.v]=ifTyped(v); return }
    var p=v.v.split('.'), k=p.shift(); (g[k]=g[k]||{})[p.join('.')]=ifTyped(v);
  });
  return g;
}
function ifRun(n){
  var c=ifGet(n), sc=ifScope(n), res={mode:c.mode,rules:[]};
  if(c.mode==='js'){
    var g=ifData(n), names=Object.keys(g);
    try{ var v=new Function(names.join(','),c.js).apply(null,names.map(function(k){return g[k]}));
      if(typeof v!=='boolean') res.err=tx('Mã phải trả về true hoặc false (đang trả về ','The code must return true or false (returned ')+(v===undefined?'undefined':JSON.stringify(v))+')';
      else res.ok=v;
    }catch(x){ res.err=x.message }
    return res;
  }
  var vals=[];
  c.rules.forEach(function(r,i){ var o=ifEvalRule(r,sc); res.rules.push(o); if(o.err&&!res.err) res.err=tx('Điều kiện '+(i+1)+': ','Condition '+(i+1)+': ')+o.err; vals.push(!!o.ok) });
  if(!res.err) res.ok=c.comb==='or'?vals.some(Boolean):vals.every(Boolean);
  if(!c.rules.length) res.err=tx('Chưa có điều kiện nào','No condition yet');
  return res;
}
function ifRulesToJs(n){
  var c=ifGet(n);
  function ex(s,t){
    s=String(s==null?'':s).trim();
    var m=s.match(/^\{\{\s*([^}]+?)\s*\}\}$/);
    if(m) return /^[A-Z0-9_]+$/.test(m[1])?'cfg.'+m[1]:m[1];
    if(t==='number'&&s!==''&&isFinite(Number(s))) return s;
    if(t==='boolean'&&/^(true|false)$/i.test(s)) return s.toLowerCase();
    return JSON.stringify(s);
  }
  var parts=c.rules.filter(function(r){return r.l}).map(function(r){
    var a=ex(r.l,r.t), b=ex(r.r,r.t);
    if(r.t==='dateTime'&&!ifUnary(r.t,r.op)){ a='toDate('+a+')'; b='toDate('+b+')' }
    switch(r.op){
      case 'exists': return a+' !== undefined'; case 'notExists': return a+' === undefined';
      case 'empty': return '!'+a; case 'notEmpty': return '!!'+a;
      case 'true': return a+' === true'; case 'false': return a+' === false';
      case 'equals': return a+' === '+b; case 'notEquals': return a+' !== '+b;
      case 'contains': return 'String('+a+').includes('+b+')'; case 'notContains': return '!String('+a+').includes('+b+')';
      case 'startsWith': return 'String('+a+').startsWith('+b+')'; case 'notStartsWith': return '!String('+a+').startsWith('+b+')';
      case 'endsWith': return 'String('+a+').endsWith('+b+')'; case 'notEndsWith': return '!String('+a+').endsWith('+b+')';
      case 'regex': return 'new RegExp('+b+').test('+a+')'; case 'notRegex': return '!new RegExp('+b+').test('+a+')';
      case 'gt': case 'after': return a+' > '+b; case 'lt': case 'before': return a+' < '+b;
      case 'gte': case 'afterOrEquals': return a+' >= '+b; case 'lte': case 'beforeOrEquals': return a+' <= '+b;
    }
    return 'true';
  });
  var body=parts.length?parts.join(c.comb==='or'?'\n    || ':'\n    && '):'true';
  var needDate=c.rules.some(function(r){return r.t==='dateTime'&&!ifUnary(r.t,r.op)});
  return tx('// Trả về true → nhánh Đúng, false → nhánh Sai\n// Dữ liệu: n1.<trường>, n2.<trường>, sys.maDon, cfg.<THAM_SO>\n','// Return true → True branch, false → False branch\n// Data: n1.<field>, n2.<field>, sys.maDon, cfg.<PARAM>\n')+
    (needDate?'function toDate(s){ var p=String(s).split(/[\\/ :]/); return new Date(p[2],p[1]-1,p[0],p[3]||0,p[4]||0).getTime() }\n':'')+
    'return '+body+';';
}

/* ---- tóm tắt trong panel phải ---- */
function ifSummaryHTML(n){
  var c=ifGet(n), e=ifErrors(n);
  return '<div class="field"><label>'+tx('Điều kiện','Conditions')+'</label>'+
    '<div class="if-sum">'+(c.mode==='js'?'<div class="if-sr">'+ifTypeIc('string').replace('>T<','>{}<')+'<span class="mono">JavaScript</span></div>':
      (c.rules.length?c.rules.map(function(r,i){ var o=ifOp(r.t,r.op);
        return (i?'<div class="if-sc">'+(c.comb==='or'?'OR':'AND')+'</div>':'')+'<div class="if-sr">'+ifTypeIc(r.t)+'<span class="mono">'+esc(ifShort(r.l)||'value1')+'</span><b>'+esc(o?o[1]:r.op)+'</b>'+(ifUnary(r.t,r.op)?'':'<span class="mono">'+esc(ifShort(r.r)||'value2')+'</span>')+'</div>' }).join('')
      :'<div class="if-sr" style="color:var(--ink-3)">'+tx('Chưa có điều kiện','No condition')+'</div>'))+'</div>'+
    (e.length?'<span class="hint" style="color:var(--danger)">'+esc(e[0])+(e.length>1?tx(' (+'+(e.length-1)+' lỗi khác)',' (+'+(e.length-1)+' more)'):'')+'</span>':'')+'</div>'+
    '<button class="btn pri" style="width:100%;justify-content:center;margin-bottom:12px" onclick="ifOpen(\''+n.id+'\')">'+svg(I.sliders)+tx('Mở cấu hình điều kiện','Open condition editor')+'</button>';
}

/* ---- màn 3 cột ---- */
function ifNode(){ return IFN.id?nodeById(IFN.id):null }
function ifOpen(id){
  var n=nodeById(id); if(!n||n.t!=='gate') return;
  IFN.id=id; IFN.tab='par'; IFN.menu=null; IFN.ac=null; IFN.res=null; IFN.stale=0; IFN.otab=''; IFN.src='all';
  ifGet(n); ifDraw();
  document.body.classList.add('ifx-on');
}
function ifClose(){
  var n=ifNode(); IFN.id=null; IFN.menu=null; IFN.ac=null;
  var r=document.getElementById('ifxRoot'); if(r) r.innerHTML='';
  document.body.classList.remove('ifx-on','if-drag');
  if(n){ n.cond=ifCondText(n); renderNodes(); renderInsp() }
}
function ifTouch(n,txt){ n.cond=ifCondText(n); if(IFN.res) IFN.stale=1; markDirty(); if(txt) try{ auditLog(tx('Sửa điều kiện rẽ nhánh','Edit branch condition'),wfNm(DSN.id)+' · '+n.name+': '+txt) }catch(e){} }
function ifDraw(){
  var n=ifNode(); if(!n) return;
  var root=document.getElementById('ifxRoot');
  if(!root){ root=document.createElement('div'); root.id='ifxRoot'; document.body.appendChild(root) }
  var mb=document.getElementById('ifMidB'), st=mb?mb.scrollTop:0, ib=document.getElementById('ifInB'), st2=ib?ib.scrollTop:0;
  var t=NT.gate;
  root.innerHTML='<div class="ifx" role="dialog" aria-modal="true" aria-label="'+esc(n.name)+'">'+
    '<div class="ifx-top"><button class="ifx-back" onclick="ifClose()">'+svg(IF_IC.back)+tx('Quay lại khung vẽ','Back to canvas')+'</button></div>'+
    '<div class="ifx-body">'+
      '<section class="ifx-side ifx-in" aria-label="INPUT">'+ifInputHTML(n)+'</section>'+
      '<section class="ifx-mid">'+
        '<div class="ifx-mh"><div class="ifx-ni" style="background:'+t.c+'">'+svg(t.i)+'</div>'+
        '<input class="ifx-name" value="'+esc(n.name)+'" aria-label="'+tx('Tên node','Node name')+'" oninput="ifName(this.value)">'+
        '<button class="btn pri ifx-exec" onclick="ifExec()">'+svg(IF_IC.flask)+'Execute step</button></div>'+
        '<div class="ifx-tabs"><button class="'+(IFN.tab==='par'?'on':'')+'" onclick="IFN.tab=\'par\';ifDraw()">Parameters</button>'+
        '<button class="'+(IFN.tab==='set'?'on':'')+'" onclick="IFN.tab=\'set\';ifDraw()">Settings</button></div>'+
        '<div class="ifx-mb" id="ifMidB">'+(IFN.tab==='set'?ifSettingsHTML(n):ifParamsHTML(n))+'</div>'+
      '</section>'+
      '<section class="ifx-side ifx-out" aria-label="OUTPUT">'+ifOutputHTML(n)+'</section>'+
    '</div></div>';
  mb=document.getElementById('ifMidB'); if(mb) mb.scrollTop=st;
  ib=document.getElementById('ifInB'); if(ib) ib.scrollTop=st2;
}
function ifName(v){ var n=ifNode(); if(!n) return; n.name=v; markDirty() }

/* INPUT */
function ifGroups(n){
  var order=[], by={};
  ifVars(n).forEach(function(v){ if(!by[v.g]){ by[v.g]=[]; order.push(v.g) } by[v.g].push(v) });
  return order.map(function(g){ return {g:g,gl:by[g][0].gl,always:by[g][0].always,cond:by[g][0].cond,vars:by[g]} });
}
function ifInputHTML(n){
  var gs=ifGroups(n), sel=gs.filter(function(g){ return IFN.src==='all'||g.g===IFN.src });
  var h='<div class="ifx-sh"><b>INPUT</b>'+
    '<select class="inp ifx-src" aria-label="'+tx('Nguồn dữ liệu','Data source')+'" onchange="IFN.src=this.value;ifDraw()">'+
    '<option value="all">'+tx('Tất cả node trước','All previous nodes')+'</option>'+gs.map(function(g){ return '<option value="'+g.g+'"'+(IFN.src===g.g?' selected':'')+'>'+esc(g.gl)+'</option>' }).join('')+'</select></div>'+
    '<div class="ifx-tb"><div class="ifx-seg">'+[['schema','Schema'],['table','Table'],['json','JSON']].map(function(x){ return '<button class="'+(IFN.view===x[0]?'on':'')+'" onclick="IFN.view=\''+x[0]+'\';ifDraw()">'+x[1]+'</button>' }).join('')+'</div>'+
    '<button class="xb look'+(IFN.edit?' on':'')+'" title="'+tx('Sửa dữ liệu mẫu để chạy thử','Edit sample data for testing')+'" aria-pressed="'+(IFN.edit?'true':'false')+'" onclick="IFN.edit=IFN.edit?0:1;ifDraw()">'+svg(IF_IC.pen)+'</button></div>'+
    '<div class="ifx-sb" id="ifInB">';
  if(IFN.view==='json'){
    var d=ifData(n), o={}; sel.forEach(function(g){ var k=g.g; if(d[k]) o[k]=d[k] });
    h+='<pre class="ifx-json">'+esc(JSON.stringify(o,null,2))+'</pre>';
  } else if(IFN.view==='table'){
    h+=sel.map(function(g){
      return '<div class="ifx-gh">'+esc(g.gl)+(g.always?'':'<em>'+svg(I.warn)+esc(g.cond||'')+'</em>')+'</div><div class="tbl-wrap"><table class="tbl ifx-t"><thead><tr>'+g.vars.map(function(v){ return '<th draggable="true" ondragstart="ifDragStart(event,\''+v.v+'\')" ondragend="ifDragEnd()" title="'+esc(v.lbl)+'">'+ifTypeIc(dtType(v.dt))+esc(ifLeaf(v.v))+'</th>' }).join('')+'</tr></thead>'+
        '<tbody><tr>'+g.vars.map(function(v){ return '<td class="mono">'+ifValCell(v)+'</td>' }).join('')+'</tr></tbody></table></div>';
    }).join('');
  } else {
    h+=sel.map(function(g){
      return '<div class="ifx-gh">'+esc(g.gl)+(g.always?'':'<em>'+svg(I.warn)+esc(g.cond||'')+'</em>')+'</div>'+
        g.vars.map(function(v){
          return '<div class="ifx-f" draggable="true" ondragstart="ifDragStart(event,\''+v.v+'\')" ondragend="ifDragEnd()" title="'+esc(v.lbl)+' — '+tx('kéo thả vào ô Value','drag into a Value field')+'">'+
            '<span class="ifx-grab">'+svg(IF_IC.grab)+'</span>'+ifTypeIc(dtType(v.dt))+'<span class="ifx-k mono">'+esc(ifLeaf(v.v))+'</span>'+
            '<span class="ifx-v mono">'+ifValCell(v)+'</span></div>';
        }).join('');
    }).join('');
  }
  h+='</div>';
  return h;
}
function ifLeaf(k){ return /^[A-Z0-9_]+$/.test(k)?k:k.split('.').slice(1).join('.') }
function ifValCell(v){
  var s=ifSampleOf(v);
  if(IFN.edit) return '<input class="ifx-ve mono" value="'+esc(s)+'" aria-label="'+tx('Giá trị mẫu của ','Sample value of ')+esc(v.v)+'" onmousedown="event.stopPropagation()" onchange="ifSample(\''+v.v+'\',this.value)">';
  return esc(s===''?'—':s);
}
function ifSample(k,v){ IFN.sample[k]=v; if(IFN.res) IFN.stale=1; ifDraw() }
function ifDragStart(e,v){
  IFN.drag=v; try{ e.dataTransfer.effectAllowed='copy'; e.dataTransfer.setData('text/plain','{{'+v+'}}') }catch(x){}
  document.body.classList.add('if-drag');
}
function ifDragEnd(){ IFN.drag=''; document.body.classList.remove('if-drag'); document.querySelectorAll('.if-drop').forEach(function(x){x.classList.remove('if-drop')}) }
function ifDOver(e,el){ if(!IFN.drag) return; e.preventDefault(); try{ e.dataTransfer.dropEffect='copy' }catch(x){} el.classList.add('if-drop') }
function ifDLeave(el){ el.classList.remove('if-drop') }
function ifDrop(e,i,s){
  if(!IFN.drag) return; e.preventDefault();
  var k=IFN.drag; ifDragEnd(); ifPick(i,s,k);
}

/* Parameters */
function ifParamsHTML(n){
  var c=ifGet(n), e=ifErrors(n);
  var h='<div class="ifx-mode"><span>'+tx('Cách viết điều kiện','Condition mode')+'</span><div class="ifx-seg">'+
    '<button class="'+(c.mode!=='js'?'on':'')+'" onclick="ifMode(\'rules\')">'+svg(IF_IC.list)+'Conditions</button>'+
    '<button class="'+(c.mode==='js'?'on':'')+'" onclick="ifMode(\'js\')">'+svg(IF_IC.code)+'JavaScript</button></div></div>';
  if(c.mode==='js'){
    var lines=String(c.js||'').split('\n').length, se=ifJsSyntax(c.js||'');
    h+='<div class="ifx-sec"><div class="ifx-st">JavaScript</div>'+
      '<div class="sys-ed ifx-ed"><div class="sys-gut" id="ifGut" aria-hidden="true">'+sysGutter(lines)+'</div>'+
      '<textarea class="mono" id="ifJs" spellcheck="false" aria-label="JavaScript" oninput="ifJsIn(this)" onscroll="var g=document.getElementById(\'ifGut\');if(g)g.scrollTop=this.scrollTop" onkeydown="ifTab(event,this)">'+esc(c.js||'')+'</textarea></div>'+
      '<div id="ifJsMsg">'+ifJsMsg(se)+'</div></div>';
    return h;
  }
  h+='<div class="ifx-sec"><div class="ifx-st">Conditions</div><div class="if-rules">';
  c.rules.forEach(function(r,i){
    var o=ifOp(r.t,r.op), un=ifUnary(r.t,r.op);
    if(i) h+='<div class="if-comb"><select class="inp" aria-label="AND / OR" onchange="ifComb(this.value)"><option value="and"'+(c.comb!=='or'?' selected':'')+'>AND</option><option value="or"'+(c.comb==='or'?' selected':'')+'>OR</option></select></div>';
    h+='<div class="if-row'+(un?' un':'')+'">'+
      ifCell(i,'l',r.l,'value1')+
      '<div class="if-opc"><button class="if-opb'+(IFN.menu===i?' on':'')+'" aria-haspopup="menu" aria-expanded="'+(IFN.menu===i)+'" onclick="event.stopPropagation();ifMenu('+i+')">'+ifTypeIc(r.t)+'<span>'+esc(o?o[1]:r.op)+'</span>'+svg(IF_IC.chev)+'</button>'+
        (IFN.menu===i?ifMenuHTML(i,r):'')+'</div>'+
      (un?'<div class="if-cell if-na"></div>':ifCell(i,'r',r.r,'value2'))+
      '<button class="xb if-del" title="'+tx('Xoá điều kiện','Remove condition')+'" aria-label="'+tx('Xoá điều kiện ','Remove condition ')+(i+1)+'" onclick="ifDel('+i+')">'+svg(I.trash)+'</button></div>';
  });
  h+='</div><button class="btn if-add" onclick="ifAdd()">'+svg(I.plus)+'Add condition</button></div>';
  if(e.length&&IFN.tried) h+='<div class="if-errs">'+e.map(function(x){return '<div>'+svg(I.warn)+esc(x)+'</div>'}).join('')+'</div>';
  return h;
}
function ifCell(i,s,val,ph){
  return '<div class="if-cell"><input class="inp if-v mono" id="ifv_'+i+'_'+s+'" value="'+esc(val||'')+'" placeholder="'+ph+'" autocomplete="off" spellcheck="false" '+
    'onfocus="ifAcOpen('+i+',\''+s+'\',this)" oninput="ifIn('+i+',\''+s+'\',this)" onblur="ifAcBlur()" onkeydown="ifAcKey(event,'+i+',\''+s+'\',this)" '+
    'ondragover="ifDOver(event,this)" ondragleave="ifDLeave(this)" ondrop="ifDrop(event,'+i+',\''+s+'\')">'+
    '<div class="if-pv" id="ifpv_'+i+'_'+s+'">'+ifPv(val)+'</div>'+
    '<div class="if-ac" id="ifac_'+i+'_'+s+'"></div></div>';
}
function ifPv(val){
  var n=ifNode(); if(!n||String(val||'').indexOf('{{')<0) return '';
  var R=ifRaw(val,ifScope(n));
  return R.miss?'<span class="bad">'+tx('Không có biến {{'+esc(R.miss)+'}} ở node này','{{'+esc(R.miss)+'}} is not available here')+'</span>':'<span>= '+esc(R.v===''?tx('(rỗng)','(empty)'):R.v)+'</span>';
}
function ifMenuHTML(i,r){
  var t=IFN.menuT||r.t;
  return '<div class="if-opm" role="menu" onclick="event.stopPropagation()"><div class="if-opt">'+
    IF_TYPES.map(function(x){ return '<button class="'+(x[0]===t?'on':'')+'" onmouseenter="ifMenuT(\''+x[0]+'\')" onclick="ifMenuT(\''+x[0]+'\')">'+ifTypeIc(x[0])+'<span>'+x[1]+'</span>'+svg(IF_IC.right)+'</button>' }).join('')+
    '</div><div class="if-opo">'+IF_OPS[t].map(function(o){ return '<button role="menuitem" class="'+(r.t===t&&r.op===o[0]?'on':'')+'" onclick="ifSetOp('+i+',\''+t+'\',\''+o[0]+'\')">'+o[1]+'</button>' }).join('')+'</div></div>';
}
function ifMenu(i){ IFN.menu=IFN.menu===i?null:i; IFN.menuT=''; IFN.ac=null; ifDraw() }
function ifMenuT(t){ if(IFN.menuT===t) return; IFN.menuT=t; ifDraw() }
function ifSetOp(i,t,op){ var n=ifNode(); if(!n) return; var r=ifGet(n).rules[i]; r.t=t; r.op=op; if(ifUnary(t,op)) r.r=''; IFN.menu=null; ifTouch(n,ifCondText(n)); ifDraw() }
function ifComb(v){ var n=ifNode(); if(!n) return; ifGet(n).comb=v; ifTouch(n,v.toUpperCase()); ifDraw() }
function ifAdd(){ var n=ifNode(); if(!n) return; ifGet(n).rules.push({l:'',t:'string',op:'equals',r:''}); ifTouch(n); ifDraw(); setTimeout(function(){ var c=ifGet(n).rules.length-1, e=document.getElementById('ifv_'+c+'_l'); if(e) e.focus() },30) }
function ifDel(i){ var n=ifNode(); if(!n) return; ifGet(n).rules.splice(i,1); ifTouch(n,tx('xoá điều kiện ','remove condition ')+(i+1)); ifDraw() }
function ifMode(m){
  var n=ifNode(); if(!n) return; var c=ifGet(n); if(c.mode===m) return;
  if(m==='js'&&!String(c.js||'').trim()) c.js=ifRulesToJs(n);
  c.mode=m; ifTouch(n,m==='js'?'JavaScript':'Conditions'); ifDraw();
}
function ifJsFromRules(){ var n=ifNode(); if(!n) return; var c=ifGet(n); c.js=ifRulesToJs(n); ifTouch(n); ifDraw() }
function ifJsMsg(se){ return se?'<div class="sys-m bad">'+svg(I.warn)+'<span>'+tx('Lỗi cú pháp: ','Syntax error: ')+esc(se)+'</span></div>':'' }
function ifJsIn(el){
  var n=ifNode(); if(!n) return; ifGet(n).js=el.value; ifTouch(n);
  var g=document.getElementById('ifGut'); if(g) g.innerHTML=sysGutter(el.value.split('\n').length);
  var m=document.getElementById('ifJsMsg'); if(m) m.innerHTML=ifJsMsg(ifJsSyntax(el.value));
}
function ifTab(e,el){ if(e.key!=='Tab') return; e.preventDefault(); var a=el.selectionStart,b=el.selectionEnd; el.value=el.value.slice(0,a)+'  '+el.value.slice(b); el.selectionStart=el.selectionEnd=a+2; ifJsIn(el) }

/* Value 1/2: gõ, gợi ý trường, chọn */
function ifIn(i,s,el){
  var n=ifNode(); if(!n) return; var r=ifGet(n).rules[i]; r[s]=el.value; ifTouch(n);
  var pv=document.getElementById('ifpv_'+i+'_'+s); if(pv) pv.innerHTML=ifPv(el.value);
  IFN.ac={i:i,s:s}; IFN.acSel=0; ifAcRender(el.value);
}
function ifAcList(q){
  var n=ifNode(); if(!n) return [];
  q=String(q||'').replace(/[{}]/g,'').trim().toLowerCase();
  return ifVars(n).filter(function(v){ return !q||(v.v+' '+v.lbl).toLowerCase().indexOf(q)>=0 });
}
function ifAcCur(q,s){ var raw=String(q||''); return (s==='r'&&raw&&raw.indexOf('{{')<0)?[]:ifAcList(raw) }
function ifAcOpen(i,s,el){ IFN.ac={i:i,s:s}; IFN.acSel=0; IFN.menu=null; var o=document.querySelector('.if-opm'); if(o) o.remove(); ifAcRender(el.value) }
function ifAcRender(q){
  document.querySelectorAll('.if-ac').forEach(function(x){ x.innerHTML=''; x.classList.remove('on') });
  if(!IFN.ac) return;
  var box=document.getElementById('ifac_'+IFN.ac.i+'_'+IFN.ac.s); if(!box) return;
  var l=ifAcCur(q,IFN.ac.s);
  if(!l.length){ return }
  var last='';
  box.innerHTML='<div class="if-ach">'+(IFN.ac.s==='l'?tx('Chọn trường của các node trước','Pick a field from previous nodes'):tx('Chọn biến hoặc nhập hằng số','Pick a variable or type a constant'))+'</div>'+
    l.map(function(v,k){
      var g=v.gl!==last?'<div class="if-acg">'+esc(v.gl)+'</div>':''; last=v.gl;
      return g+'<button type="button" class="'+(k===IFN.acSel?'on':'')+'" onmousedown="event.preventDefault();ifPick('+IFN.ac.i+',\''+IFN.ac.s+'\',\''+v.v+'\')">'+ifTypeIc(dtType(v.dt))+'<span class="mono">'+esc(ifLeaf(v.v))+'</span><em>'+esc(v.lbl)+'</em><i class="mono">'+esc(ifSampleOf(v))+'</i></button>';
    }).join('');
  box.classList.add('on');
}
function ifAcBlur(){ setTimeout(function(){ var a=document.activeElement; if(a&&a.classList&&a.classList.contains('if-v')) return; IFN.ac=null; ifAcRender('') },120) }
function ifAcKey(e,i,s,el){
  var box=document.getElementById('ifac_'+i+'_'+s), bs=box?box.querySelectorAll('button'):[];
  if(e.key==='Escape'&&IFN.ac){ e.stopPropagation(); IFN.ac=null; ifAcRender(''); return }
  if(!bs.length) return;
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){ e.preventDefault(); IFN.acSel=(IFN.acSel+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length; bs.forEach(function(b,k){ b.classList.toggle('on',k===IFN.acSel) }); bs[IFN.acSel].scrollIntoView({block:'nearest'}) }
  else if(e.key==='Enter'){ e.preventDefault(); var v=ifAcCur(el.value,s)[IFN.acSel]; if(v) ifPick(i,s,v.v) }
}
function ifPick(i,s,k){
  var n=ifNode(); if(!n) return; var r=ifGet(n).rules[i]; if(!r) return;
  r[s]='{{'+k+'}}';
  if(s==='l'){ var v=ifScope(n)[k]; if(v){ var t=dtType(v.dt); if(r.t!==t){ r.t=t; if(!ifOp(t,r.op)) r.op=ifOp(t,'equals')?'equals':IF_OPS[t][0][0] } } }
  IFN.ac=null; ifTouch(n,ifCondText(n)); ifDraw();
  setTimeout(function(){ var nx=document.getElementById(s==='l'&&!ifUnary(r.t,r.op)?'ifv_'+i+'_r':'ifv_'+i+'_'+s); if(nx&&s==='l'&&!nx.value) nx.focus() },30);
}

/* Settings */
function ifSettingsHTML(n){
  return '<div class="ifx-sec"><div class="field"><label for="ifNote">Notes</label><textarea class="inp" id="ifNote" rows="4" placeholder="'+tx('Ghi chú cho người thiết kế sau…','Notes for other designers…')+'" oninput="ifSet(\'note\',this.value)">'+esc(n.note||'')+'</textarea></div>'+
    '<label class="ck"><input type="checkbox" '+(n.showNote?'checked':'')+' onchange="ifSet(\'showNote\',this.checked?1:0)"><span>Display note in flow</span></label></div>';
}
function ifSet(k,v){ var n=ifNode(); if(!n) return; n[k]=v; markDirty() }

/* OUTPUT */
function ifTarget(n,lb){ var l=def().links.filter(function(x){ return x.f===n.id&&x.lbl===lb })[0]; var t=l?nodeById(l.to):null; return t?t.name:'' }
function ifExec(){
  var n=ifNode(); if(!n) return;
  IFN.tried=1; IFN.res=ifRun(n); IFN.stale=0; IFN.otab=IFN.res.err?'':(IFN.res.ok?'t':'f');
  try{ auditLog(tx('Chạy thử node rẽ nhánh','Test-run branch node'),wfNm(DSN.id)+' · '+n.name+' → '+(IFN.res.err?tx('lỗi','error'):(IFN.res.ok?'true':'false'))) }catch(e){}
  ifDraw();
}
function ifOutputHTML(n){
  var R=IFN.res, LT=tx('Đúng','True'), LF=tx('Sai','False');
  var h='<div class="ifx-sh"><b>OUTPUT</b>'+(R&&IFN.stale?'<span class="chip c-wait nb">'+tx('Cấu hình đã đổi — chạy lại','Settings changed — run again')+'</span>':'')+'</div>';
  if(!R) return h+'<div class="ifx-empty">'+svg(IF_IC.flask)+'<b>'+tx('Chưa chạy thử','Not run yet')+'</b><p>'+tx('Bấm Execute step để chạy điều kiện với dữ liệu mẫu ở cột INPUT.','Click Execute step to evaluate the condition with the sample data in INPUT.')+'</p>'+
    '<button class="btn" onclick="ifExec()">'+svg(IF_IC.flask)+'Execute step</button></div>';
  if(R.err) return h+'<div class="ifx-err">'+svg(I.warn)+'<div><b>'+tx('Node chạy lỗi','Node execution failed')+'</b><span>'+esc(R.err)+'</span></div></div>';
  var tab=IFN.otab||(R.ok?'t':'f'), on=(tab==='t')===R.ok, tgt=ifTarget(n,tab==='t'?LT:LF);
  h+='<div class="ifx-bt"><button class="'+(tab==='t'?'on':'')+'" onclick="IFN.otab=\'t\';ifDraw()">True Branch <span class="'+(R.ok?'c1':'c0')+'">'+(R.ok?1:0)+' item</span></button>'+
     '<button class="'+(tab==='f'?'on':'')+'" onclick="IFN.otab=\'f\';ifDraw()">False Branch <span class="'+(!R.ok?'c1':'c0')+'">'+(!R.ok?1:0)+' item</span></button></div>'+
     '<div class="ifx-sb">'+
     '<div class="ifx-res '+(R.ok?'t':'f')+'">'+svg(R.ok?I.check:I.x)+'<span>'+tx('Kết quả: ','Result: ')+'<b>'+(R.ok?'true':'false')+'</b> → '+tx('nhánh ','branch ')+(R.ok?LT:LF)+(ifTarget(n,R.ok?LT:LF)?' → '+esc(ifTarget(n,R.ok?LT:LF)):'')+'</span></div>'+
     (tgt?'<div class="ifx-to">'+tx('Nhánh này nối tới: ','This branch goes to: ')+'<b>'+esc(tgt)+'</b></div>':'<div class="ifx-to">'+tx('Nhánh này chưa nối tới node nào','This branch is not connected yet')+'</div>')+
     (on?'<pre class="ifx-json">'+esc(JSON.stringify([ifData(n)],null,2))+'</pre>':'<div class="ifx-none">'+tx('Không có item nào đi nhánh này','This branch did not output any data')+'</div>');
  if(R.mode!=='js'){
    var c=ifGet(n);
    h+='<div class="ifx-gh" style="margin-top:12px">'+tx('Chi tiết từng điều kiện','Condition details')+' · '+(c.comb==='or'?'OR':'AND')+'</div>'+
      '<table class="tbl ifx-t"><thead><tr><th>#</th><th>Value 1</th><th>'+tx('Phép so sánh','Comparison')+'</th><th>Value 2</th><th></th></tr></thead><tbody>'+
      c.rules.map(function(r,i){ var o=R.rules[i]||{}, op=ifOp(r.t,r.op);
        return '<tr><td>'+(i+1)+'</td><td class="mono">'+esc(o.lv===undefined?'—':o.lv)+'</td><td>'+ifTypeIc(r.t)+esc(op?op[1]:r.op)+'</td><td class="mono">'+(ifUnary(r.t,r.op)?'—':esc(o.rv===undefined?'—':o.rv))+'</td>'+
          '<td>'+(o.ok?'<span class="chip c-done nb">true</span>':'<span class="chip c-draft nb">false</span>')+'</td></tr>' }).join('')+'</tbody></table>';
  }
  return h+'</div>';
}
document.addEventListener('click',function(e){
  if(IFN.id&&IFN.menu!==null&&!(e.target.closest&&e.target.closest('.if-opc'))){ IFN.menu=null; ifDraw() }
});
document.addEventListener('keydown',function(e){
  if(!IFN.id||e.key!=='Escape') return;
  e.stopPropagation(); e.preventDefault();
  if(IFN.menu!==null){ IFN.menu=null; ifDraw(); return }
  if(IFN.ac){ IFN.ac=null; ifAcRender(''); return }
  ifClose();
},true);

/* =====================================================================
   v17 — NODE RẼ NHÁNH: 2 cột (trường biểu mẫu của node trước | điều kiện)
   bỏ Execute step, OUTPUT, thanh INPUT, Settings, số nhỏ dưới ô giá trị;
   bản VI dùng tên kiểu dữ liệu và phép so sánh tiếng Việt
   ===================================================================== */
var IF_TYPES=[['string','String','Chuỗi ký tự'],['number','Number','Số'],['dateTime','Date & Time','Ngày & giờ'],['boolean','Boolean','Đúng / Sai']];
var IF_U=[['exists','exists','tồn tại',1],['notExists','does not exist','không tồn tại',1],['empty','is empty','trống',1],['notEmpty','is not empty','không trống',1]];
var IF_OPS={
  string:IF_U.concat([['equals','is equal to','bằng'],['notEquals','is not equal to','không bằng'],['contains','contains','chứa'],['notContains','does not contain','không chứa'],['startsWith','starts with','bắt đầu bằng'],['notStartsWith','does not start with','không bắt đầu bằng'],['endsWith','ends with','kết thúc bằng'],['notEndsWith','does not end with','không kết thúc bằng']]),
  number:IF_U.concat([['equals','is equal to','bằng'],['notEquals','is not equal to','không bằng'],['gt','is greater than','lớn hơn'],['lt','is less than','nhỏ hơn'],['gte','is greater than or equal to','lớn hơn hoặc bằng'],['lte','is less than or equal to','nhỏ hơn hoặc bằng']]),
  dateTime:IF_U.concat([['equals','is equal to','bằng'],['notEquals','is not equal to','không bằng'],['after','is after','sau'],['before','is before','trước'],['afterOrEquals','is after or equal to','sau hoặc bằng'],['beforeOrEquals','is before or equal to','trước hoặc bằng']]),
  boolean:IF_U.concat([['true','is true','là đúng',1],['false','is false','là sai',1],['equals','is equal to','bằng'],['notEquals','is not equal to','không bằng']])
};
function ifTypeName(t){ var x=IF_TYPES.filter(function(y){return y[0]===t})[0]||IF_TYPES[0]; return tx(x[2],x[1]) }
function ifOpLabel(o){ return o?tx(o[2],o[1]):'' }
function ifUnary(t,op){ var o=ifOp(t,op); return !!(o&&o[3]) }

/* chỉ dữ liệu biểu mẫu của các node đứng trước node điều kiện */
function ifVars(n){
  var keys={};
  upstreamNodes(n.id).forEach(function(nid){ var x=nodeById(nid); (x&&x.form||[]).forEach(function(f){ if(typeof bcIsData!=='function'||bcIsData(f)) keys[nid+'.'+f.k]=1 }) });
  return varsAt(n.id).filter(function(v){ return keys[v.v] });
}
function ifGet(n){
  if(!n.ifc){
    var rule={l:'',t:'string',op:'equals',r:''}, m=String(n.cond||'').match(/^\s*([\w.]+)\s*(>=|<=|==|!=|>|<|=)\s*(.+?)\s*$/);
    if(m){
      var v=ifVars(n).filter(function(x){ return x.v===m[1]||x.v.split('.').pop()===m[1] })[0];
      rule.l='{{'+(v?v.v:m[1])+'}}'; rule.t=v?dtType(v.dt):'number';
      var map={'>':'gt','<':'lt','>=':'gte','<=':'lte','==':'equals','=':'equals','!=':'notEquals'}, op=map[m[2]];
      if(rule.t==='dateTime') op={gt:'after',lt:'before',gte:'afterOrEquals',lte:'beforeOrEquals'}[op]||op;
      if(!ifOp(rule.t,op)) rule.t='number';
      rule.op=op;
      var c=m[3].match(/^\{\{\s*([A-Z0-9_]+)\s*\}\}$/);            /* tham số cấu hình cũ → điền số trực tiếp */
      rule.r=c&&IF_CFG[c[1]]!==undefined?IF_CFG[c[1]]:m[3];
    }
    n.ifc={mode:'rules',comb:'and',rules:[rule],js:''};
  }
  return n.ifc;
}
function ifCondText(n){
  var c=ifGet(n);
  if(c.mode==='js') return 'JavaScript';
  return c.rules.filter(function(r){return r.l}).map(function(r){
    var o=ifOp(r.t,r.op), s=IF_SYM[r.op];
    return ifShort(r.l)+' '+(s||ifOpLabel(o))+(ifUnary(r.t,r.op)?'':' '+ifShort(r.r));
  }).join(c.comb==='or'?' OR ':' AND ');
}
function ifValErr(r){
  var v=String(r.r||'').trim(); if(!v||v.indexOf('{{')>=0||ifUnary(r.t,r.op)||r.op==='regex'||r.op==='notRegex') return '';
  if(r.t==='number'&&!isFinite(Number(v.replace(',','.')))) return tx('Phải nhập số','Must be a number');
  if(r.t==='dateTime'&&ifDate(v)===null) return tx('Nhập ngày dạng dd/mm/yyyy','Use dd/mm/yyyy');
  if(r.t==='boolean'&&ifConv('boolean',v).err) return tx('Nhập true hoặc false','Enter true or false');
  return '';
}
function ifErrors(n){
  var c=ifGet(n), e=[], sc=ifScope(n);
  function refs(s,i){ String(s||'').replace(/\{\{\s*([^}]+?)\s*\}\}/g,function(_,k){ if(!sc[k]) e.push(tx('Điều kiện '+(i+1)+': trường {{'+k+'}} không có ở các node trước','Condition '+(i+1)+': field {{'+k+'}} is not available from previous nodes')) }) }
  if(c.mode==='js'){
    if(!String(c.js||'').trim()) e.push(tx('Chưa viết mã JavaScript','No JavaScript code yet'));
    else { var se=ifJsSyntax(c.js); if(se) e.push(tx('Lỗi cú pháp JavaScript: ','JavaScript syntax error: ')+se) }
    return e;
  }
  if(!c.rules.length) e.push(tx('Chưa có điều kiện nào','No condition yet'));
  c.rules.forEach(function(r,i){
    if(!String(r.l).trim()) e.push(tx('Điều kiện '+(i+1)+': chưa chọn trường ở giá trị 1','Condition '+(i+1)+': value 1 is empty')); else refs(r.l,i);
    if(!ifUnary(r.t,r.op)){
      if(!String(r.r).trim()) e.push(tx('Điều kiện '+(i+1)+': chưa có giá trị 2','Condition '+(i+1)+': value 2 is empty'));
      else { refs(r.r,i); var ve=ifValErr(r); if(ve) e.push(tx('Điều kiện '+(i+1)+': ','Condition '+(i+1)+': ')+ve) }
    }
    if((r.op==='regex'||r.op==='notRegex')&&String(r.r).trim()&&r.r.indexOf('{{')<0){ try{ ifRegex(r.r) }catch(x){ e.push(tx('Điều kiện '+(i+1)+': regex không hợp lệ','Condition '+(i+1)+': invalid regex')) } }
  });
  return e;
}
function ifRulesToJs(n){
  var c=ifGet(n);
  function ex(s,t){
    s=String(s==null?'':s).trim();
    var m=s.match(/^\{\{\s*([^}]+?)\s*\}\}$/); if(m) return m[1];
    if(t==='number'&&s!==''&&isFinite(Number(s))) return s;
    if(t==='boolean'&&/^(true|false)$/i.test(s)) return s.toLowerCase();
    return JSON.stringify(s);
  }
  var parts=c.rules.filter(function(r){return r.l}).map(function(r){
    var a=ex(r.l,r.t), b=ex(r.r,r.t);
    if(r.t==='dateTime'&&!ifUnary(r.t,r.op)){ a='toDate('+a+')'; b='toDate('+b+')' }
    switch(r.op){
      case 'exists': return a+' !== undefined'; case 'notExists': return a+' === undefined';
      case 'empty': return '!'+a; case 'notEmpty': return '!!'+a;
      case 'true': return a+' === true'; case 'false': return a+' === false';
      case 'equals': return a+' === '+b; case 'notEquals': return a+' !== '+b;
      case 'contains': return 'String('+a+').includes('+b+')'; case 'notContains': return '!String('+a+').includes('+b+')';
      case 'startsWith': return 'String('+a+').startsWith('+b+')'; case 'notStartsWith': return '!String('+a+').startsWith('+b+')';
      case 'endsWith': return 'String('+a+').endsWith('+b+')'; case 'notEndsWith': return '!String('+a+').endsWith('+b+')';
      case 'regex': return 'new RegExp('+b+').test('+a+')'; case 'notRegex': return '!new RegExp('+b+').test('+a+')';
      case 'gt': case 'after': return a+' > '+b; case 'lt': case 'before': return a+' < '+b;
      case 'gte': case 'afterOrEquals': return a+' >= '+b; case 'lte': case 'beforeOrEquals': return a+' <= '+b;
    }
    return 'true';
  });
  var body=parts.length?parts.join(c.comb==='or'?'\n    || ':'\n    && '):'true';
  var needDate=c.rules.some(function(r){return r.t==='dateTime'&&!ifUnary(r.t,r.op)});
  return tx('// Trả về true → nhánh Đúng, false → nhánh Sai\n// Dữ liệu biểu mẫu: n1.<mã trường>, n2.<mã trường>…\n','// Return true → True branch, false → False branch\n// Form data: n1.<field>, n2.<field>…\n')+
    (needDate?'function toDate(s){ var p=String(s).split(/[\\/ :]/); return new Date(p[2],p[1]-1,p[0],p[3]||0,p[4]||0).getTime() }\n':'')+
    'return '+body+';';
}
function ifSummaryHTML(n){
  var c=ifGet(n), e=ifErrors(n);
  return '<div class="field"><label>'+tx('Điều kiện','Conditions')+'</label>'+
    '<div class="if-sum">'+(c.mode==='js'?'<div class="if-sr"><span class="ift">{}</span><span class="mono">JavaScript</span></div>':
      (c.rules.length?c.rules.map(function(r,i){ var o=ifOp(r.t,r.op);
        return (i?'<div class="if-sc">'+(c.comb==='or'?'OR':'AND')+'</div>':'')+'<div class="if-sr">'+ifTypeIc(r.t)+'<span class="mono">'+esc(ifShort(r.l)||tx('giá trị 1','value1'))+'</span><b>'+esc(ifOpLabel(o))+'</b>'+(ifUnary(r.t,r.op)?'':'<span class="mono">'+esc(ifShort(r.r)||tx('giá trị 2','value2'))+'</span>')+'</div>' }).join('')
      :'<div class="if-sr" style="color:var(--ink-3)">'+tx('Chưa có điều kiện','No condition')+'</div>'))+'</div>'+
    (e.length?'<span class="hint" style="color:var(--danger)">'+esc(e[0])+(e.length>1?tx(' (+'+(e.length-1)+' lỗi khác)',' (+'+(e.length-1)+' more)'):'')+'</span>':'')+'</div>'+
    '<button class="btn pri" style="width:100%;justify-content:center;margin-bottom:12px" onclick="ifOpen(\''+n.id+'\')">'+svg(I.sliders)+tx('Mở cấu hình điều kiện','Open condition editor')+'</button>';
}
function ifDraw(){
  var n=ifNode(); if(!n) return;
  var root=document.getElementById('ifxRoot');
  if(!root){ root=document.createElement('div'); root.id='ifxRoot'; document.body.appendChild(root) }
  var mb=document.getElementById('ifMidB'), st=mb?mb.scrollTop:0, ib=document.getElementById('ifInB'), st2=ib?ib.scrollTop:0;
  var t=NT.gate;
  root.innerHTML='<div class="ifx v17" role="dialog" aria-modal="true" aria-label="'+esc(n.name)+'">'+
    '<div class="ifx-top"><button class="ifx-back" onclick="ifClose()">'+svg(IF_IC.back)+tx('Quay lại khung vẽ','Back to canvas')+'</button></div>'+
    '<div class="ifx-body">'+
      '<section class="ifx-side ifx-in" aria-label="'+tx('Trường biểu mẫu của các node trước','Form fields from previous nodes')+'"><div class="ifx-sb" id="ifInB">'+ifInputHTML(n)+'</div></section>'+
      '<section class="ifx-mid">'+
        '<div class="ifx-mh"><div class="ifx-ni" style="background:'+t.c+'">'+svg(t.i)+'</div>'+
        '<input class="ifx-name" value="'+esc(n.name)+'" aria-label="'+tx('Tên node','Node name')+'" oninput="ifName(this.value)"></div>'+
        '<div class="ifx-mb" id="ifMidB">'+ifParamsHTML(n)+'</div>'+
      '</section>'+
    '</div></div>';
  mb=document.getElementById('ifMidB'); if(mb) mb.scrollTop=st;
  ib=document.getElementById('ifInB'); if(ib) ib.scrollTop=st2;
}
function ifInputHTML(n){
  var gs=ifGroups(n);
  if(!gs.length) return '<div class="ifx-none">'+tx('Các node trước chưa có trường biểu mẫu nào','Previous nodes have no form fields')+'</div>';
  return gs.map(function(g){
    return '<div class="ifx-gh">'+esc(g.gl)+'</div>'+g.vars.map(function(v){
      var s=ifSampleOf(v);
      return '<div class="ifx-f" draggable="true" ondragstart="ifDragStart(event,\''+v.v+'\')" ondragend="ifDragEnd()" title="'+esc(v.lbl)+'">'+
        '<span class="ifx-grab">'+svg(IF_IC.grab)+'</span>'+ifTypeIc(dtType(v.dt))+
        '<span class="ifx-kc"><span class="ifx-k mono">'+esc(ifLeaf(v.v))+'</span><span class="ifx-l">'+esc(v.lbl)+'</span></span>'+
        '<span class="ifx-v mono" title="'+esc(s)+'">'+esc(s===''?'—':s)+'</span></div>';
    }).join('');
  }).join('');
}
function ifParamsHTML(n){
  var c=ifGet(n), e=ifErrors(n);
  var h='<div class="ifx-mode"><span>'+tx('Cách viết điều kiện','Condition mode')+'</span><div class="ifx-seg">'+
    '<button class="'+(c.mode!=='js'?'on':'')+'" onclick="ifMode(\'rules\')">'+svg(IF_IC.list)+tx('Điều kiện','Conditions')+'</button>'+
    '<button class="'+(c.mode==='js'?'on':'')+'" onclick="ifMode(\'js\')">'+svg(IF_IC.code)+'JavaScript</button></div></div>';
  if(c.mode==='js'){
    var lines=String(c.js||'').split('\n').length, se=ifJsSyntax(c.js||'');
    h+='<div class="ifx-sec"><div class="ifx-st">JavaScript</div>'+
      '<div class="sys-ed ifx-ed"><div class="sys-gut" id="ifGut" aria-hidden="true">'+sysGutter(lines)+'</div>'+
      '<textarea class="mono" id="ifJs" spellcheck="false" aria-label="JavaScript" oninput="ifJsIn(this)" onscroll="var g=document.getElementById(\'ifGut\');if(g)g.scrollTop=this.scrollTop" onkeydown="ifTab(event,this)">'+esc(c.js||'')+'</textarea></div>'+
      '<div id="ifJsMsg">'+ifJsMsg(se)+'</div></div>';
    return h;
  }
  h+='<div class="ifx-sec"><div class="ifx-st">'+tx('Điều kiện','Conditions')+'</div><div class="if-rules">';
  c.rules.forEach(function(r,i){
    var o=ifOp(r.t,r.op), un=ifUnary(r.t,r.op), ve=ifValErr(r);
    if(i) h+='<div class="if-comb"><select class="inp" aria-label="'+'AND / OR'+'" onchange="ifComb(this.value)"><option value="and"'+(c.comb!=='or'?' selected':'')+'>'+'AND'+'</option><option value="or"'+(c.comb==='or'?' selected':'')+'>'+'OR'+'</option></select></div>';
    h+='<div class="if-row'+(un?' un':'')+'">'+
      ifCell(i,'l',r.l,tx('Giá trị 1','value1'),r.t)+
      '<div class="if-opc"><button class="if-opb'+(IFN.menu===i?' on':'')+'" aria-haspopup="menu" aria-expanded="'+(IFN.menu===i)+'" onclick="event.stopPropagation();ifMenu('+i+')">'+ifTypeIc(r.t)+'<span class="if-opl">'+esc(ifOpLabel(o))+'</span>'+svg(IF_IC.chev)+'</button>'+
        (IFN.menu===i?ifMenuHTML(i,r):'')+'</div>'+
      (un?'<div class="if-cell if-na"></div>':ifCell(i,'r',r.r,r.t==='number'?tx('Nhập số','Number'):r.t==='dateTime'?'dd/mm/yyyy':r.t==='boolean'?'true / false':tx('Giá trị 2','value2'),r.t,ve))+
      '<button class="xb if-del" title="'+tx('Xoá điều kiện','Remove condition')+'" aria-label="'+tx('Xoá điều kiện ','Remove condition ')+(i+1)+'" onclick="ifDel('+i+')">'+svg(I.trash)+'</button></div>';
  });
  h+='</div><button class="btn if-add" onclick="ifAdd()">'+svg(I.plus)+tx('Thêm điều kiện','Add condition')+'</button></div>';
  h+='<div id="ifErrs">'+ifErrsHTML(e)+'</div>';
  return h;
}
function ifCell(i,s,val,ph,t,err){
  return '<div class="if-cell"><input class="inp if-v mono'+(err?' bad':'')+'" id="ifv_'+i+'_'+s+'" value="'+esc(val||'')+'" placeholder="'+esc(ph)+'" autocomplete="off" spellcheck="false"'+(s==='r'&&t==='number'?' inputmode="decimal"':'')+' '+
    'onfocus="ifAcOpen('+i+',\''+s+'\',this)" oninput="ifIn('+i+',\''+s+'\',this)" onblur="ifAcBlur()" onkeydown="ifAcKey(event,'+i+',\''+s+'\',this)" '+
    'ondragover="ifDOver(event,this)" ondragleave="ifDLeave(this)" ondrop="ifDrop(event,'+i+',\''+s+'\')">'+
    '<div class="if-ac" id="ifac_'+i+'_'+s+'"></div></div>';
}
function ifPv(){ return '' }
function ifIn(i,s,el){
  var n=ifNode(); if(!n) return; var r=ifGet(n).rules[i]; r[s]=el.value; ifTouch(n);
  if(s==='r') el.classList.toggle('bad',!!ifValErr(r));
  var eb=document.getElementById('ifErrs'); if(eb) eb.innerHTML=ifErrsHTML(ifErrors(n));
  IFN.ac={i:i,s:s}; IFN.acSel=0; ifAcRender(el.value);
}
function ifMenuHTML(i,r){
  var t=IFN.menuT||r.t;
  return '<div class="if-opm" role="menu" onclick="event.stopPropagation()"><div class="if-opt">'+
    IF_TYPES.map(function(x){ return '<button class="'+(x[0]===t?'on':'')+'" onmouseenter="ifMenuT(\''+x[0]+'\')" onclick="ifMenuT(\''+x[0]+'\')">'+ifTypeIc(x[0])+'<span>'+tx(x[2],x[1])+'</span>'+svg(IF_IC.right)+'</button>' }).join('')+
    '</div><div class="if-opo">'+IF_OPS[t].map(function(o){ return '<button role="menuitem" class="'+(r.t===t&&r.op===o[0]?'on':'')+'" onclick="ifSetOp('+i+',\''+t+'\',\''+o[0]+'\')">'+ifOpLabel(o)+'</button>' }).join('')+'</div></div>';
}
/* value 2 của kiểu Số/Ngày/Đúng-Sai: không gợi ý trường, chỉ nhập giá trị */
function ifAcCur(q,s){
  var raw=String(q||'');
  if(s==='r'){ var n=ifNode(), r=n?ifGet(n).rules[IFN.ac?IFN.ac.i:0]:null; if(r&&r.t!=='string'&&raw.indexOf('{{')<0) return []; if(raw&&raw.indexOf('{{')<0) return [] }
  return ifAcList(raw);
}
function ifAcRender(q){
  document.querySelectorAll('.if-ac').forEach(function(x){ x.innerHTML=''; x.classList.remove('on') });
  if(!IFN.ac) return;
  var box=document.getElementById('ifac_'+IFN.ac.i+'_'+IFN.ac.s); if(!box) return;
  var l=ifAcCur(q,IFN.ac.s); if(!l.length) return;
  var last='';
  box.innerHTML='<div class="if-ach">'+tx('Chọn trường biểu mẫu của các node trước','Pick a form field from previous nodes')+'</div>'+
    l.map(function(v,k){
      var g=v.gl!==last?'<div class="if-acg">'+esc(v.gl)+'</div>':''; last=v.gl;
      return g+'<button type="button" class="'+(k===IFN.acSel?'on':'')+'" onmousedown="event.preventDefault();ifPick('+IFN.ac.i+',\''+IFN.ac.s+'\',\''+v.v+'\')">'+ifTypeIc(dtType(v.dt))+
        '<span class="if-acn"><span class="mono">'+esc(ifLeaf(v.v))+'</span><em>'+esc(v.lbl)+'</em></span><i class="mono" title="'+esc(ifSampleOf(v))+'">'+esc(ifSampleOf(v))+'</i></button>';
    }).join('');
  box.classList.add('on');
}
function ifClose(){
  var n=ifNode(); IFN.id=null; IFN.menu=null; IFN.ac=null;
  var r=document.getElementById('ifxRoot'); if(r) r.innerHTML='';
  document.body.classList.remove('ifx-on','if-drag');
  if(n){ n.cond=ifCondText(n); renderNodes(); renderInsp() }
}
function ifErrsHTML(e){ return e.length?'<div class="if-errs">'+e.map(function(x){return '<div>'+svg(I.warn)+esc(x)+'</div>'}).join('')+'</div>':'' }

/* =====================================================================
   v16 — MA TRẬN PHÊ DUYỆT: ai duyệt cho ai · từ ngày – đến ngày · đơn nào
   (bỏ vai trò; thêm Xoá)
   ===================================================================== */
function wfIdOfCode(c){ var k=Object.keys(WF_CODE).filter(function(x){return WF_CODE[x]===c})[0]; if(k) return k; var w=wfById(c); return w?w.id:'' }
function mtFiltered(){
  var q=MTV.q.trim().toLowerCase();
  return MATRIX.filter(function(r){
    var e=userBy(r.emp), s=mtSt(r);
    if(unitOf(r.emp)!==MTV.unit) return false;
    if(MTV.pb&&(!e||e.pb!==MTV.pb)) return false;
    if(MTV.wf&&r.wf.length&&r.wf.indexOf(MTV.wf)<0) return false;
    if(MTV.st&&s!==MTV.st) return false;
    if(q&&(uname(r.emp)+' '+r.emp+' '+uname(r.appr)+' '+r.appr).toLowerCase().indexOf(q)<0) return false;
    return true;
  });
}
function mtWfOpts(){ var seen={}, out=[]; WFS.forEach(function(w){ if(w.donvi===CUR_UNIT&&w.st!=='huy'&&w.id!=='it-ticket'){ var k=w.n.toLowerCase(); if(!seen[k]){ seen[k]=1; out.push([w.id,w.n]) } } }); return out }
PAGES['ma-tran']=function(){
  var u=MTV.unit, canEdit=can('mt',u), list=mtFiltered();
  var pbs=[]; USERS.forEach(function(x){ if(x.donvi===u&&pbs.indexOf(x.pb)<0) pbs.push(x.pb) });
  var cnt={on:0,soon:0,future:0,end:0}; MATRIX.forEach(function(r){ if(unitOf(r.emp)!==u) return; var s=mtSt(r); if(s==='on') cnt.on++; else if(s==='soon') cnt.soon++; else if(s==='future') cnt.future++; else cnt.end++ });
  var dis=canEdit?'':' disabled title="'+tx('Bạn không có quyền với công ty đang lọc','You have no permission for this company')+'"';
  V('<div class="page-head"><div><h1>'+tx('Ma trận phê duyệt','Approval matrix')+'</h1></div>'+
    '<div class="ph-actions">'+
    '<button class="btn" onclick="mtImport()"'+dis+'>'+svg(I.up)+tx('Import Excel','Import Excel')+'</button>'+
    '<button class="btn" onclick="mtExport()">'+svg(I.down)+tx('Xuất Excel','Export Excel')+'</button>'+
    '<button class="btn pri" onclick="openMt(\'\')"'+dis+'>'+svg(I.plus)+tx('Thêm','Add')+'</button></div></div>'+
    (canEdit?'':'<div class="alert a-info" style="margin-bottom:12px">'+svg(I.info)+'<div><b>'+tx('Bạn chỉ xem được ma trận','You can only view the matrix')+'</b></div></div>')+
    '<div class="pg-tools">'+
    '<select class="inp" style="max-width:210px" onchange="mtGo(\'wf\',this.value)" aria-label="'+tx('Loại đơn','Ticket type')+'">'+optsHTML([['',tx('Loại đơn: tất cả','Ticket type: all')]].concat(mtWfOpts()),MTV.wf||'')+'</select>'+
    '<select class="inp" style="max-width:190px" onchange="mtGo(\'st\',this.value)" aria-label="'+tx('Trạng thái','Status')+'">'+optsHTML([['',tx('Trạng thái: tất cả','Status: all')],['on',MT_ST.on[0]],['soon',MT_ST.soon[0]],['exp',MT_ST.exp[0]]],MTV.st)+'</select>'+
    '<input class="inp" style="max-width:280px" placeholder="'+tx('Tìm nhân viên hoặc người duyệt…','Search employee or approver…')+'" value="'+esc(MTV.q)+'" onchange="mtGo(\'q\',this.value)">'+
    '</div>'+
    '<div class="card"><div class="card-b flush"><div class="tbl-wrap" style="overflow:visible"><table class="tbl"><thead><tr><th>'+tx('Nhân viên','Employee')+'</th><th>'+tx('Người duyệt','Approver')+'</th><th>'+tx('Áp dụng cho đơn','Applies to')+'</th><th>'+tx('Từ – đến','From – to')+'</th><th>'+tx('Trạng thái','Status')+'</th><th></th></tr></thead><tbody>'+
    (list.length?list.map(function(r){
      var e=userBy(r.emp), s=mtSt(r), ok=mtOK(r);
      return '<tr class="clk" onclick="openMt(\''+r.id+'\')"><td class="c-main">'+esc(uname(r.emp))+'<div class="mono" style="font-size:11px;color:var(--ink-3);font-weight:400">'+r.emp+'</div></td>'+
        '<td>'+esc(uname(r.appr))+'<div class="mono" style="font-size:11px;color:var(--ink-3)">'+r.appr+'</div></td>'+
        '<td style="font-size:12.5px">'+esc(mtScope(r))+'</td>'+
        '<td class="num" style="font-size:12.5px;white-space:nowrap">'+dmy(r.tu)+' – '+dmy(r.den)+'</td>'+
        '<td>'+chipSt(MT_ST,s)+'</td>'+
        '<td class="r rm" onclick="event.stopPropagation()"><button class="xb" aria-label="'+tx('Thao tác','Actions')+'" title="'+tx('Thao tác','Actions')+'" onclick="mtMenu(\''+r.id+'\')">'+svg('<circle cx="5" cy="12" r="1.2"/><circle cx="12" cy="12" r="1.2"/><circle cx="19" cy="12" r="1.2"/>')+'</button>'+
        (MTV.menu===r.id?'<div class="rm-pop">'+
          (ok?'<button onclick="openMt(\''+r.id+'\')">'+tx('Sửa','Edit')+'</button><button onclick="mtExtend(\''+r.id+'\')">'+tx('Gia hạn','Extend')+'</button>':'')+
          (ok?'<button class="dgr" onclick="mtDelete(\''+r.id+'\')">'+tx('Xoá','Delete')+'</button>':'')+'</div>':'')+'</td></tr>';
    }).join(''):'<tr><td colspan="6">'+empty(I.tree,tx('Không có dòng ma trận nào khớp','No matrix row matches'),tx('Thử đổi bộ lọc.','Try changing the filters.'))+'</td></tr>')+
    '</tbody></table></div></div></div>'+
    '<div class="mt-leg"><span><i class="d on"></i>'+MT_ST.on[0]+' ('+cnt.on+')</span><span><i class="d soon"></i>'+MT_ST.soon[0]+' ('+cnt.soon+')</span><span><i class="d end"></i>'+MT_ST.exp[0]+' ('+cnt.end+')</span></div>');
};
function mtClash(d,selfId){
  return MATRIX.filter(function(r){ return r.id!==selfId&&!r.off&&r.emp===d.emp&&scopeMeet(r.wf,d.wf)&&r.tu<=d.den&&d.tu<=r.den })[0]||null;
}
function clashMsg(c){ return tx('Trùng với dòng ','Overlaps row ')+c.id+' · '+uname(c.emp)+' · '+mtScope(c)+' · '+dmy(c.tu)+'–'+dmy(c.den) }
function mtSummary(r){ return uname(r.emp)+' → '+uname(r.appr)+' · '+mtScope(r)+' · '+dmy(r.tu)+'–'+dmy(r.den) }
function openMt(id){
  if(!can('mt')&&!id){ denied(tx('Bạn không có quyền thêm dòng ma trận','You cannot add matrix rows')); return }
  var r=id?mtById(id):null;
  MTE=r?{id:r.id,empTxt:empLabel(userBy(r.emp)||{n:r.emp,u:r.emp,pb:''}),emp:r.emp,appr:r.appr,all:!r.wf.length,wfs:r.wf.slice(),tu:r.tu,den:r.den,gc:r.gc,tried:0,ro:!mtOK(r)}
        :{id:'',empTxt:'',emp:'',appr:'',all:true,wfs:[],tu:TODAY,den:'',gc:'',tried:0,ro:false};
  MTV.menu=''; drawMt();
}
function mtDraft(){ return {emp:MTE.emp,appr:MTE.appr,wf:MTE.all?[]:MTE.wfs.slice(),tu:MTE.tu,den:MTE.den,gc:MTE.gc,off:0} }
function mtErrors(){
  var E={}, B=[], e=userBy(MTE.emp);
  if(!MTE.id){
    if(!MTE.empTxt.trim()) E.emp=tx('Chọn nhân viên','Select an employee');
    else if(!e){ E.emp=tx('Không tìm thấy nhân viên trong danh bạ','Employee not found in the directory'); B.push(1) }
    else if(uStat(e.u)!=='on'){ E.emp=uStat(e.u)==='left'?tx('Nhân viên đã nghỉ việc','The employee has left'):tx('Account nhân viên đang bị khoá','The employee account is locked'); B.push(1) }
    else if(!can('mt',e.donvi)){ E.emp=tx('Bạn không có quyền khai ma trận cho nhân viên này','You cannot add rows for this employee'); B.push(1) }
    else if(e.donvi!==MTV.unit){ E.emp=tx('Nhân viên không thuộc đơn vị '+unitName(MTV.unit),'The employee is not in '+unitName(MTV.unit)); B.push(1) }
  }
  var ap=userBy(MTE.appr);
  if(!MTE.appr) E.appr=tx('Nhập account người duyệt','Enter the approver account');
  else if(!ap){ E.appr=tx('Account không tồn tại','Account does not exist'); B.push(1) }
  else if(uStat(ap.u)==='locked'){ E.appr=tx('Account đang bị khoá','Account is locked'); B.push(1) }
  else if(uStat(ap.u)==='left'){ E.appr=tx('Người duyệt đã nghỉ việc','The approver has left'); B.push(1) }
  else if(ap.u===MTE.emp){ E.appr=tx('Người duyệt không được trùng nhân viên','The approver cannot be the employee'); B.push(1) }
  if(!MTE.all&&!MTE.wfs.length) E.wf=tx('Chọn ít nhất một loại đơn','Select at least one ticket type');
  if(!MTE.tu) E.tu=tx('Nhập ngày bắt đầu','Enter a start date');
  if(!MTE.den) E.den=tx('Nhập ngày kết thúc','Enter an end date');
  else if(MTE.tu&&MTE.den<=MTE.tu){ E.den=tx('Ngày kết thúc phải sau ngày bắt đầu','The end date must be after the start date'); B.push(1) }
  if(!E.emp&&!E.wf&&MTE.tu&&MTE.den&&MTE.den>MTE.tu&&MTE.emp){ var c=mtClash(mtDraft(),MTE.id); if(c){ E.clash=clashMsg(c); B.push(1) } }
  return {E:E,block:B.length>0,any:Object.keys(E).length>0};
}
function mtScopePanel(){
  if(!MTE.emp||!userBy(MTE.emp)) return '<div class="mini">'+tx('Chọn nhân viên để xem dòng này được dùng ở những bước duyệt nào.','Pick an employee to see which approval steps use this row.')+'</div>';
  var d=mtDraft(), date=(MTE.tu&&MTE.tu>TODAY)?MTE.tu:TODAY, used=[], not=[];
  Object.keys(DEFS).forEach(function(k){
    if(!MTE.all&&MTE.wfs.indexOf(k)<0) return;
    approvalNodes(k).forEach(function(n){
      var a=apGet(n); if(a.mode==='fixed'||!a.src.some(function(s){return s.k==='mt'})) return;
      var r=apResolve(n,MTE.emp,date,k,[d]), mt=r.steps.filter(function(s){return s.k==='mt'})[0];
      var item={dn:DEFS[k].n,nn:n.name};
      if(mt&&mt.state==='hit'&&mt.rows.indexOf(d)>=0) used.push(item);
      else {
        var before=r.steps.filter(function(s){return s.state==='hit'&&s.k!=='mt'})[0];
        item.why=before?before.name+tx(' xếp trước Ma trận và đã có người (',' is ranked above the matrix and found (')+before.ok.map(uname).join(', ')+')'
          :(mt&&mt.rows&&mt.rows.length?tx('Có dòng khác khai riêng cho loại đơn này','Another row targets this ticket type'):(d.appr&&badReason(d.appr,d.emp)?tx('Người duyệt không hợp lệ: ','Invalid approver: ')+badReason(d.appr,d.emp):tx('Dòng chưa có hiệu lực ở ngày ','Row not effective on ')+dmy(date)));
        not.push(item);
      }
    });
  });
  return '<div class="fieldset" style="margin:0"><div class="lg">'+tx('Phạm vi tác dụng · tính ở ngày ','Effect · as of ')+dmy(date)+'</div>'+
    '<div style="font-size:13px;margin-bottom:6px"><b>'+tx('Dòng này được dùng ở '+used.length+' bước duyệt.','Used in '+used.length+' approval step(s).')+'</b>'+(not.length?' <b style="color:var(--warn)">'+tx('Không được dùng ở '+not.length+' bước:','Not used in '+not.length+' step(s):')+'</b>':'')+'</div>'+
    used.map(function(x){return '<div class="sc-l ok">'+svg(I.check)+esc(x.dn)+' · '+esc(x.nn)+'</div>'}).join('')+
    not.map(function(x){return '<div class="sc-l no">'+svg(I.warn)+'<span>'+esc(x.dn)+' · '+esc(x.nn)+'<br><span style="color:var(--ink-3)">'+esc(x.why)+'</span></span></div>'}).join('')+
    (!used.length&&!not.length?'<div class="mini">'+tx('Chưa có bước duyệt nào dùng Ma trận phê duyệt cho các loại đơn đã chọn.','No approval step uses the Approval matrix for the selected ticket types.')+'</div>':'')+'</div>';
}
function drawMt(){
  var ed=!!MTE.id, ro=MTE.ro, ev=mtErrors(), E=ev.E, T=MTE.tried;
  function er(k){ return (T||k==='clash'||(k==='appr'&&MTE.appr)||(k==='den'&&MTE.den)||(k==='emp'&&MTE.empTxt))&&E[k]?E[k]:'' }
  function hint(k){ return er(k)?'<span class="hint" style="color:var(--danger)">'+esc(er(k))+'</span>':'' }
  var dis=ro?' disabled':'', ap=userBy(MTE.appr), req=' <span style="color:var(--danger)">*</span>';
  var emps=USERS.filter(function(x){ return uStat(x.u)==='on'&&can('mt',x.donvi)&&x.donvi===MTV.unit });
  var h='<div class="drw-h"><div style="flex:1"><h2>'+(ed?tx('Sửa dòng ma trận','Edit matrix row'):tx('Thêm dòng ma trận','Add matrix row'))+'</h2><div class="meta">'+(ed?'<span class="mono">'+MTE.id+'</span>'+chipSt(MT_ST,mtSt(mtById(MTE.id))):'')+'</div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">'+
    (ro?'<div class="alert a-info" style="margin-bottom:12px">'+svg(I.info)+'<div><b>'+tx('Chỉ xem','View only')+'</b></div></div>':'')+
    (er('clash')?'<div class="alert a-dgr" style="margin-bottom:12px">'+svg(I.warn)+'<div><b>'+tx('Không lưu được','Cannot save')+'</b>'+esc(er('clash'))+'</div></div>':'')+
    '<div class="field"><label for="mt_emp">'+tx('Nhân viên (được duyệt)','Employee (being approved)')+req+'</label>'+
    '<input class="inp'+(er('emp')?' bad':'')+'" id="mt_emp" list="mtEmpList" value="'+esc(MTE.empTxt)+'" placeholder="'+tx('Gõ tên hoặc account…','Type a name or account…')+'" onchange="mtSet()"'+(ed?' disabled':dis)+'>'+
    '<datalist id="mtEmpList">'+emps.map(function(x){return '<option value="'+esc(empLabel(x))+'">'}).join('')+'</datalist>'+hint('emp')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="mt_appr">'+tx('Người duyệt (account)','Approver (account)')+req+'</label>'+
    '<input class="inp mono'+(er('appr')?' bad':'')+'" id="mt_appr" value="'+esc(MTE.appr)+'" placeholder="'+tx('Ví dụ: huylq','e.g. huylq')+'" onchange="mtSet()"'+dis+'>'+
    (er('appr')?hint('appr'):(ap?'<span class="hint">'+esc(ap.n)+' · '+esc(ap.cv)+' · '+esc(unitName(ap.donvi))+'</span>':''))+'</div>'+
    '<div class="field" style="margin-top:12px"><label>'+tx('Áp dụng cho','Applies to')+'</label>'+
    '<label class="ck"><input type="radio" name="mt_all" '+(MTE.all?'checked':'')+dis+' onchange="mtSet(\'all\',true)"><span>'+tx('Mọi loại đơn','All ticket types')+'</span></label>'+
    '<label class="ck"><input type="radio" name="mt_all" '+(!MTE.all?'checked':'')+dis+' onchange="mtSet(\'all\',false)"><span>'+tx('Chọn loại đơn','Choose ticket types')+'</span></label>'+
    (!MTE.all?mtTTBox(ro):'')+hint('wf')+'</div>'+
    '<div class="g2" style="margin-top:12px"><div class="field"><label for="mt_tu">'+tx('Từ ngày','From')+req+'</label><input class="inp" type="date" id="mt_tu" value="'+esc(MTE.tu)+'" onchange="mtSet()"'+dis+'>'+hint('tu')+'</div>'+
    '<div class="field"><label for="mt_den">'+tx('Đến ngày','To')+req+'</label><input class="inp'+(er('den')?' bad':'')+'" type="date" id="mt_den" value="'+esc(MTE.den)+'" onchange="mtSet()"'+dis+'>'+hint('den')+'</div></div>'+
    '<div class="field" style="margin-top:12px"><label for="mt_gc">'+tx('Lý do','Reason')+'</label><textarea class="inp'+(er('gc')?' bad':'')+'" id="mt_gc" rows="2" maxlength="250" onchange="mtSet()"'+dis+'>'+esc(MTE.gc)+'</textarea>'+hint('gc')+'</div>'+
    '</div>'+
    '<div class="drw-f">'+(ro?'':'<button class="btn pri" onclick="mtSave()"'+(ev.block?' disabled':'')+'>'+svg(I.save)+tx('Lưu','Save')+'</button>')+
    (ed&&!ro?'<button class="btn dgr" onclick="mtDelete(\''+MTE.id+'\')">'+svg(I.trash)+tx('Xoá','Delete')+'</button>':'')+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>';
  showDrawer(h);
}
function mtSave(){
  mtGrab(); var ev=mtErrors(); MTE.tried=1;
  if(ev.any){ drawMt(); return }
  var r=MTE.id?mtById(MTE.id):null;
  if(r&&!mtOK(r)){ denied(tx('Không đủ quyền sửa dòng này','Not allowed to edit this row')); return }
  if(!r&&!can('mt',unitOf(MTE.emp))){ denied(tx('Không đủ quyền khai ma trận cho nhân viên này','Not allowed for this employee')); return }
  var d=mtDraft(), bef=r?mtSummary(r):'';
  if(r){ r.appr=d.appr; r.wf=d.wf; r.tu=d.tu; r.den=d.den; r.gc=(d.gc||'').trim() }
  else { MT_SEQ++; r={id:'MT-'+('0000'+MT_SEQ).slice(-4),emp:d.emp,appr:d.appr,wf:d.wf,tu:d.tu,den:d.den,gc:(d.gc||'').trim(),log:[]}; MATRIX.unshift(r) }
  var aft=mtSummary(r), hd=bef?tx('Sửa dòng ma trận','Edit matrix row'):tx('Thêm dòng ma trận','Add matrix row');
  r.log.unshift({t:nowStr(),u:ACTORS[ACT].acc,h:hd,dt:bef?bef+' → '+aft:aft});
  auditLog(hd,r.id+' · '+(bef?bef+' → ':'')+aft);
  closeDrawer(); toast((bef?tx('Đã lưu dòng ','Saved row '):tx('Đã thêm dòng ','Added row '))+r.id,tx('Đã gửi thông báo tới ','Notified ')+uname(r.appr));
  MTV.unit=unitOf(r.emp); if(MTV.st&&mtSt(r)!==MTV.st) MTV.st=''; PAGES['ma-tran']();
}
function mtDelete(id){
  MTV.menu=''; var r=mtById(id); if(!r) return; if(!mtOK(r)){ denied(tx('Không đủ quyền xoá dòng này','Not allowed to delete this row')); return }
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+tx('Xoá dòng ma trận?','Delete matrix row?')+'</h2><div class="meta"><span class="mono">'+r.id+'</span><span>'+esc(mtSummary(r))+'</span></div></div><button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
    '<div class="drw-b"><div class="alert a-dgr">'+svg(I.warn)+'<div><b>'+tx('Xoá hẳn khỏi ma trận','Removes the row permanently')+'</b>'+tx('Ticket mới sẽ không còn tra theo dòng này. Task đã giao không tự đổi người. Thao tác được ghi nhật ký hệ thống.','New tickets will no longer use this row. Tasks already assigned do not change. The action is logged.')+'</div></div></div>'+
    '<div class="drw-f"><button class="btn dgr" onclick="doDelete(\''+r.id+'\')">'+svg(I.trash)+tx('Xoá dòng','Delete row')+'</button><button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>');
}
function doDelete(id){
  var r=mtById(id); if(!r) return; var i=MATRIX.indexOf(r); MATRIX.splice(i,1);
  auditLog(tx('Xoá dòng ma trận','Delete matrix row'),r.id+' · '+mtSummary(r));
  closeDrawer(); toast(tx('Đã xoá ','Deleted ')+r.id,mtSummary(r)); PAGES['ma-tran']();
}

/* ---- Excel: bỏ cột Mã vai trò ---- */
var CSV_HEAD=LANG==='en'?['Employee account','Approver account','Ticket type code','From','To']:['Account nhân viên','Account người duyệt','Mã loại đơn','Từ ngày','Đến ngày'];
var CSV_HEAD_EXP=CSV_HEAD.concat([tx('Lý do','Reason')]);   /* v28: tệp xuất có thêm Lý do; import không dùng cột này */
function mtRowCsv(r){ return [r.emp,r.appr,r.wf.map(wfCodeOf).join(';'),dmy(r.tu),dmy(r.den),r.gc].map(csvCell).join(',') }
var MTI_SAMPLE=[
 'tudv,lanlt,,10/10/2026,10/01/2027,'+tx('Chưa có quản lý trên HRM','No manager in HRM'),
 'sonpt,khoalm,TANG_LUONG,15/08/2026,31/03/2027,'+tx('Gia hạn dự án HRDX','HRDX project extension'),
 'ngocbt,vietdq,DANG_KY_OT,01/11/2026,31/01/2027,'+tx('Điều động tạm thời','Temporary assignment'),
 'mailt,huylq,,01/10/2026,31/12/2026,'+tx('Hỗ trợ dự án','Project support'),
 'binhpv,kienpv,,10/10/2026,31/12/2026,'+tx('Duyệt thay','Stand-in approver'),
 'lannt,lannt,,10/10/2026,31/12/2026,'+tx('Thử','Test'),
 'hangvt,dungvt4,MA_SAI,10/10/2026,31/12/2026,'+tx('Thử','Test')
].join('\n');
function impCheck(cells,seen){
  var r={emp:cells[0]||'',appr:cells[1]||'',wfc:(cells[2]||'').split(';').map(function(x){return x.trim()}).filter(Boolean),tuS:cells[3]||'',denS:cells[4]||'',gc:'',err:'',kind:''};
  var e=userBy(r.emp), ap=userBy(r.appr);
  r.wf=[]; var badWf='';
  r.wfc.forEach(function(c){ var id=wfIdOfCode(c); if(id) r.wf.push(id); else badWf=c });
  r.tu=dmyToIso(r.tuS); r.den=dmyToIso(r.denS);
  if(!e) r.err=tx('Account nhân viên “'+r.emp+'” không có trong danh bạ','Employee account “'+r.emp+'” not found');
  else if(uStat(e.u)!=='on') r.err=uStat(e.u)==='left'?tx('Nhân viên đã nghỉ việc','Employee has left'):tx('Account nhân viên đang bị khoá','Employee account locked');
  else if(!can('mt',e.donvi)) r.err=tx('Bạn không có quyền khai ma trận cho nhân viên này','Not allowed for this employee');
  else if(e.donvi!==MTV.unit) r.err=tx('Nhân viên không thuộc đơn vị '+unitName(MTV.unit),'The employee is not in '+unitName(MTV.unit));
  else if(!ap) r.err=tx('Account người duyệt “'+r.appr+'” không tồn tại','Approver account “'+r.appr+'” does not exist');
  else if(uStat(ap.u)==='locked') r.err=tx('Account đang bị khoá','Account locked');
  else if(uStat(ap.u)==='left') r.err=tx('Người duyệt đã nghỉ việc','Approver has left');
  else if(ap.u===e.u) r.err=tx('Người duyệt không được trùng nhân viên','Approver cannot be the employee');
  else if(badWf) r.err=tx('Mã loại đơn “'+badWf+'” không tồn tại','Ticket type code “'+badWf+'” does not exist');
  else if(!r.tu||!r.den) r.err=tx('Ngày phải theo dạng dd/MM/yyyy','Dates must be dd/MM/yyyy');
  else if(r.den<=r.tu) r.err=tx('Ngày kết thúc phải sau ngày bắt đầu','End date must be after start date');
  if(!r.err){
    var key=r.emp+'|'+r.appr+'|'+r.wf.slice().sort().join();
    var same=MATRIX.filter(function(m){ return !m.off&&m.emp+'|'+m.appr+'|'+m.wf.slice().sort().join()===key })[0];
    var c=mtClash({emp:r.emp,wf:r.wf,tu:r.tu,den:r.den},same?same.id:'');
    if(c) r.err=clashMsg(c);
    else { var inFile=seen.filter(function(s){ return s.emp===r.emp&&scopeMeet(s.wf,r.wf)&&s.tu<=r.den&&r.tu<=s.den })[0];
      if(inFile) r.err=tx('Trùng với một dòng khác trong cùng tệp (nhân viên '+inFile.emp+')','Overlaps another row in the same file (employee '+inFile.emp+')') }
    if(!r.err){ r.kind=same?'upd':'new'; r.target=same?same.id:'' }
  }
  if(r.err) r.kind='err';
  return r;
}
function drawImp(){
  var s=MTI.step, n={new:0,upd:0,err:0}; MTI.rows.forEach(function(r){n[r.kind]++});
  var kinds={new:[tx('Thêm mới','New'),'c-done'],upd:[tx('Cập nhật','Update'),'c-info'],err:[tx('Lỗi — bỏ qua','Error — skipped'),'c-rej']};
  var h='<div class="drw-h"><div style="flex:1"><h2>'+tx('Import ma trận từ Excel','Import matrix from Excel')+'</h2><div class="meta"><span>'+tx('Bước ','Step ')+s+'/2 · '+(s===1?tx('Chọn tệp','Choose a file'):tx('Xem kết quả kiểm tra rồi mới ghi','Review the check before writing'))+'</span></div></div><button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">';
  if(s===1){
    h+=(MTI.msg?'<div class="alert a-dgr" style="margin-bottom:12px">'+svg(I.warn)+'<div><b>'+tx('Chưa đọc được tệp','Could not read the file')+'</b>'+esc(MTI.msg)+'</div></div>':'')+
      '<div class="card" style="box-shadow:none"><div class="card-h"><h2>'+tx('Cấu trúc tệp','File layout')+'</h2></div><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>'+tx('Cột','Column')+'</th><th>'+tx('Ví dụ','Example')+'</th><th>'+tx('Bắt buộc','Required')+'</th></tr></thead><tbody>'+
      [[CSV_HEAD[0],'annv',tx('Có','Yes')],[CSV_HEAD[1],'huylq',tx('Có','Yes')],[CSV_HEAD[2],'NGHI_PHEP;DANG_KY_OT',tx('Không — để trống = mọi loại đơn','No — blank = all ticket types')],[CSV_HEAD[3],'01/09/2026',tx('Có','Yes')],[CSV_HEAD[4],'31/12/2026',tx('Có','Yes')]].map(function(x){
        return '<tr><td class="c-main">'+esc(x[0])+'</td><td class="mono" style="font-size:12px">'+esc(x[1])+'</td><td>'+x[2]+'</td></tr>'}).join('')+'</tbody></table></div></div></div>'+
      '<div class="field" style="margin-top:14px"><label for="imp_f">'+tx('Tệp import','Import file')+'</label><input class="inp" type="file" id="imp_f" accept=".csv,.xlsx" onchange="impFile(this)"></div>';
  } else {
    h+='<div class="stats" style="grid-template-columns:repeat(3,1fr);margin-bottom:12px"><div class="stat"><div class="lbl">'+kinds.new[0]+'</div><div class="val">'+n.new+'</div></div><div class="stat"><div class="lbl">'+kinds.upd[0]+'</div><div class="val">'+n.upd+'</div></div><div class="stat'+(n.err?' stat-alert':'')+'"><div class="lbl">'+tx('Lỗi','Errors')+'</div><div class="val">'+n.err+'</div></div></div>'+
      '<div class="card" style="box-shadow:none"><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>#</th><th>'+tx('Nhân viên','Employee')+'</th><th>'+tx('Người duyệt','Approver')+'</th><th>'+tx('Loại đơn','Ticket types')+'</th><th>'+tx('Từ – đến','From – to')+'</th><th>'+tx('Kết quả','Result')+'</th></tr></thead><tbody>'+
      MTI.rows.map(function(r,i){
        return '<tr'+(r.kind==='err'?' style="background:var(--danger-soft)"':'')+'><td class="num">'+(i+2)+'</td><td class="mono" style="font-size:12px">'+esc(r.emp)+'</td><td class="mono" style="font-size:12px">'+esc(r.appr)+'</td><td style="font-size:12px">'+(r.wf.length?esc(r.wf.map(wfNm).join(', ')):(r.wfc.length?'<span class="mono">'+esc(r.wfc.join('; '))+'</span>':tx('Mọi loại đơn','All')))+'</td>'+
          '<td class="num" style="font-size:12px;white-space:nowrap">'+esc(r.tuS)+' – '+esc(r.denS)+'</td><td>'+chipSt(kinds,r.kind)+(r.err?'<div style="font-size:11.5px;color:var(--danger);margin-top:3px">'+esc(r.err)+'</div>':(r.target?'<div style="font-size:11.5px;color:var(--ink-3);margin-top:3px">'+tx('Cập nhật ','Updates ')+r.target+'</div>':''))+'</td></tr>';
      }).join('')+'</tbody></table></div></div></div>';
  }
  h+='</div><div class="drw-f">'+(s===2?'<button class="btn pri" onclick="impApply()"'+(n.new+n.upd?'':' disabled')+'>'+svg(I.save)+tx('Xác nhận ghi ','Write ')+(n.new+n.upd)+tx(' dòng',' row(s)')+'</button><button class="btn" onclick="MTI.step=1;MTI.msg=\'\';drawImp()">'+tx('Chọn tệp khác','Choose another file')+'</button>':'')+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Đóng','Close')+'</button></div>';
  showDrawer(h,'wide');
}
function impApply(){
  if(!can('mt',MTV.unit)){ denied(tx('Không đủ quyền ghi import','Not allowed to import')); return }
  var a=0,b=0;
  MTI.rows.forEach(function(r){
    if(r.kind==='new'){ MT_SEQ++; var m={id:'MT-'+('0000'+MT_SEQ).slice(-4),emp:r.emp,appr:r.appr,wf:r.wf,tu:r.tu,den:r.den,gc:r.gc,log:[]};
      m.log.unshift({t:nowStr(),u:ACTORS[ACT].acc,h:tx('Thêm dòng ma trận (import)','Add matrix row (import)'),dt:mtSummary(m)}); MATRIX.unshift(m); a++ }
    else if(r.kind==='upd'){ var m2=mtById(r.target), bef=mtSummary(m2); m2.tu=r.tu; m2.den=r.den; m2.gc=r.gc;
      m2.log.unshift({t:nowStr(),u:ACTORS[ACT].acc,h:tx('Cập nhật dòng ma trận (import)','Update matrix row (import)'),dt:bef+' → '+mtSummary(m2)}); b++ }
  });
  var bad=MTI.rows.filter(function(r){return r.kind==='err'}).length;
  auditLog(tx('Import ma trận từ tệp','Import matrix from file'),MTI.file+' · +'+a+' · ~'+b+' · ✕'+bad);
  closeDrawer(); toast(tx('Đã ghi ','Wrote ')+(a+b)+tx(' dòng',' row(s)'),tx('Thêm mới ','New ')+a+' · '+tx('cập nhật ','updated ')+b+' · '+tx('bỏ qua ','skipped ')+bad); MTV.st=''; PAGES['ma-tran']();
}
function mtScope(r){ return r.wf.length?r.wf.map(wfNm).join(', '):tx('Mọi loại đơn','All ticket types') }

/* v17 — bỏ trạng thái Đã ngưng */
function mtSt(r){ if(TODAY>r.den) return 'exp'; if(dayDiff(TODAY,r.den)<=REMIND_DAYS) return 'soon'; return 'on' }
function mtActive(r,date){ return r.tu<=date&&date<=r.den }
function mtClash(d,selfId){ return MATRIX.filter(function(r){ return r.id!==selfId&&r.emp===d.emp&&scopeMeet(r.wf,d.wf)&&r.tu<=d.den&&d.tu<=r.den })[0]||null }
MATRIX.forEach(function(r){ delete r.off });
if(MTV.st==='off'||MTV.st==='act') MTV.st='';

/* =====================================================================
   v17 — USER GROUP: mỗi vai trò có 1 hoặc nhiều người; Thêm / Sửa / Xoá
   UGM[unit] = [{code, members:[account…]}]
   ===================================================================== */
var UGM={};
Object.keys(UGS).forEach(function(u){
  var m=[], by={};
  UGS[u].recs.forEach(function(x){ if(!by[x.code]){ by[x.code]={code:x.code,members:[]}; m.push(by[x.code]) } if(by[x.code].members.indexOf(x.acc)<0) by[x.code].members.push(x.acc) });
  UGM[u]=m;
});
function ugRoles(unit){ return UGM[unit||UGV.unit]||[] }
function ugMembers(unit,code){ var r=(UGM[unit]||[]).filter(function(x){return x.code===code})[0]; return r?r.members.slice():[] }
function ugPositions(){
  var seen={}, out=[];
  Object.keys(UGM).forEach(function(u){ UGM[u].forEach(function(r){ if(!seen[r.code]){ seen[r.code]=1; out.push([r.code,posName(r.code)]) } }) });
  return out;
}
function ugUsage(code){
  var out=[];
  Object.keys(DEFS).forEach(function(k){ approvalNodes(k).forEach(function(n){ var a=apGet(n);
    if((a.main==='ug'&&a.code===code)||a.prio.some(function(p){return p.k==='ug'&&p.code===code})) out.push(DEFS[k].n+' · '+n.name) }) });
  return out;
}
PAGES['user-group']=function(){
  if(unitsFor().indexOf(UGV.unit)<0) UGV.unit=unitsFor()[0];
  var u=UGV.unit, q=(UGV.q||'').trim().toLowerCase(), roles=ugRoles(u);
  if(UGV.role&&!roles.some(function(r){return r.code===UGV.role})) UGV.role='';
  var list=roles.filter(function(r){ return !UGV.role||r.code===UGV.role }).map(function(r){
    var mem=r.members.filter(function(a){ return !q||(ugNm(a)+' '+a+' '+posName(r.code)).toLowerCase().indexOf(q)>=0 });
    return {r:r,mem:mem};
  }).filter(function(x){ return x.mem.length||(!q&&!x.r.members.length) }).sort(function(a,b){ return posName(a.r.code).localeCompare(posName(b.r.code)) });
  var body=list.map(function(x){
    var rs=Math.max(1,x.mem.length), act='<td class="r ug-act" rowspan="'+rs+'">'+
      '<button class="xb look" title="'+tx('Sửa','Edit')+'" aria-label="'+tx('Sửa vai trò ','Edit role ')+esc(posName(x.r.code))+'" onclick="ugOpen(\''+x.r.code+'\')">'+svg(I.edit)+'</button>'+
      '<button class="xb" title="'+tx('Xoá','Delete')+'" aria-label="'+tx('Xoá vai trò ','Delete role ')+esc(posName(x.r.code))+'" onclick="ugDel(\''+x.r.code+'\')">'+svg(I.trash)+'</button></td>';
    var role='<td class="c-main ug-role" rowspan="'+rs+'">'+esc(posName(x.r.code))+'</td>';
    if(!x.mem.length) return '<tr class="ug-first">'+role+'<td colspan="2" style="color:var(--ink-3)">'+tx('Chưa có người','No one yet')+'</td>'+act+'</tr>';
    return x.mem.map(function(a,i){
      return '<tr class="'+(i===0?'ug-first':'ug-more')+'">'+(i===0?role:'')+'<td>'+esc(ugNm(a))+'</td><td class="c-code">'+esc(a)+'</td>'+(i===0?act:'')+'</tr>';
    }).join('');
  }).join('');
  V('<div class="page-head"><div><h1>User Group</h1></div>'+
    '<div class="ph-actions"><button class="btn pri" onclick="ugOpen(\'\')">'+svg(I.plus)+tx('Thêm vai trò','Add role')+'</button></div></div>'+
    '<div class="pg-tools"><input class="inp" style="max-width:320px" placeholder="'+tx('Tìm họ tên hoặc account…','Search name or account…')+'" value="'+esc(UGV.q)+'" onchange="ugGo(\'q\',this.value)">'+
    '<select class="inp" style="max-width:240px" onchange="ugGo(\'role\',this.value)" aria-label="'+tx('Vai trò','Role')+'">'+optsHTML([['',tx('Vai trò: tất cả','Role: all')]].concat(roles.map(function(r){return [r.code,posName(r.code)]})),UGV.role)+'</select></div>'+
    '<div class="card"><div class="card-b flush"><div class="tbl-wrap"><table class="tbl ug-tbl"><thead><tr><th>'+tx('Vai trò','Role')+'</th><th>'+tx('Họ tên','Full name')+'</th><th>Account</th><th></th></tr></thead><tbody>'+
    (body||'<tr><td colspan="4">'+empty(I.users,tx('Không có bản ghi nào khớp','No matching records'),tx('Thử bỏ bớt bộ lọc.','Try removing some filters.'))+'</td></tr>')+
    '</tbody></table></div></div></div>');
};
/* ---- Thêm / Sửa ---- */
var UGE=null;
function ugOpen(code){
  var r=code?ugRoles().filter(function(x){return x.code===code})[0]:null;
  UGE={code:code||'',name:r?posName(r.code):'',members:r?r.members.slice():[],add:'',err:{},tried:0};
  ugDraw();
}
function ugGrab(){ var a=document.getElementById('ug_name'); if(a) UGE.name=a.value; var b=document.getElementById('ug_add'); if(b) UGE.add=b.value }
function ugDraw(){
  var ed=!!UGE.code, E=UGE.err, req=' <span style="color:var(--danger)">*</span>';
  var opts=USERS.filter(function(x){ return uStat(x.u)==='on'&&x.donvi===UGV.unit&&UGE.members.indexOf(x.u)<0 });
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+(ed?tx('Sửa vai trò','Edit role'):tx('Thêm vai trò','Add role'))+'</h2>'+
    '<div class="meta"><span>'+tx('Một vai trò có thể có một hoặc nhiều người','A role can have one or more people')+'</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">'+
    '<div class="field"><label for="ug_name">'+tx('Vai trò','Role')+req+'</label>'+
    '<input class="inp'+(E.name?' bad':'')+'" id="ug_name" list="ugRoleList" value="'+esc(UGE.name)+'" placeholder="'+tx('Ví dụ: Trưởng phòng Nhân sự','e.g. HR Manager')+'" maxlength="80">'+
    '<datalist id="ugRoleList">'+ugPositions().map(function(p){return '<option value="'+esc(p[1])+'">'}).join('')+'</datalist>'+
    (E.name?'<span class="hint" style="color:var(--danger)">'+esc(E.name)+'</span>':'')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_add">'+tx('Người giữ vai trò','People in this role')+req+'</label>'+
    '<div class="ug-addr"><input class="inp" id="ug_add" list="ugUserList" value="'+esc(UGE.add)+'" placeholder="'+tx('Gõ họ tên hoặc account…','Type a name or account…')+'" autocomplete="off" onkeydown="if(event.key===\'Enter\'){event.preventDefault();ugAddM()}">'+
    '<button class="btn" onclick="ugAddM()">'+svg(I.plus)+tx('Thêm người','Add person')+'</button></div>'+
    '<datalist id="ugUserList">'+opts.map(function(x){return '<option value="'+esc(x.n+' · '+x.u)+'">'}).join('')+'</datalist>'+
    (E.add?'<span class="hint" style="color:var(--danger)">'+esc(E.add)+'</span>':'')+
    '<div class="ug-mem">'+(UGE.members.length?UGE.members.map(function(a,i){
      return '<div class="ug-m"><div><b>'+esc(uname(a))+'</b><span class="mono">'+esc(a)+'</span></div><button class="xb" title="'+tx('Bỏ khỏi vai trò','Remove from role')+'" aria-label="'+tx('Bỏ ','Remove ')+esc(uname(a))+'" onclick="ugRmM('+i+')">'+svg(I.x)+'</button></div>';
    }).join(''):'<div class="ap-empty">'+tx('Chưa có người nào','No one yet')+'</div>')+'</div>'+
    (E.members?'<span class="hint" style="color:var(--danger)">'+esc(E.members)+'</span>':'')+'</div></div>'+
    '<div class="drw-f"><button class="btn pri" onclick="ugSave()">'+svg(I.save)+tx('Lưu','Save')+'</button>'+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>');
}
function ugAddM(){
  ugGrab(); UGE.err={};
  var u=apParseUser(UGE.add);
  if(!UGE.add.trim()) UGE.err.add=tx('Chọn một người trong danh bạ','Pick a person from the directory');
  else if(!u) UGE.err.add=tx('Không tìm thấy trong danh bạ','Not found in the directory');
  else if(uStat(u.u)!=='on') UGE.err.add=tx('Người này đã nghỉ việc hoặc bị khoá account','This person has left or is locked');
  else if(UGE.members.indexOf(u.u)>=0) UGE.err.add=tx('Người này đã có trong vai trò','Already in this role');
  else { UGE.members.push(u.u); UGE.add='' }
  ugDraw(); setTimeout(function(){ var e=document.getElementById('ug_add'); if(e) e.focus() },30);
}
function ugRmM(i){ ugGrab(); UGE.members.splice(i,1); UGE.err={}; ugDraw() }
function ugCodeOf(name){
  var k=Object.keys(HRM_NAMES).filter(function(c){ return HRM_NAMES[c].toLowerCase()===name.toLowerCase() })[0];
  if(k) return k;
  var c=slugVi(name).toUpperCase().replace(/-/g,'_')||('VT_'+Date.now()); HRM_NAMES[c]=name; return c;
}
function ugSave(){
  ugGrab(); UGE.err={}; var nm=(UGE.name||'').trim(), list=ugRoles();
  if(!nm) UGE.err.name=tx('Nhập tên vai trò','Enter the role name');
  if(nm&&list.some(function(r){ return r.code!==UGE.code&&posName(r.code).toLowerCase()===nm.toLowerCase() })) UGE.err.name=tx('Vai trò này đã có — dùng Sửa để thêm người','This role already exists — use Edit to add people');
  if(!UGE.members.length) UGE.err.members=tx('Thêm ít nhất một người','Add at least one person');
  if(Object.keys(UGE.err).length) return ugDraw();
  var r=UGE.code?list.filter(function(x){return x.code===UGE.code})[0]:null, bef=r?posName(r.code)+': '+r.members.join(', '):'';
  if(r){ HRM_NAMES[r.code]=nm; r.members=UGE.members.slice() }
  else list.push({code:ugCodeOf(nm),members:UGE.members.slice()});
  var aft=nm+': '+UGE.members.join(', ');
  auditLog(r?tx('Sửa vai trò User Group','Edit User Group role'):tx('Thêm vai trò User Group','Add User Group role'),(bef?bef+' → ':'')+aft);
  closeDrawer(); toast(r?tx('Đã lưu vai trò','Role saved'):tx('Đã thêm vai trò','Role added'),nm+' · '+UGE.members.length+tx(' người',' people'));
  PAGES['user-group']();
}
function ugDel(code){
  var r=ugRoles().filter(function(x){return x.code===code})[0]; if(!r) return;
  var used=ugUsage(code);
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+tx('Xoá vai trò?','Delete role?')+'</h2><div class="meta"><span>'+esc(posName(code))+' · '+r.members.length+tx(' người',' people')+'</span></div></div><button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div>'+
    '<div class="drw-b">'+(used.length
      ?'<div class="alert a-dgr">'+svg(I.warn)+'<div><b>'+tx('Không xoá được — vai trò đang được dùng','Cannot delete — the role is in use')+'</b>'+used.map(esc).join('<br>')+'</div></div>'
      :'<div class="alert a-warn">'+svg(I.warn)+'<div><b>'+tx('Xoá vai trò và danh sách người giữ vai trò','Deletes the role and its people')+'</b>'+tx('Thao tác được ghi nhật ký hệ thống.','The action is logged.')+'</div></div>')+'</div>'+
    '<div class="drw-f">'+(used.length?'':'<button class="btn dgr" onclick="ugDoDel(\''+code+'\')">'+svg(I.trash)+tx('Xoá vai trò','Delete role')+'</button>')+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Đóng','Close')+'</button></div>');
}
function ugDoDel(code){
  var l=ugRoles(), i=-1; l.forEach(function(x,k){ if(x.code===code) i=k }); if(i<0) return;
  var r=l.splice(i,1)[0]; auditLog(tx('Xoá vai trò User Group','Delete User Group role'),posName(code)+': '+r.members.join(', '));
  closeDrawer(); toast(tx('Đã xoá vai trò','Role deleted'),posName(code)); PAGES['user-group']();
}


