/* =====================================================================
   v19 — Biểu mẫu: chỉ 4 kiểu dữ liệu (Văn bản, Số, Ngày, Danh sách chọn);
   Danh sách chọn có nguồn lựa chọn: Tự nhập / Lấy từ danh mục bộ trường
   ===================================================================== */
var FT=LANG==='en'?{text:'Text',num:'Number',date:'Date',select:'Dropdown list',file:'Attachment'}:{text:'Văn bản',num:'Số',date:'Ngày',select:'Danh sách chọn',file:'Tệp đính kèm'};   /* v24: thêm lại Tệp đính kèm */
function fld19(f){
  if(!f||!f.t||f.t==='section'||f.t==='note'||f.t==='divider') return;
  var t=f.t;
  if(t==='area'||t==='time'){ f.t='text'; delete f.rows }
  else if(t==='money') f.t='num';
  else if(t==='radio') f.t='select';
  else if(t==='check'){ f.t='select'; if(!f.o) f.o=tx('Có\nKhông','Yes\nNo') }
  else if(t==='user'){ f.t='select'; if(!f.o) f.o=USERS.filter(function(u){return uStat(u.u)==='on'}).slice(0,6).map(function(u){return u.n+' · '+u.u}).join('\n') }
  else if(t==='ro') f.t=(f.dt==='number'||/^(so|muc|luong|quyPhep|otThang)/.test(f.k))?'num':'text';
}
Object.keys(DEFS).forEach(function(k){ DEFS[k].nodes.forEach(function(n){ (n.form||[]).forEach(fld19) }) });
FORMLIB.forEach(function(b){ b.f.forEach(fld19) });
function fldLibLists(){
  var out=[]; FORMLIB.forEach(function(b){ b.f.forEach(function(f){ if(f.t==='select'&&f.o) out.push({key:b.id+'.'+f.k,bo:b.n,f:f}) }) }); return out;
}
function fldOptHTML(f,i){
  var lib=!!f.osrc, lists=fldLibLists(), opts=String(f.o||'').split('\n').filter(Boolean);
  var h='<div class="field"><label>'+tx('Nguồn lựa chọn','Option source')+'</label><div class="fo-src">'+
    '<label class="ck"><input type="radio" name="fo_'+i+'" '+(lib?'':'checked')+' onchange="fldSrc('+i+',0)"><span>'+tx('Tự nhập','Enter manually')+'</span></label>'+
    '<label class="ck"><input type="radio" name="fo_'+i+'" '+(lib?'checked':'')+' onchange="fldSrc('+i+',1)"><span>'+tx('Lấy từ danh mục bộ trường','From the field-set catalogue')+'</span></label></div>';
  if(!lib) return h+'<textarea class="inp" placeholder="'+tx('Mỗi dòng một giá trị','One value per line')+'" onchange="setField('+i+',\'o\',this.value)">'+esc(f.o||'')+'</textarea></div>';
  var bos={}, order=[]; lists.forEach(function(x){ if(!bos[x.bo]){ bos[x.bo]=[]; order.push(x.bo) } bos[x.bo].push(x) });
  return h+'<select class="inp" onchange="fldPick('+i+',this.value)" aria-label="'+tx('Trường danh sách trong danh mục','Catalogue list field')+'">'+
    order.map(function(b){ return '<optgroup label="'+esc(b)+'">'+bos[b].map(function(x){ return '<option value="'+x.key+'"'+(f.osrc===x.key?' selected':'')+'>'+esc(x.f.l)+'</option>' }).join('')+'</optgroup>' }).join('')+'</select>'+
    '<div class="fo-list">'+opts.map(function(o){ return '<span>'+esc(o)+'</span>' }).join('')+'</div></div>';
}
function fldLibGet(key){ return fldLibLists().filter(function(x){return x.key===key})[0]||null }
function fldSrc(i,lib){
  var n=fnode(); if(!n) return; var f=n.form[i];
  if(lib){ var L=fldLibLists(), x=fldLibGet(f.osrc)||L.filter(function(y){return y.f.k===f.k})[0]||L[0]; if(x){ f.osrc=x.key; f.o=x.f.o } }
  else delete f.osrc;
  renderNodes(); renderInsp(); markDirty();
}
function fldPick(i,key){ var n=fnode(); if(!n) return; var f=n.form[i], x=fldLibGet(key); if(!x) return; f.osrc=key; f.o=x.f.o; renderInsp(); markDirty() }
