var MDI_VI={"nguoi":"account people human person","nhan vien":"account badge person","nhan su":"account badge people group","nhom":"group multiple","phong ban":"group domain office","khach hang":"account heart handshake","luong":"cash wallet currency","tien":"cash wallet currency bank money","thanh toan":"credit cash receipt","ngan hang":"bank","tai chinh":"cash currency bank","hoa don":"receipt invoice","ke toan":"calculator receipt cash","cham cong":"clock timer","dong ho":"clock timer","gio":"clock timer","thoi gian":"clock timer calendar","lich":"calendar","ngay":"calendar","nghi phep":"calendar beach airplane","le tet":"calendar gift","ca lam":"clock calendar","dao tao":"school book certificate","hoc":"school book","sach":"book","chung chi":"certificate license","tuyen dung":"account-plus search","phong van":"account-search message","khen thuong":"medal trophy star","phuc loi":"heart gift","thai san":"baby","suc khoe":"medical heart hospital","y te":"medical hospital heart","bao hiem":"shield umbrella heart","an toan":"shield lock","bao mat":"lock shield security","phap che":"scale gavel","hop dong":"file handshake draw","ky":"draw","van ban":"file text","tai lieu":"file text","bao cao":"chart file","thong ke":"chart poll","bieu do":"chart","cong tac":"airplane bag suitcase","may bay":"airplane","di chuyen":"car bus airplane train","xe":"car bus truck","o to":"car","van chuyen":"truck","giao hang":"truck package","toa nha":"domain office","van phong":"office briefcase coffee","hanh chinh":"office domain clipboard","nha":"home","dia chi":"map home","ban do":"map","vi tri":"map","may tinh":"monitor laptop desktop","cntt":"monitor laptop server lan","phan cung":"monitor laptop","phan mem":"application code","may chu":"server","mang":"lan wifi","du lieu":"database","dien thoai":"phone cellphone","cuoc goi":"phone","email":"email","thu":"email","tin nhan":"message comment","thong bao":"bell","cai dat":"cog settings","cau hinh":"cog settings tune","cong cu":"wrench tools hammer","sua chua":"wrench hammer","khoa":"lock key","chia khoa":"key","quyen":"key shield lock","tai san":"package archive","kho":"package archive warehouse","mua":"cart basket","ban hang":"cart store","cua hang":"store","qua tang":"gift","sao":"star","danh gia":"star","muc tieu":"target flag","kpi":"target chart","co":"flag","quoc te":"earth","toan cau":"earth","an uong":"food silverware coffee","com":"food silverware","cafe":"coffee","camera":"camera video","truyen thong":"camera video message","anh":"image","video":"video","in":"printer","may in":"printer","the":"card badge","id":"card badge","phe duyet":"check clipboard","duyet":"check","tu choi":"close cancel","huy":"cancel close","canh bao":"alert","thong tin":"information","tim kiem":"magnify","loc":"filter","xoa":"delete trash","sua":"pencil edit","them":"plus","du an":"folder briefcase clipboard","cong viec":"briefcase clipboard check","nhiem vu":"clipboard check","ghi chu":"note text","danh sach":"format-list clipboard","bieu mau":"file-document form clipboard","don":"file clipboard","ticket":"ticket","ho tro":"help lifebuoy headset","khieu nai":"message alert","phan hoi":"message comment","thue":"receipt calculator","bhxh":"shield heart","bao hiem xa hoi":"shield heart","nghi viec":"account-off exit","thoi viec":"account-off exit","chuyen cong tac":"swap-horizontal airplane","dieu chuyen":"swap-horizontal","tang luong":"trending-up cash","thu viec":"account-clock","hop":"calendar-clock account-group","phong hop":"account-group calendar","cay":"leaf tree","moi truong":"leaf earth","dien":"flash lightbulb","nuoc":"water","lua":"fire","thoi tiet":"weather-cloudy","nhiet do":"thermometer"};
var GIL={q:'',list:[],n:0,CH:240,all:null};
function gNorm(s){ return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'d').toLowerCase().trim() }
function gPretty(n){ var t=n.replace(/-outline$/,'').replace(/-/g,' '); return t.charAt(0).toUpperCase()+t.slice(1) }
function gInner(k){
  if(k&&k.indexOf('m:')===0&&MDI[k.slice(2)]) return '<path fill="currentColor" stroke="none" d="'+MDI[k.slice(2)]+'"/>';
  var a=gIcons(); for(var i=0;i<a.length;i++) if(a[i][0]===k) return a[i][2];
  return a[a.length-1][2];
}
function gIco(k){ return gInner(k) }
/* một thư viện duy nhất: 41 biểu tượng nghiệp vụ dùng nhiều đứng đầu, tiếp theo là phần còn lại */
function gItems(){
  if(GIL.all) return GIL.all;
  var out=gIcons().map(function(x){ return {k:x[0],l:x[1],s:gNorm(x[1])+' '+x[0],c:1} });
  Object.keys(MDI).forEach(function(n){ out.push({k:'m:'+n,l:gPretty(n),s:n.replace(/-/g,' '),c:0}) });
  return GIL.all=out;
}
/* t gõ trực tiếp: khớp đầu từ · từ khoá tiếng Việt quy đổi sang tiếng Anh: khớp nguyên từ (tránh car → card, bus → rhombus) */
function gTerms(t){
  var o=[{t:t,x:0}];
  Object.keys(MDI_VI).forEach(function(k){ if((' '+k+' ').indexOf(' '+t+' ')>=0) MDI_VI[k].split(' ').forEach(function(w){ if(!o.some(function(z){return z.t===w})) o.push({t:w,x:1}) }) });
  return o;
}
function gHit(s,z){ return z.x?(' '+s+' ').indexOf(' '+z.t+' ')>=0:(' '+s).indexOf(' '+z.t)>=0 }
function gBuild(){
  var q=gNorm(GIL.q), all=gItems(), l;
  if(q){
    var tk=q.split(/\s+/).filter(Boolean).map(gTerms);
    l=all.filter(function(it){ return tk.every(function(ts){ return ts.some(function(z){ return gHit(it.s,z) }) }) });
  } else {
    l=all.slice();
    var si=l.map(function(it){return it.k}).indexOf(GRP&&GRP.ic);
    if(si>40){ var sel=l.splice(si,1)[0]; l.splice(41,0,sel) }   /* biểu tượng đang chọn nằm ngay sau nhóm Thường dùng */
  }
  GIL.list=l; GIL.n=0;
}
function gChunk(){
  var h='', e=Math.min(GIL.list.length,GIL.n+GIL.CH);
  for(var i=GIL.n;i<e;i++){ var it=GIL.list[i], on=GRP&&GRP.ic===it.k;
    h+='<button type="button" role="radio" aria-checked="'+on+'" class="gi'+(on?' on':'')+'" data-k="'+it.k+'" title="'+esc(it.l)+'" aria-label="'+esc(it.l)+'">'+svg(gInner(it.k))+'</button>' }
  GIL.n=e; return h;
}
function gCount(){ return gItems().length }
function grpIcPicker(){
  GIL.q=''; gBuild();
  return '<div class="field" style="margin-top:14px"><label>'+tx('Biểu tượng nhóm','Group icon')+' <span style="color:var(--danger)">*</span></label>'+
    '<div class="gi-bar"><div class="gi-srch">'+svg('<circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/>')+
    '<input class="inp" id="giQ" type="search" autocomplete="off" placeholder="'+tx('Tìm biểu tượng, ví dụ: tiền, xe, lịch, người…','Search icons, e.g. money, car, calendar, user…')+'" oninput="giSearch(this.value)" aria-label="'+tx('Tìm biểu tượng','Search icons')+'"></div>'+
    '<span class="gi-name">'+tx('Thư viện biểu tượng','Icon library')+'<span>'+gCount().toLocaleString(LANG==='vi'?'vi-VN':'en-US')+'</span></span></div>'+
    '<div class="gi-scroll" id="giList" role="radiogroup" aria-label="'+tx('Biểu tượng nhóm','Group icon')+'" tabindex="0" onclick="giPick(event)" onscroll="giMore()">'+gChunk()+'</div>'+
    '<div class="gi-meta" id="giMeta" hidden></div></div>';
}
function giFill(){
  var el=document.getElementById('giList'); if(!el) return;
  el.innerHTML=gChunk()||'<div class="gi-empty">'+tx('Không có biểu tượng khớp. Thử từ khoá khác, tiếng Việt hoặc tiếng Anh.','No matching icon. Try another keyword, in Vietnamese or English.')+'</div>';
  el.scrollTop=0;
  var m=document.getElementById('giMeta'); if(m){ m.hidden=!GIL.q; m.textContent=GIL.list.length+tx(' kết quả',' results') }
}
function giSearch(v){ GIL.q=v; gBuild(); giFill() }
function giMore(){
  var el=document.getElementById('giList'); if(!el||GIL.n>=GIL.list.length) return;
  if(el.scrollTop+el.clientHeight>=el.scrollHeight-200) el.insertAdjacentHTML('beforeend',gChunk());
}
function giPick(e){
  var b=e.target.closest&&e.target.closest('.gi'); if(!b) return;
  var el=document.getElementById('giList'), p=el.querySelector('.gi.on');
  if(p){ p.classList.remove('on'); p.setAttribute('aria-checked','false') }
  b.classList.add('on'); b.setAttribute('aria-checked','true');
  GRP.ic=b.getAttribute('data-k');
}

