  var lg=function(h,dt){ return [{t:'01/10/2026 09:30',u:'admin',h:h,dt:dt}] };
  MATRIX.push(
    {id:'MT-0013',emp:'tungvt',appr:'namnv',wf:[],tu:'2026-10-01',den:'2026-12-31',gc:tx('Hỗ trợ tuyển dụng quý IV tại Phòng Nhân sự','Supporting Q4 recruitment in the HR Department'),log:lg(tx('Thêm dòng ma trận','Add matrix row'),'Võ Thanh Tùng → Nguyễn Văn Nam')},
    {id:'MT-0014',emp:'thudt',appr:'hoatt',wf:['fis-leave-approval'],tu:'2026-09-15',den:'2026-11-30',gc:tx('Làm dự án ERP của Phòng Giải pháp','Working on the Solutions Department ERP project'),log:lg(tx('Thêm dòng ma trận','Add matrix row'),'Đinh Thị Thu → Trần Thị Hoa')}
  );
