/* ---------- lịch sử phiên bản trong ngăn Sửa thông tin quy trình ---------- */
function wfVerRows(w){
  var V=w.vers||[], n=V.length;
  return V.map(function(v,i){
    var st=i>0?[tx('Phiên bản cũ','Previous version'),'c-draft']
      :w.st==='run'?[tx('Đang áp dụng','In use'),'c-done']:w.st==='huy'?[tx('Đã vô hiệu hoá','Disabled'),'c-rej']:[tx('Nháp','Draft'),'c-draft'];
    return '<tr><td class="num c-main">v'+w.v+'.'+(n-i)+'</td><td class="num">'+esc(v.t||'—')+'</td><td>'+esc(accName(v.w||''))+'<div class="mono" style="font-size:11px;color:var(--ink-3)">'+esc(v.w||'')+'</div></td><td><span class="chip nb '+st[1]+'">'+st[0]+'</span></td></tr>';
  }).join('');
}
(function(){
  var dw=drawWfInfo;
  drawWfInfo=function(){
    dw.apply(this,arguments);
    var w=wfById(WI.id), b=document.querySelector('#drw .drw-b'); if(!w||!b||!(w.vers&&w.vers.length)) return;
    b.insertAdjacentHTML('beforeend','<div class="fieldset" style="margin-top:16px"><div class="lg">'+tx('Lịch sử phiên bản','Version history')+'</div>'+
      '<div class="tbl-wrap"><table class="tbl wf-vh"><thead><tr><th>'+tx('Phiên bản','Version')+'</th><th>'+tx('Xuất bản lúc','Published at')+'</th><th>'+tx('Người xuất bản','Published by')+'</th><th>'+tx('Trạng thái','Status')+'</th></tr></thead><tbody>'+wfVerRows(w)+'</tbody></table></div></div>');
  };
})();

/* ---------- vô hiệu hoá quy trình (trong màn thiết kế) ---------- */
(function(){
  var cp=canvasPage;
  canvasPage=function(){
    cp.apply(this,arguments);
    var w=wfById(DSN.id), bar=document.querySelector('#view .dsn-bar'); if(!w||!bar||w.st!=='run') return;
    var sv=bar.querySelector('button[onclick="saveDef()"]');
    var h='<button class="btn dgr" id="wfOffBtn" onclick="openDisableWf()">'+svg('<circle cx="12" cy="12" r="8.5"/><path d="M6 6l12 12"/>')+tx('Vô hiệu hoá','Disable')+'</button>';
    if(sv) sv.insertAdjacentHTML('beforebegin',h); else bar.insertAdjacentHTML('beforeend',h);
  };
})();
function openDisableWf(){
  var w=wfById(DSN.id); if(!w) return;
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+tx('Vô hiệu hoá quy trình?','Disable this workflow?')+'</h2><div class="meta"><span>'+esc(w.n)+' · '+wfVer(w)+' · '+esc(unitName(w.donvi))+'</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">'+
    '<div class="alert a-warn">'+svg(I.warn)+'<div><b>'+tx('Quy trình chuyển sang Đã huỷ và ngừng nhận ticket mới','The workflow becomes Cancelled and stops accepting new tickets')+'</b>'+
    (w.run?tx('Còn '+w.run+' ticket đang xử lý theo '+wfVer(w)+' — các ticket này vẫn chạy tiếp đến khi hoàn tất.',w.run+' ticket(s) in progress on '+wfVer(w)+' continue until they finish.'):tx('Không có ticket nào đang xử lý.','No ticket is in progress.'))+'</div></div></div>'+
    '<div class="drw-f"><button class="btn dgr" onclick="doDisableWf()">'+svg('<circle cx="12" cy="12" r="8.5"/><path d="M6 6l12 12"/>')+tx('Vô hiệu hoá','Disable')+'</button>'+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>');
}
function doDisableWf(){
  var w=wfById(DSN.id); if(!w) return;
  w.st='huy'; w.pub=0; if(DEFS[w.id]) DEFS[w.id].pub=0; w.mod={acc:ACTORS[ACT].acc,t:nowStr()}; DSN.dirty=0;
  auditLog(tx('Vô hiệu hoá quy trình','Disable workflow'),w.id+' · '+wfVer(w)+' · '+unitName(w.donvi));
  closeDrawer(); openLib();
  toast(tx('Đã vô hiệu hoá “','Disabled “')+w.n+'”',tx('Quy trình ở trạng thái Đã huỷ, không nhận ticket mới','The workflow is Cancelled and accepts no new tickets'));
}

/* ---------- User Group: thêm / sửa người bằng nhập tay họ tên + account ---------- */
function ugOpen(code){
  var r=code?ugRoles().filter(function(x){return x.code===code})[0]:null;
  UGE={code:code||'',name:r?posName(r.code):'',mcode:r?r.code:'',codeTouched:!!r,mo:r?(r.mo||''):'',members:r?r.members.slice():[],pn:'',pa:'',pe:-1,err:{}};
  ugDraw();
}
function ugGrab(){
  var g=function(id){ return document.getElementById(id) };
  if(g('ug_name')) UGE.name=g('ug_name').value;
  if(g('ug_code')&&!UGE.code) UGE.mcode=g('ug_code').value;
  if(g('ug_mo')) UGE.mo=g('ug_mo').value;
  if(g('ug_pn')) UGE.pn=g('ug_pn').value;
  if(g('ug_pa')) UGE.pa=g('ug_pa').value;
}
function ugDraw(){
  var ed=!!UGE.code, E=UGE.err, req=' <span style="color:var(--danger)">*</span>', pe=UGE.pe>=0;
  var hint=function(k){ return E[k]?'<span class="hint" style="color:var(--danger)">'+esc(E[k])+'</span>':'' };
  var key='onkeydown="if(event.key===\'Enter\'){event.preventDefault();ugAddM()}"';
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+(ed?tx('Sửa vai trò','Edit role'):tx('Thêm vai trò','Add role'))+'</h2>'+
    '<div class="meta"><span>'+tx('Đơn vị ','Unit ')+esc(unitName(UGV.unit))+'</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">'+
    '<div class="field"><label for="ug_name">'+tx('Tên vai trò','Role name')+req+'</label>'+
    '<input class="inp'+(E.name?' bad':'')+'" id="ug_name" value="'+esc(UGE.name)+'" placeholder="'+tx('Ví dụ: Trưởng phòng Hành chính','e.g. Head of Administration')+'" maxlength="80" oninput="ugNameIn(this.value)" autocomplete="off">'+hint('name')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_code">'+tx('Mã vai trò','Role code')+req+'</label>'+
    '<input class="inp mono'+(E.code?' bad':'')+'" id="ug_code" value="'+esc(UGE.mcode)+'" placeholder="TRUONG_PHONG_HC" maxlength="40"'+(ed?' disabled':' oninput="UGE.codeTouched=1;this.value=this.value.toUpperCase()"')+'>'+hint('code')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_mo">'+tx('Mô tả','Description')+'</label>'+
    '<textarea class="inp" id="ug_mo" rows="2" maxlength="250">'+esc(UGE.mo)+'</textarea></div>'+
    '<div class="field" style="margin-top:12px"><label>'+tx('Người giữ vai trò','People in this role')+'</label>'+
    '<div class="ug-in"><input class="inp" id="ug_pn" value="'+esc(UGE.pn)+'" placeholder="'+tx('Họ tên','Full name')+'" maxlength="80" autocomplete="off" '+key+'>'+
    '<input class="inp mono" id="ug_pa" value="'+esc(UGE.pa)+'" placeholder="Account" maxlength="40" autocomplete="off" '+key+'>'+
    '<button class="btn" onclick="ugAddM()">'+(pe?svg(I.save)+tx('Cập nhật','Update'):svg(I.plus)+tx('Thêm người','Add person'))+'</button>'+
    (pe?'<button class="btn" onclick="UGE.pe=-1;UGE.pn=\'\';UGE.pa=\'\';UGE.err={};ugDraw()">'+tx('Huỷ','Cancel')+'</button>':'')+'</div>'+hint('add')+
    '<div class="ug-mem">'+(UGE.members.length?UGE.members.map(function(a,i){
      return '<div class="ug-m'+(UGE.pe===i?' on':'')+'"><div><b>'+esc(ugNm(a))+'</b><span class="mono">'+esc(a)+'</span></div>'+
        '<button class="xb look" title="'+tx('Sửa','Edit')+'" aria-label="'+tx('Sửa ','Edit ')+esc(ugNm(a))+'" onclick="ugEditM('+i+')">'+svg(I.edit)+'</button>'+
        '<button class="xb" title="'+tx('Bỏ khỏi vai trò','Remove from role')+'" aria-label="'+tx('Bỏ ','Remove ')+esc(ugNm(a))+'" onclick="ugRmM('+i+')">'+svg(I.x)+'</button></div>';
    }).join(''):'<div class="ap-empty">'+tx('Chưa có người nào','No one yet')+'</div>')+'</div></div></div>'+
    '<div class="drw-f"><button class="btn pri" onclick="ugSave()">'+svg(I.save)+(ed?tx('Lưu','Save'):tx('Thêm vai trò','Add role'))+'</button>'+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>');
}
function ugAddM(){
  ugGrab(); UGE.err={};
  var n=(UGE.pn||'').trim(), a=(UGE.pa||'').trim().toLowerCase();
  if(!n||!a){ var e=document.getElementById(n?'ug_pa':'ug_pn'); if(e) e.focus(); return }
  if(!/^[a-z0-9._-]{2,40}$/.test(a)) UGE.err.add=tx('Account chỉ gồm chữ thường không dấu, số, dấu chấm, gạch nối','Account may only contain lowercase letters, digits, dots and hyphens');
  else if(UGE.members.some(function(x,i){ return x===a&&i!==UGE.pe })) UGE.err.add=tx('Account này đã có trong vai trò','This account is already in the role');
  if(UGE.err.add) return ugDraw();
  UG_NM[a]=n;
  if(UGE.pe>=0) UGE.members[UGE.pe]=a; else UGE.members.push(a);
  UGE.pe=-1; UGE.pn=''; UGE.pa=''; ugDraw();
  setTimeout(function(){ var e=document.getElementById('ug_pn'); if(e) e.focus() },30);
}
function ugEditM(i){ ugGrab(); var a=UGE.members[i]; UGE.pe=i; UGE.pn=ugNm(a); UGE.pa=a; UGE.err={}; ugDraw(); setTimeout(function(){ var e=document.getElementById('ug_pn'); if(e) e.focus() },30) }
function ugRmM(i){ ugGrab(); UGE.members.splice(i,1); if(UGE.pe===i){ UGE.pe=-1; UGE.pn=''; UGE.pa='' } else if(UGE.pe>i) UGE.pe--; UGE.err={}; ugDraw() }

