function ugImport(){ UGI={step:1,rows:[],file:'',msg:''}; ugDrawImp() }
function ugImpFile(inp){
  var f=inp.files&&inp.files[0]; if(!f) return;
  if(!/\.csv$/i.test(f.name)){ UGI.msg=tx('Bản demo chỉ đọc tệp .csv (UTF-8) — bản thật đọc trực tiếp .xlsx.','The demo reads .csv (UTF-8) only — the real system reads .xlsx.'); ugDrawImp(); return }
  var rd=new FileReader(); rd.onload=function(){ ugImpRun(String(rd.result),f.name) }; rd.readAsText(f,'utf-8');
}
function ugImpRun(text,name){
  var rows=parseCsv(text).filter(function(c){ return c.some(function(x){ return String(x||'').trim() }) });
  if(rows.length&&/vai trò|role/i.test(rows[0][0]||'')) rows.shift();
  var roles=ugRoles(), seen={}, newCodes={};
  UGI.rows=rows.map(function(c){
    var r={rn:(c[0]||'').trim(),rc:(c[1]||'').trim().toUpperCase(),pn:(c[2]||'').trim(),pa:(c[3]||'').trim().toLowerCase(),kind:'',err:''};
    if(!r.rn) r.err=tx('Thiếu tên vai trò','Role name missing');
    else if(!r.pn) r.err=tx('Thiếu họ tên','Full name missing');
    else if(!r.pa) r.err=tx('Thiếu account','Account missing');
    else if(!/^[a-z0-9._-]{2,40}$/.test(r.pa)) r.err=tx('Account “'+r.pa+'” sai định dạng','Account “'+r.pa+'” has an invalid format');
    else if(r.rc&&!/^[A-Z0-9_]+$/.test(r.rc)) r.err=tx('Mã vai trò “'+r.rc+'” sai định dạng','Role code “'+r.rc+'” has an invalid format');
    if(!r.err){
      var ex=roles.filter(function(x){ return (r.rc&&x.code===r.rc)||posName(x.code).toLowerCase()===r.rn.toLowerCase() })[0];
      if(ex&&r.rc&&ex.code!==r.rc) r.err=tx('Vai trò “'+r.rn+'” đã có với mã '+ex.code,'Role “'+r.rn+'” already exists with code '+ex.code);
      else if(ex&&posName(ex.code).toLowerCase()!==r.rn.toLowerCase()) r.err=tx('Mã '+r.rc+' đang dùng cho vai trò “'+posName(ex.code)+'”','Code '+r.rc+' is used by “'+posName(ex.code)+'”');
      else {
        r.code=ex?ex.code:(r.rc||ugCodeGen(r.rn));
        var k=r.code+'|'+r.pa;
        if(seen[k]) r.err=tx('Trùng với một dòng khác trong tệp','Duplicates another row in the file');
        else { seen[k]=1;
          if(ex&&ex.members.indexOf(r.pa)>=0) r.kind='skip';
          else if(!ex&&!newCodes[r.code]){ r.kind='role'; newCodes[r.code]=1 }
          else r.kind='add';
        }
      }
    }
    if(r.err) r.kind='err';
    return r;
  });
  UGI.file=name; UGI.step=2; UGI.msg=''; ugDrawImp();
}
function ugDrawImp(){
  var s=UGI.step, n={role:0,add:0,skip:0,err:0}; UGI.rows.forEach(function(r){ n[r.kind]++ });
  var K={role:[tx('Vai trò mới + người','New role + person'),'c-done'],add:[tx('Thêm người','Add person'),'c-info'],skip:[tx('Đã có — bỏ qua','Already there — skipped'),'c-draft'],err:[tx('Lỗi — bỏ qua','Error — skipped'),'c-rej']};
  var h='<div class="drw-h"><div style="flex:1"><h2>'+tx('Import User Group từ Excel','Import User Group from Excel')+'</h2><div class="meta"><span>'+tx('Đơn vị ','Unit ')+esc(unitName(UGV.unit))+' · '+tx('Bước ','Step ')+s+'/2</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">';
  if(s===1){
    h+=(UGI.msg?'<div class="alert a-dgr" style="margin-bottom:12px">'+svg(I.warn)+'<div><b>'+tx('Chưa đọc được tệp','Could not read the file')+'</b>'+esc(UGI.msg)+'</div></div>':'')+
      '<div class="card" style="box-shadow:none"><div class="card-h"><h2>'+tx('Cấu trúc tệp','File layout')+'</h2></div><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>'+tx('Cột','Column')+'</th><th>'+tx('Ví dụ','Example')+'</th><th>'+tx('Bắt buộc','Required')+'</th></tr></thead><tbody>'+
      [[UG_HEAD[0],tx('Trưởng phòng Nhân sự','HR Manager'),tx('Có','Yes')],[UG_HEAD[1],'TRUONG_PHONG_NS',tx('Không — để trống thì tự sinh từ tên','No — blank = generated from the name')],[UG_HEAD[2],'Phạm Thu Hà',tx('Có','Yes')],[UG_HEAD[3],'haptt',tx('Có','Yes')]].map(function(x){
        return '<tr><td class="c-main">'+esc(x[0])+'</td><td class="mono" style="font-size:12px">'+esc(x[1])+'</td><td>'+x[2]+'</td></tr>' }).join('')+'</tbody></table></div></div></div>'+
      '<div class="field" style="margin-top:14px"><label for="ugi_f">'+tx('Tệp import','Import file')+'</label><input class="inp" type="file" id="ugi_f" accept=".csv,.xlsx" onchange="ugImpFile(this)"></div>';
  } else {
    h+='<div class="stats" style="grid-template-columns:repeat(4,1fr);margin-bottom:12px">'+['role','add','skip','err'].map(function(k){ return '<div class="stat'+(k==='err'&&n.err?' stat-alert':'')+'"><div class="lbl">'+K[k][0]+'</div><div class="val">'+n[k]+'</div></div>' }).join('')+'</div>'+
      '<div class="card" style="box-shadow:none"><div class="card-b flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>#</th><th>'+tx('Vai trò','Role')+'</th><th>'+tx('Họ tên','Full name')+'</th><th>Account</th><th>'+tx('Kết quả','Result')+'</th></tr></thead><tbody>'+
      UGI.rows.map(function(r,i){
        return '<tr'+(r.kind==='err'?' style="background:var(--danger-soft)"':'')+'><td class="num">'+(i+2)+'</td><td>'+esc(r.rn)+(r.code?'<div class="mono" style="font-size:11px;color:var(--ink-3)">'+esc(r.code)+'</div>':'')+'</td><td>'+esc(r.pn)+'</td><td class="mono" style="font-size:12px">'+esc(r.pa)+'</td>'+
          '<td>'+chipSt(K,r.kind)+(r.err?'<div style="font-size:11.5px;color:var(--danger);margin-top:3px">'+esc(r.err)+'</div>':'')+'</td></tr>';
      }).join('')+'</tbody></table></div></div></div>';
  }
  h+='</div><div class="drw-f">'+(s===2?'<button class="btn pri" onclick="ugImpApply()"'+(n.role+n.add?'':' disabled')+'>'+svg(I.save)+tx('Xác nhận ghi ','Write ')+(n.role+n.add)+tx(' dòng',' row(s)')+'</button><button class="btn" onclick="UGI.step=1;UGI.msg=\'\';ugDrawImp()">'+tx('Chọn tệp khác','Choose another file')+'</button>':'')+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Đóng','Close')+'</button></div>';
  showDrawer(h,'wide');
}
function ugImpApply(){
  var L=ugRoles(), nr=0, np=0;
  if(!UGM[UGV.unit]) UGM[UGV.unit]=L;
  UGI.rows.forEach(function(r){
    if(r.kind!=='role'&&r.kind!=='add') return;
    var ro=L.filter(function(x){return x.code===r.code})[0];
    if(!ro){ ro={code:r.code,members:[],mo:''}; L.push(ro); HRM_NAMES[r.code]=r.rn; nr++ }
    if(ro.members.indexOf(r.pa)<0){ ro.members.push(r.pa); np++ }
    UG_NM[r.pa]=r.pn;
  });
  var bad=UGI.rows.filter(function(r){return r.kind==='err'}).length;
  auditLog(tx('Import User Group từ tệp','Import User Group from file'),unitName(UGV.unit)+' · '+UGI.file+' · +'+nr+tx(' vai trò',' role(s)')+' · +'+np+tx(' người',' people')+' · ✕'+bad);
  closeDrawer(); toast(tx('Đã import User Group','User Group imported'),'+'+nr+tx(' vai trò mới · +',' new role(s) · +')+np+tx(' người · bỏ qua ',' people · skipped ')+(UGI.rows.length-nr-np>0?UGI.rows.filter(function(r){return r.kind==='skip'||r.kind==='err'}).length:0));
  UGV.q=''; UGV.role=''; PAGES['user-group']();
}

/* =====================================================================
   v37 — Ma trận: "Áp dụng cho" chọn được loại ticket của đơn vị khác
   (nhân viên điều chuyển có thời hạn sang đơn vị khác dùng đơn của đơn vị đó)
   ===================================================================== */
var TT_UNITS=['fsoft','fptis','ftel'];
function ttAllInit(){ TT_UNITS.forEach(function(u){ ttList(u) }) }
function ttUnitOf(id){ ttAllInit(); for(var i=0;i<TT_UNITS.length;i++){ if(MT_TT[TT_UNITS[i]].some(function(x){return x.id===id})) return TT_UNITS[i] } return wfById(id)?wfById(id).donvi:'' }
function ttById(id){ ttAllInit(); var ks=Object.keys(MT_TT); for(var i=0;i<ks.length;i++){ var t=MT_TT[ks[i]].filter(function(x){return x.id===id})[0]; if(t) return t } return null }
function ttLabel(id,base){ var u=ttUnitOf(id); return ttName(id)+(u&&u!==base?' ('+unitName(u)+')':'') }
function wfIdOfCode(c){
  c=String(c||'').trim().toUpperCase(); ttAllInit();
  var order=[MTV.unit].concat(TT_UNITS.filter(function(u){return u!==MTV.unit}));      /* đơn vị đang chọn trước, rồi các đơn vị khác */
  for(var i=0;i<order.length;i++){ var t=(MT_TT[order[i]]||[]).filter(function(x){return x.code===c})[0]; if(t) return t.id }
  var k=Object.keys(WF_CODE).filter(function(x){return WF_CODE[x]===c})[0]; return k||'';
}
function mtScope(r){ var b=unitOf(r.emp); return r.wf.length?r.wf.map(function(id){ return ttLabel(id,b) }).join(', '):tx('Mọi loại đơn','All ticket types') }
function mtWfOpts(){
  var out=ttList(MTV.unit).map(function(t){ return [t.id,t.n] }), has={};
  out.forEach(function(o){ has[o[0]]=1 });
  MATRIX.forEach(function(r){ if(unitOf(r.emp)!==MTV.unit) return; r.wf.forEach(function(id){ if(!has[id]){ has[id]=1; out.push([id,ttLabel(id,MTV.unit)]) } }) });
  return out;
}
(function(){ var o=openMt; openMt=function(id){ o(id); if(MTE){ MTE.ttU='' } } })();
function ttUnit(u){ mtGrab(); MTE.ttU=u; MTE.ttDel=''; MTE.ttErr=''; drawMt() }

function mtTTBox(ro){
  var base=(MTE.emp&&userBy(MTE.emp))?unitOf(MTE.emp):MTV.unit, U=MTE.ttU||base, L=ttList(U);
  var sel=MTE.wfs.length?'<div class="tt-sel"><span class="lb">'+tx('Đã chọn','Selected')+' ('+MTE.wfs.length+')</span>'+MTE.wfs.map(function(id){
      return '<span class="tt-chip">'+esc(ttLabel(id,base))+(ro?'':'<button title="'+tx('Bỏ chọn','Unselect')+'" aria-label="'+tx('Bỏ chọn ','Unselect ')+esc(ttName(id))+'" onclick="mtWf(\''+id+'\',false)">'+svg(I.x)+'</button>')+'</span>' }).join('')+'</div>':'';
  return '<div class="fieldset tt-box">'+sel+
    L.map(function(w){
      var on=MTE.wfs.indexOf(w.id)>=0;
      if(MTE.ttDel===w.id) return '<div class="tt-row tt-cf"><span>'+tx('Xoá loại ticket “','Delete ticket type “')+'<b>'+esc(w.n)+'</b>'+tx('” khỏi danh mục của ','” from the list of ')+esc(unitName(U))+'?</span>'+
        '<button class="btn sm dgr" onclick="ttDelGo(\''+w.id+'\')">'+tx('Xoá','Delete')+'</button><button class="btn sm" onclick="MTE.ttDel=\'\';mtGrab();drawMt()">'+tx('Huỷ','Cancel')+'</button></div>';
      return '<div class="tt-row"><label class="ck"><input type="checkbox" '+(on?'checked':'')+(ro?' disabled':'')+' onchange="mtWf(\''+w.id+'\',this.checked)"><span>'+esc(w.n)+'</span></label>'+
        (ro?'':'<button class="xb tt-x" title="'+tx('Xoá loại ticket khỏi danh mục','Remove this ticket type')+'" aria-label="'+tx('Xoá ','Remove ')+esc(w.n)+'" onclick="MTE.ttDel=\''+w.id+'\';MTE.ttErr=\'\';mtGrab();drawMt()">'+svg(I.x)+'</button>')+'</div>';
    }).join('')+
    (L.length?'':'<div class="ap-empty">'+tx('Đơn vị chưa có loại ticket nào','This unit has no ticket type yet')+'</div>')+
    (MTE.ttErr?'<span class="hint" style="color:var(--danger)">'+esc(MTE.ttErr)+'</span>':'')+
    '</div>';
}
function ttAdd(){
  mtGrab(); var U=MTE.ttU||MTV.unit, e=document.getElementById('mt_ttn'), n=(e?e.value:'').trim(), L=ttList(U);
  MTE.ttNew=n; MTE.ttErr='';
  if(!n) MTE.ttErr=tx('Nhập tên loại ticket','Enter a ticket type name');
  else if(L.some(function(x){ return x.n.toLowerCase()===n.toLowerCase() })) MTE.ttErr=tx(unitName(U)+' đã có loại ticket “'+n+'”',unitName(U)+' already has “'+n+'”');
  if(MTE.ttErr) return drawMt();
  var code=ttCodeGen(n)||'LOAI_TICKET', c=code, i=2; while(L.some(function(x){return x.code===c})){ c=code+'_'+i; i++ }
  var id='tt-'+U+'-'+c.toLowerCase(); while(ttById(id)) id+='-x';
  L.push({id:id,n:n,code:c}); WF_CODE[id]=c;
  if(MTE.wfs.indexOf(id)<0) MTE.wfs.push(id);
  MTE.ttNew='';
  auditLog(tx('Thêm loại ticket','Add ticket type'),unitName(U)+' · '+n+' ('+c+')');
  drawMt(); toast(tx('Đã thêm loại ticket','Ticket type added'),n+' · '+unitName(U));
}
function ttDelGo(id){
  mtGrab(); var U=MTE.ttU||MTV.unit, L=ttList(U), t=L.filter(function(x){return x.id===id})[0]; MTE.ttDel='';
  if(!t) return drawMt();
  var used=MATRIX.filter(function(r){ return r.id!==MTE.id&&r.wf.indexOf(id)>=0 });
  if(used.length){ MTE.ttErr=tx('Không xoá được “'+t.n+'” — đang dùng ở '+used.length+' dòng ma trận khác ('+used.map(function(r){return r.id}).join(', ')+')','Cannot remove “'+t.n+'” — used by '+used.length+' other matrix row(s) ('+used.map(function(r){return r.id}).join(', ')+')'); return drawMt() }
  L.splice(L.indexOf(t),1);
  var k=MTE.wfs.indexOf(id); if(k>=0) MTE.wfs.splice(k,1);
  if(MTV.wf===id) MTV.wf='';
  MTE.ttErr='';
  auditLog(tx('Xoá loại ticket','Remove ticket type'),unitName(U)+' · '+t.n+' ('+t.code+')');
  drawMt(); toast(tx('Đã xoá loại ticket','Ticket type removed'),t.n+' · '+unitName(U));
}
/* =====================================================================
   v40 — Xuất bản / Vô hiệu hoá: hộp xác nhận giữa màn hình (không mở ngăn bên)
   ===================================================================== */
function cfmClose(){ var d=document.getElementById('cfm'); if(d){if(d.open)d.close();d.remove()} }
function cfmShow(o){
  cfmClose();
  var d=document.createElement('dialog'); d.id='cfm'; d.className='cfm-bg'; d.setAttribute('aria-labelledby','cfmT');
  d.innerHTML='<div class="cfm'+(o.wide?' wide':'')+'">'+
    '<h3 id="cfmT">'+o.title+'</h3><div class="cfm-b">'+o.body+'</div>'+
    '<div class="cfm-f"><button class="btn" id="cfmNo">'+(o.no||tx('Huỷ','Cancel'))+'</button>'+
    (o.ok?'<button class="btn '+(o.okCls||'pri')+'" id="cfmOk">'+o.ok+'</button>':'')+'</div></div>';
  document.body.appendChild(d); d.showModal();
  d.addEventListener('mousedown',function(e){ if(e.target===d) cfmClose() });
  document.getElementById('cfmNo').onclick=cfmClose;
  var ok=document.getElementById('cfmOk');
  if(ok)ok.onclick=function(){ cfmClose(); o.onOk() }; document.getElementById('cfmNo').focus();
}
document.addEventListener('keydown',function(e){
  if(e.key==='Escape'&&document.getElementById('cfm')){ e.preventDefault(); e.stopImmediatePropagation(); cfmClose() }
},true);

/* ---------- Xuất bản ---------- */
var publishGo=publishDef;
function pubNextVer(w){
  if(!w) return '';
  var n=(w.vers||[]).length, first=n&&w.vers[0].s==='draft'&&!w.pub;
  return 'v'+(w.v||1)+'.'+(first?n:n+1);
}
publishDef=function(){
  var errs=publishErrors(), w=wfById(DSN.id), nm=w?w.n:def().n;
  if(errs.length){
    cfmShow({wide:1,title:tx('Chưa xuất bản được','Cannot publish yet'),no:tx('Đóng','Close'),
      body:'<p>'+tx('Quy trình <b>'+esc(nm)+'</b> còn '+errs.length+' lỗi cần sửa trước khi xuất bản:','Workflow <b>'+esc(nm)+'</b> has '+errs.length+' issue(s) to fix before publishing:')+'</p>'+
        '<ul class="cfm-err">'+errs.map(function(e){
          return '<li><div><b>'+esc(e.n.name)+'</b><span>'+esc(e.m)+'</span></div><button class="btn xs" onclick="cfmClose();'+(e.flow?'pubGotoLn':'pubGoto')+'(\''+e.n.id+'\')">'+tx('Đi tới node','Go to node')+'</button></li>';
        }).join('')+'</ul>'});
    return;
  }
  cfmShow({title:tx('Xuất bản quy trình','Publish workflow'),ok:tx('Xác nhận','Confirm'),onOk:publishGo,
    body:'<p>'+tx('Bạn có chắc muốn xuất bản quy trình <b>'+esc(nm)+'</b> thành phiên bản <b>'+pubNextVer(w)+'</b>?','Are you sure you want to publish workflow <b>'+esc(nm)+'</b> as version <b>'+pubNextVer(w)+'</b>?')+'</p>'});
};

/* ---------- Vô hiệu hoá ---------- */
function openDisableWf(){
  var w=wfById(DSN.id); if(!w) return;
  cfmShow({title:tx('Vô hiệu hoá quy trình','Disable workflow'),ok:tx('Xác nhận','Confirm'),onOk:doDisableWf,
    body:'<p>'+tx('Bạn có chắc muốn vô hiệu hoá quy trình <b>'+esc(w.n)+'</b>?','Are you sure you want to disable workflow <b>'+esc(w.n)+'</b>?')+'</p>'});
}

function pubGotoLn(id){ closeDrawer(); DSN.inspOn=true; DSN.sel=id; DSN.tab='ln'; renderNodes(); renderInsp() }
/* =====================================================================
   v41 — "Lưu bản nháp" chỉ dành cho quy trình mới tạo, chưa từng xuất bản.
   Quy trình đã xuất bản (Đang chạy / Đã huỷ): sửa xong thì Xuất bản phiên bản mới.
   ===================================================================== */
function wfDraftable(w){
  w=w||wfById(DSN.id); if(!w) return true;
  return w.st==='draft'&&!w.pub&&!(w.vers||[]).some(function(v){ return v.s!=='draft' });
}
function dsnDraftSync(){
  if(wfDraftable()) return;
  var b=document.querySelector('#view .dsn-bar button[onclick="saveDef()"]'); if(b) b.parentNode.removeChild(b);
}
(function(){
  var cp=canvasPage; canvasPage=function(){ cp.apply(this,arguments); dsnDraftSync() };
  var pg=publishGo; publishGo=function(){ pg.apply(this,arguments); dsnDraftSync();
    var w=wfById(DSN.id), pb=document.querySelector('#view .dsn-bar button[onclick="publishDef()"]');
    if(w&&w.st==='run'&&pb&&!document.getElementById('wfOffBtn'))
      pb.insertAdjacentHTML('beforebegin','<button class="btn dgr" id="wfOffBtn" onclick="openDisableWf()">'+svg('<circle cx="12" cy="12" r="8.5"/><path d="M6 6l12 12"/>')+tx('Vô hiệu hoá','Disable')+'</button>');
  };
  var sd=saveDef; saveDef=function(){ if(!wfDraftable()) return; sd.apply(this,arguments) };
  var md=markDirty; markDirty=function(){ md.apply(this,arguments);
    if(!wfDraftable()){ var e=document.getElementById('dsnState'); if(e) e.innerHTML='<span class="chip c-wait">'+tx('Có thay đổi chưa xuất bản','Unpublished changes')+'</span>' } };
  var au=askUnit; askUnit=function(u){
    if(u!==CUR_UNIT&&page==='thiet-ke'&&DSN.view!=='lib'&&DSN.dirty&&!wfDraftable()){
      renderUnit();
      cfmShow({title:tx('Đổi sang đơn vị ','Switch to unit ')+esc(unitName(u)),ok:tx('Bỏ thay đổi','Discard changes'),no:tx('Ở lại','Stay'),
        onOk:function(){ DSN.dirty=0; setUnit(u) },
        body:'<p>'+tx('Quy trình <b>'+esc(def().n)+'</b> đang chạy và còn thay đổi chưa xuất bản. Đổi đơn vị sẽ bỏ các thay đổi này.','Workflow <b>'+esc(def().n)+'</b> is running and has unpublished changes. Switching unit discards them.')+'</p>'});
      return;
    }
    return au.apply(this,arguments);
  };
})();
/* dữ liệu mẫu: "Xin thôi việc" là quy trình mới, chưa từng xuất bản */
(function(){ var w=wfById('resignation'); if(!w) return; w.v=1; w.pub=0; w.st='draft'; w.vers=(w.vers||[]).filter(function(x){return x.s==='draft'}).slice(0,1); if(w.vers[0]) w.vers[0].v=1; if(DEFS[w.id]){ DEFS[w.id].pub=0; DEFS[w.id].v=1 } })();
/* =====================================================================
   v42 — (1) User Group: "Người giữ vai trò" quay về cách của v34
             (ô gõ họ tên/account chọn từ danh bạ + Thêm người, bỏ nút sửa)
         (2) Xuất bản: chặn khi luồng sai cấu trúc
   ===================================================================== */
function ugOpen(code){
  var r=code?ugRoles().filter(function(x){return x.code===code})[0]:null;
  UGE={code:code||'',name:r?posName(r.code):'',mcode:r?r.code:'',codeTouched:!!r,mo:r?(r.mo||''):'',members:r?r.members.slice():[],add:'',err:{}};
  ugDraw();
}
function ugGrab(){
  var g=function(id){ return document.getElementById(id) };
  if(g('ug_name')) UGE.name=g('ug_name').value;
  if(g('ug_code')&&!UGE.code) UGE.mcode=g('ug_code').value;
  if(g('ug_mo')) UGE.mo=g('ug_mo').value;
  if(g('ug_add')) UGE.add=g('ug_add').value;
}
function ugDraw(){
  var ed=!!UGE.code, E=UGE.err, req=' <span style="color:var(--danger)">*</span>';
  var hint=function(k){ return E[k]?'<span class="hint" style="color:var(--danger)">'+esc(E[k])+'</span>':'' };
  var opts=USERS.filter(function(x){ return uStat(x.u)==='on'&&x.donvi===UGV.unit&&UGE.members.indexOf(x.u)<0 });
  showDrawer('<div class="drw-h"><div style="flex:1"><h2>'+(ed?tx('Sửa vai trò','Edit role'):tx('Thêm vai trò','Add role'))+'</h2>'+
    '<div class="meta"><span>'+tx('Đơn vị ','Unit ')+esc(unitName(UGV.unit))+'</span></div></div>'+
    '<button class="x-btn" onclick="closeDrawer()">'+svg(I.x)+'</button></div><div class="drw-b">'+
    '<div class="field"><label for="ug_name">'+tx('Tên vai trò','Role name')+req+'</label>'+
    '<input class="inp'+(E.name?' bad':'')+'" id="ug_name" value="'+esc(UGE.name)+'" placeholder="'+tx('Ví dụ: Trưởng phòng Hành chính','e.g. Head of Administration')+'" maxlength="80" oninput="ugNameIn(this.value)" autocomplete="off">'+hint('name')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_code">'+tx('Mã vai trò','Role code')+req+'</label>'+
    '<input class="inp mono'+(E.code?' bad':'')+'" id="ug_code" value="'+esc(UGE.mcode)+'" placeholder="TRUONG_PHONG_HC" maxlength="40"'+(ed?' disabled':' oninput="UGE.codeTouched=1;this.value=this.value.toUpperCase()"')+'>'+hint('code')+'</div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_mo">'+tx('Mô tả','Description')+'</label>'+
    '<textarea class="inp" id="ug_mo" rows="2" maxlength="250" placeholder="'+tx('Vai trò này duyệt những gì','What this role approves')+'">'+esc(UGE.mo)+'</textarea></div>'+
    '<div class="field" style="margin-top:12px"><label for="ug_add">'+tx('Người giữ vai trò','People in this role')+'</label>'+
    '<div class="ug-addr"><input class="inp" id="ug_add" list="ugUserList" value="'+esc(UGE.add)+'" placeholder="'+tx('Gõ họ tên hoặc account…','Type a name or account…')+'" autocomplete="off" onkeydown="if(event.key===\'Enter\'){event.preventDefault();ugAddM()}">'+
    '<button class="btn" onclick="ugAddM()">'+svg(I.plus)+tx('Thêm người','Add person')+'</button></div>'+
    '<datalist id="ugUserList">'+opts.map(function(x){return '<option value="'+esc(x.n+' · '+x.u)+'">'}).join('')+'</datalist>'+hint('add')+
    '<div class="ug-mem">'+(UGE.members.length?UGE.members.map(function(a,i){
      return '<div class="ug-m"><div><b>'+esc(ugNm(a))+'</b><span class="mono">'+esc(a)+'</span></div><button class="xb" title="'+tx('Bỏ khỏi vai trò','Remove from role')+'" aria-label="'+tx('Bỏ ','Remove ')+esc(ugNm(a))+'" onclick="ugRmM('+i+')">'+svg(I.x)+'</button></div>';
    }).join(''):'<div class="ap-empty">'+tx('Chưa có người nào','No one yet')+'</div>')+'</div></div></div>'+
    '<div class="drw-f"><button class="btn pri" onclick="ugSave()">'+svg(I.save)+(ed?tx('Lưu','Save'):tx('Thêm vai trò','Add role'))+'</button>'+
    '<button class="btn" style="margin-left:auto" onclick="closeDrawer()">'+tx('Huỷ','Cancel')+'</button></div>');
  setTimeout(function(){ var e=document.getElementById(ed?'ug_add':'ug_name'); if(e&&!UGE.add) e.focus() },50);
}
function ugAddM(){
  ugGrab(); UGE.err={};
  var u=apParseUser(UGE.add);
  if(!UGE.add.trim()) UGE.err.add=tx('Chọn một người trong danh bạ','Pick a person from the directory');
  else if(!u) UGE.err.add=tx('Không tìm thấy trong danh bạ','Not found in the directory');
  else if(uStat(u.u)!=='on') UGE.err.add=tx('Người này đã nghỉ việc hoặc bị khoá account','This person has left or is locked');
  else if(UGE.members.indexOf(u.u)>=0) UGE.err.add=tx('Người này đã có trong vai trò','Already in this role');
  else { UGE.members.push(u.u); UGE.add='' }
  ugDraw(); setTimeout(function(){ var e=document.getElementById('ug_add'); if(e) e.focus() },30);
}
function ugRmM(i){ ugGrab(); UGE.members.splice(i,1); UGE.err={}; ugDraw() }

/* ---------- Kiểm tra cấu trúc luồng trước khi xuất bản ---------- */
var LB_OK=['Duyệt','Approve'], LB_NO=['Từ chối','Reject'], LB_T=['Đúng','True'], LB_F=['Sai','False'];
function flowErrors(){
  var d=def(), N=d.nodes, L=d.links, errs=[], has=function(arr,lbs){ return arr.some(function(l){ return lbs.indexOf(l.lbl)>=0 }) };
  var outs={}, ins={}; N.forEach(function(n){ outs[n.id]=[]; ins[n.id]=[] });
  L.forEach(function(l){ if(outs[l.f]&&ins[l.to]){ outs[l.f].push(l); ins[l.to].push(l) } });
  /* node tới được Kết thúc: duyệt ngược từ các node Kết thúc */
  var reach={}, st=N.filter(function(n){return n.t==='end'}).map(function(n){return n.id});
  st.forEach(function(id){ reach[id]=1 });
  while(st.length){ var id=st.pop(); (ins[id]||[]).forEach(function(l){ if(!reach[l.f]){ reach[l.f]=1; st.push(l.f) } }) }
  var hasEnd=N.some(function(n){return n.t==='end'});
  N.forEach(function(n){
    var o=outs[n.id], i=ins[n.id], m=[];
    if(n.t==='start'){
      if(!o.length) m.push(tx('Bắt đầu chưa có đường ra','The Start node has no outgoing link'));
      if(!hasEnd) m.push(tx('Quy trình chưa có node Kết thúc','The workflow has no End node'));
    } else {
      if(!i.length) m.push(tx('Node chưa có đường vào','The node has no incoming link'));
      if(n.t!=='end'&&!o.length) m.push(tx('Node chưa có đường ra','The node has no outgoing link'));
    }
    if(n.t==='task'){
      if(o.length&&!has(o,LB_OK)) m.push(tx('Bước duyệt thiếu nhánh Duyệt','The approval step is missing the Approve branch'));
      if(o.length&&!has(o,LB_NO)) m.push(tx('Bước duyệt thiếu nhánh Từ chối','The approval step is missing the Reject branch'));
    }
    if(n.t==='gate'){
      if(o.length&&!has(o,LB_T)) m.push(tx('Điều kiện thiếu nhánh Đúng','The condition is missing the True branch'));
      if(o.length&&!has(o,LB_F)) m.push(tx('Điều kiện thiếu nhánh Sai','The condition is missing the False branch'));
    }
    if(hasEnd&&n.t!=='end'&&o.length&&!reach[n.id]) m.push(tx('Từ node này không đi tới được node Kết thúc','No path from this node reaches an End node'));
    m.forEach(function(x){ errs.push({n:n,m:x,flow:1}) });
  });
  return errs;
}
(function(){
  var pe=publishErrors;
  publishErrors=function(){
    var f=flowErrors(), c=pe.apply(this,arguments);
    return f.concat(c);
  };
})();
/* =====================================================================
   v43 — Ô gợi ý (họ tên / account): thay danh sách mặc định của trình duyệt
   (datalist, hiện nền đen trên Windows) bằng hộp gợi ý trắng, bo góc, lọc khi gõ
   ===================================================================== */
(function(){
  var pop=null, cur=null, idx=-1, items=[];
  function norm(s){ return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase() }
  function strip(root){ (root.querySelectorAll?root:document).querySelectorAll('input[list]').forEach(function(i){ i.setAttribute('data-list',i.getAttribute('list')); i.removeAttribute('list') }) }
  function opts(inp){ var dl=document.getElementById(inp.getAttribute('data-list')); return dl?[].slice.call(dl.options).map(function(o){return o.value}):[] }
  function close(){ if(pop){ pop.parentNode&&pop.parentNode.removeChild(pop); pop=null } idx=-1 }
  function place(){
    if(!pop||!cur||!document.body.contains(cur)){ close(); return }
    var r=cur.getBoundingClientRect(), w=Math.min(Math.max(r.width*0.62,280),r.width);
    pop.style.width=w+'px'; pop.style.left=(r.left+Math.min(44,r.width-w))+'px';
    var h=pop.offsetHeight, below=window.innerHeight-r.bottom;
    if(below<h+16&&r.top>below){ pop.classList.add('up'); pop.style.top=(r.top-h-10)+'px' } else { pop.classList.remove('up'); pop.style.top=(r.bottom+10)+'px' }
  }
  function render(){
    var q=norm(cur.value).trim();
    items=opts(cur).filter(function(v){ return !q||norm(v).indexOf(q)>=0 }).slice(0,60);
    if(!items.length){ close(); return }
    if(idx>=items.length) idx=items.length-1;
    if(!pop){ pop=document.createElement('div'); pop.className='acx'; pop.setAttribute('role','listbox'); document.body.appendChild(pop);
      pop.addEventListener('mousedown',function(e){ e.preventDefault(); var t=e.target.closest('.acx-i'); if(t) choose(+t.getAttribute('data-i')) }) }
    pop.innerHTML='<div class="acx-l">'+items.map(function(v,i){ return '<div class="acx-i'+(i===idx?' on':'')+'" role="option" data-i="'+i+'">'+esc(v)+'</div>' }).join('')+'</div>';
    place();
    var on=pop.querySelector('.acx-i.on'); if(on) on.scrollIntoView({block:'nearest'});
  }
  function choose(i){
    var v=items[i], inp=cur; if(v==null||!inp) return;
    inp.value=v; close();
    inp.dispatchEvent(new Event('input',{bubbles:true})); inp.dispatchEvent(new Event('change',{bubbles:true}));
    close(); inp.focus();
  }
  function isAc(t){ return t&&t.tagName==='INPUT'&&t.hasAttribute('data-list') }
  document.addEventListener('input',function(e){ if(isAc(e.target)){ cur=e.target; idx=-1; render() } },true);
  document.addEventListener('click',function(e){ if(isAc(e.target)){ cur=e.target; render() } else if(!e.target.closest||!e.target.closest('.acx')) close() },true);
  document.addEventListener('focusout',function(e){ if(isAc(e.target)) setTimeout(function(){ if(document.activeElement!==cur) close() },120) },true);
  document.addEventListener('keydown',function(e){
    if(!pop||!isAc(e.target)) return;
    if(e.key==='ArrowDown'){ e.preventDefault(); idx=Math.min(items.length-1,idx+1); render() }
    else if(e.key==='ArrowUp'){ e.preventDefault(); idx=Math.max(0,idx-1); render() }
    else if(e.key==='Enter'&&idx>=0){ e.preventDefault(); e.stopImmediatePropagation(); choose(idx) }
    else if(e.key==='Escape'){ e.preventDefault(); e.stopImmediatePropagation(); close() }
  },true);
  window.addEventListener('resize',place); document.addEventListener('scroll',function(){ place() },true);
  strip(document);
  new MutationObserver(function(ms){ ms.forEach(function(m){ m.addedNodes.forEach(function(n){ if(n.nodeType===1){ if(n.matches&&n.matches('input[list]')) strip(n.parentNode||document); else strip(n) } }) }) })
    .observe(document.body,{childList:true,subtree:true});
})();
/* =====================================================================
   v44 — Người cập nhật / xuất bản là người cụ thể (họ tên + account),
   không dùng tài khoản chung "Quản trị hệ thống · admin"
   ===================================================================== */
(function(){
  /* người đang đăng nhập cổng Admin trong bản demo */
  ACTORS.grp.acc='huongntt'; ACTORS.hr.acc='hangvt'; ACTORS.des.acc='quantm';
  var OLD={'admin':1,'hr.fsoft':1,'designer1':1};
  var by={'leave-approval-demo':'quantm','salary-increase-demo':'quantm','it-ticket':'quantm'};
  WFS.forEach(function(w){
    (w.vers||[]).forEach(function(v){ if(OLD[v.w]) v.w=by[w.id]||'huongntt' });
    if(w.mod&&OLD[w.mod.acc]) w.mod.acc=by[w.id]||'huongntt';
  });
  var map={'admin':'huongntt','hr.fsoft':'hangvt','designer1':'quantm'};
  MATRIX.forEach(function(r){ (r.log||[]).forEach(function(l){ if(map[l.u]) l.u=map[l.u] }) });
  if(typeof AUDIT!=='undefined') AUDIT.forEach(function(a){ if(map[a.u]) a.u=map[a.u] });
})();
/* =====================================================================
   v45 — Xoá quy trình
   · Nháp chưa từng xuất bản, hoặc Đã huỷ và không còn ticket đang xử lý → xoá được
   · Đang chạy → phải Vô hiệu hoá trước
   · Đang được dùng ở Ma trận phê duyệt → phải bỏ khỏi các dòng ma trận trước
   ===================================================================== */
var I_TRASH='<path d="M4 7h16M10 11v6M14 11v6M6 7l1 12a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-12M9 7V4h6v3"/>';
function wfDelBlock(w){
  if(w.st==='run') return {k:'run',m:tx('Quy trình đang chạy nên chưa xoá được. Hãy <b>Vô hiệu hoá</b> quy trình trước, khi không còn ticket đang xử lý thì mới xoá.','This workflow is running and cannot be deleted. <b>Disable</b> it first; you can delete it once no ticket is in progress.')};
  if(w.run>0) return {k:'tk',m:tx('Còn <b>'+w.run+' ticket</b> đang xử lý theo quy trình này. Chờ các ticket này hoàn tất rồi mới xoá.','<b>'+w.run+' ticket(s)</b> are still in progress on this workflow. Wait until they finish before deleting.')};
  var rows=MATRIX.filter(function(r){ return r.wf.indexOf(w.id)>=0 });
  if(rows.length) return {k:'mt',m:tx('Quy trình đang được chọn ở <b>'+rows.length+' dòng Ma trận phê duyệt</b> ('+rows.map(function(r){return esc(uname(r.emp))}).join(', ')+'). Bỏ quy trình khỏi các dòng này trước khi xoá.','The workflow is selected in <b>'+rows.length+' approval matrix row(s)</b> ('+rows.map(function(r){return esc(uname(r.emp))}).join(', ')+'). Remove it from those rows before deleting.')};
  return null;
}
function openDelWf(id){
  var w=wfById(id); if(!w) return;
  var b=wfDelBlock(w);
  if(b){ cfmShow({title:tx('Chưa xoá được quy trình','Cannot delete this workflow'),no:tx('Đóng','Close'),body:'<p>'+b.m+'</p>'}); return }
  cfmShow({title:tx('Xoá quy trình','Delete workflow'),ok:tx('Xoá','Delete'),okCls:'dgr-s',onOk:function(){ doDelWf(id) },
    body:'<p>'+tx('Bạn có chắc muốn xoá quy trình <b>'+esc(w.n)+'</b>? Bản vẽ và lịch sử phiên bản sẽ bị xoá, không khôi phục được.','Are you sure you want to delete workflow <b>'+esc(w.n)+'</b>? Its drawing and version history will be removed and cannot be restored.')+
      (w.luot>0?'<p class="cfm-sub">'+tx('Các ticket đã hoàn tất trước đây vẫn được giữ để tra cứu.','Tickets completed earlier are kept for reference.')+'</p>':'')});
}
function doDelWf(id){
  var w=wfById(id); if(!w||wfDelBlock(w)) return;
  if(window.workflowForgetChanges)window.workflowForgetChanges(id);
  WFS.splice(WFS.indexOf(w),1); delete DEFS[id];
  Object.keys(MT_TT).forEach(function(u){ MT_TT[u]=MT_TT[u].filter(function(t){ return t.id!==id }) });
  if(typeof MTV!=='undefined'&&MTV.wf===id) MTV.wf='';
  auditLog(tx('Xoá quy trình','Delete workflow'),unitName(w.donvi)+' · '+w.n+' ('+id+') · '+wfVer(w));
  closeDrawer();
  if(DSN.id===id) DSN.id=null;
  openLib();
  toast(tx('Đã xoá quy trình','Workflow deleted'),esc(w.n));
}
/* nút xoá trên thẻ quy trình */
(function(){
  var lp=libPage;
  libPage=function(){
    var r=lp.apply(this,arguments);
    document.querySelectorAll('#view .wfc').forEach(function(c){
      var m=(c.getAttribute('onclick')||'').match(/\('([^']+)'\)/), a=c.querySelector('.wfc-acts'); if(!m||!a||a.querySelector('.wfc-del')) return;
      var w=wfById(m[1]); if(!w) return;
      a.insertAdjacentHTML('beforeend','<button class="xb look wfc-del" title="'+tx('Xoá quy trình','Delete workflow')+'" aria-label="'+tx('Xoá ','Delete ')+esc(w.n)+'" onclick="event.stopPropagation();openDelWf(\''+w.id+'\')">'+svg(I_TRASH)+'</button>');
    });
    return r;
  };
})();
/* nút xoá trong ngăn Sửa thông tin quy trình */
(function(){
  var dw=drawWfInfo;
  drawWfInfo=function(){
    var r=dw.apply(this,arguments);
    var f=document.querySelector('#drw .drw-f'), id=(typeof WI!=='undefined'&&WI)?WI.id:null;
    if(f&&id&&!f.querySelector('.wfi-del')) f.querySelector('.btn.pri').insertAdjacentHTML('afterend','<button class="btn dgr wfi-del" onclick="openDelWf(\''+id+'\')">'+svg(I_TRASH)+tx('Xoá quy trình','Delete workflow')+'</button>');
    return r;
  };
})();

/* UX refinement: one guard covers module navigation and the library Back button. */
(function(){
 var pending={};
 window.workflowForgetChanges=function(id){delete pending[id];if(DSN.id===id)DSN.dirty=0};
 var oldMark=markDirty;markDirty=function(){oldMark.apply(this,arguments);pending[DSN.id]=true};
 var oldSave=saveDef;saveDef=function(){var result=oldSave.apply(this,arguments);if(!DSN.dirty)delete pending[DSN.id];return result};
 var oldPublish=publishGo;publishGo=function(){var result=oldPublish.apply(this,arguments);if(!DSN.dirty)delete pending[DSN.id];return result};
 var oldSwitch=switchDef;switchDef=function(id){if(DSN.dirty)pending[DSN.id]=true;var result=oldSwitch.apply(this,arguments);DSN.dirty=pending[id]?1:0;return result};
 var oldLibrary=openLib;
 function guard(proceed){
   if(page!=='thiet-ke'||DSN.view==='lib'||!DSN.dirty){proceed();return}
   var draft=wfDraftable();
   cfmShow({title:tx('Rời màn thiết kế?','Leave the designer?'),no:tx('Ở lại','Stay'),ok:draft?tx('Lưu nháp và chuyển','Save draft and continue'):tx('Chuyển màn hình','Continue'),
    body:'<p>'+tx('Quy trình <b>'+esc(def().n)+'</b> còn thay đổi '+(draft?'chưa lưu. Lưu bản nháp trước khi chuyển.':'chưa xuất bản. Thay đổi được giữ trong phiên này nhưng chưa áp dụng cho ticket mới.'),'Workflow <b>'+esc(def().n)+'</b> has '+(draft?'unsaved changes. Save the draft before leaving.':'unpublished changes. Changes remain in this session and do not apply to new tickets yet.'))+'</p>',
    onOk:function(){if(draft)saveDef();else pending[DSN.id]=true;proceed()}});
 }
 openLib=function(){guard(function(){oldLibrary()})};
 workflowNavigate=function(k){guard(function(){if(k==='thiet-ke')oldLibrary();else go(k)})};
 var oldSetUnit=setUnit;setUnit=function(){if(!DSN.dirty)delete pending[DSN.id];return oldSetUnit.apply(this,arguments)};
 window.addEventListener('beforeunload',function(e){if(!DSN.dirty)delete pending[DSN.id];if(DSN.dirty||Object.keys(pending).length){e.preventDefault();e.returnValue=''}});
 function fitDesigner(){var pane=document.querySelector('#view .dsn');if(!pane)return;var top=pane.getBoundingClientRect().top;pane.style.height=Math.max(260,window.innerHeight-top-24)+'px'}
 var oldCanvas=canvasPage;canvasPage=function(){oldCanvas.apply(this,arguments);requestAnimationFrame(fitDesigner)};
 window.addEventListener('resize',fitDesigner);
})();
function resetWorkflowFilters(){DSN.q='';DSN.f='all';libPage();var input=document.querySelector('.workflow-summary-toolbar .gsearch input');if(input)input.focus()}


renderUnit(); renderNav(); renderActor(); openLib();
